-- Perioperative Nursing mock exams — Day 1 and Day 2 (600 questions: 6 papers of 100).
-- Day 1  Morning: PON 413 Principles & Practice (40), PON 411 Anatomy & Physiology (30), GSM 402 Microbiology (30)
--        Afternoon: PAN 414 Anaesthesia (35), PAN 412 Pharmacology (30), PON 415 PACU (35)
--        Night: PON 416 General Surgery (40), PON 417 Trauma & Orthopaedics (30), PON 421 O&G Surgery (30)
-- Day 2  Morning: PON 423 Paediatric, Urology, Neurosurgery, Cardiothoracic, Reconstructive (20 each)
--        Afternoon: Maxillofacial 20, Ophthalmic 20, ENT 20, Radiology 15, Occupational Health 15, Theories 10
--        Night: Research 15, Nursing Process 15, Management 15, Ethico-legal 15, Entrepreneurship 10,
--               Computer 10, Behavioural Science 10, Use of English 10
-- The questions are added as hidden exam-only questions (not shown in the practice app). The 6 exams are
-- created for the PERIOPERATIVE section only (specialty = 'periop'), so Critical Care students never see them.
-- Times (Nigeria time) can be changed later on the admin page. Run update_specialties.sql first.
-- If an exam already exists, only its questions are updated. Safe to run more than once.
set lock_timeout = '5s';
begin;
alter table public.exam_exams add column if not exists specialty text not null default 'ccn';
create temporary table ponew (paper int, n int, source text, topic text, q text, opts jsonb, ans_idx int, exp text, category text, primary key (paper, n)) on commit drop;
select (select coalesce(max(id), 0) from public.questions) + row_number() over (order by d.paper, d.n), d.topic, d.source, d.q, d.opts, d.ans_idx, d.exp, d.category, '🩺', false
from ponew d
where not exists (select 1 from public.questions x where x.source = d.source and x.q = d.q);
update public.exam_exams set question_ids = (select array_agg(x.id order by d.n) from ponew d join public.questions x on x.source = d.source and x.q = d.q where d.paper = 1), instructions = 'Perioperative Nursing — Day 1 Morning. 100 questions: PON 413 · Principles & Practice of Perioperative Nursing, PON 411 · Anatomy & Physiology, GSM 402 · Microbiology & Infection Control. Choose the ONE best answer for each question. Each correct answer carries 1 mark. You have 100 minutes.', specialty = 'periop'
 where title = 'Perioperative Mock — Day 1 Morning (100 Questions)';
                               max_warnings, shuffle, all_candidates, attempts_allowed, proctor_level, specialty)
select 'Perioperative Mock — Day 1 Morning (100 Questions)', 'Perioperative Nursing — Day 1 Morning. 100 questions: PON 413 · Principles & Practice of Perioperative Nursing, PON 411 · Anatomy & Physiology, GSM 402 · Microbiology & Infection Control. Choose the ONE best answer for each question. Each correct answer carries 1 mark. You have 100 minutes.',
       timestamptz '2026-11-02 08:00:00+01', timestamptz '2026-11-02 10:00:00+01', 100, (select array_agg(x.id order by d.n) from ponew d join public.questions x on x.source = d.source and x.q = d.q where d.paper = 1),
       true, true, 100, true, true, 1, 'relaxed', 'periop'
where not exists (select 1 from public.exam_exams where title = 'Perioperative Mock — Day 1 Morning (100 Questions)');
update public.exam_exams set question_ids = (select array_agg(x.id order by d.n) from ponew d join public.questions x on x.source = d.source and x.q = d.q where d.paper = 2), instructions = 'Perioperative Nursing — Day 1 Afternoon. 100 questions: PAN 414 · Anaesthesia, PAN 412 · Pharmacology, PON 415 · Post-Anaesthesia Care (PACU). Choose the ONE best answer for each question. Each correct answer carries 1 mark. You have 100 minutes.', specialty = 'periop'
 where title = 'Perioperative Mock — Day 1 Afternoon (100 Questions)';
                               max_warnings, shuffle, all_candidates, attempts_allowed, proctor_level, specialty)
select 'Perioperative Mock — Day 1 Afternoon (100 Questions)', 'Perioperative Nursing — Day 1 Afternoon. 100 questions: PAN 414 · Anaesthesia, PAN 412 · Pharmacology, PON 415 · Post-Anaesthesia Care (PACU). Choose the ONE best answer for each question. Each correct answer carries 1 mark. You have 100 minutes.',
       timestamptz '2026-11-02 12:00:00+01', timestamptz '2026-11-02 14:00:00+01', 100, (select array_agg(x.id order by d.n) from ponew d join public.questions x on x.source = d.source and x.q = d.q where d.paper = 2),
       true, true, 100, true, true, 1, 'relaxed', 'periop'
where not exists (select 1 from public.exam_exams where title = 'Perioperative Mock — Day 1 Afternoon (100 Questions)');
update public.exam_exams set question_ids = (select array_agg(x.id order by d.n) from ponew d join public.questions x on x.source = d.source and x.q = d.q where d.paper = 3), instructions = 'Perioperative Nursing — Day 1 Night. 100 questions: PON 416 · General Surgery, PON 417 · Trauma & Orthopaedics, PON 421 · Obstetric & Gynaecological Surgery. Choose the ONE best answer for each question. Each correct answer carries 1 mark. You have 100 minutes.', specialty = 'periop'
 where title = 'Perioperative Mock — Day 1 Night (100 Questions)';
                               max_warnings, shuffle, all_candidates, attempts_allowed, proctor_level, specialty)
select 'Perioperative Mock — Day 1 Night (100 Questions)', 'Perioperative Nursing — Day 1 Night. 100 questions: PON 416 · General Surgery, PON 417 · Trauma & Orthopaedics, PON 421 · Obstetric & Gynaecological Surgery. Choose the ONE best answer for each question. Each correct answer carries 1 mark. You have 100 minutes.',
       timestamptz '2026-11-02 19:00:00+01', timestamptz '2026-11-02 21:00:00+01', 100, (select array_agg(x.id order by d.n) from ponew d join public.questions x on x.source = d.source and x.q = d.q where d.paper = 3),
       true, true, 100, true, true, 1, 'relaxed', 'periop'
where not exists (select 1 from public.exam_exams where title = 'Perioperative Mock — Day 1 Night (100 Questions)');
update public.exam_exams set question_ids = (select array_agg(x.id order by d.n) from ponew d join public.questions x on x.source = d.source and x.q = d.q where d.paper = 4), instructions = 'Perioperative Nursing — Day 2 Morning. 100 questions: PON 423 · Paediatric Surgery, PON 423 · Urology, PON 423 · Neurosurgery, PON 423 · Cardiothoracic Surgery, PON 423 · Reconstructive (Plastic) Surgery. Choose the ONE best answer for each question. Each correct answer carries 1 mark. You have 100 minutes.', specialty = 'periop'
 where title = 'Perioperative Mock — Day 2 Morning (100 Questions)';
                               max_warnings, shuffle, all_candidates, attempts_allowed, proctor_level, specialty)
select 'Perioperative Mock — Day 2 Morning (100 Questions)', 'Perioperative Nursing — Day 2 Morning. 100 questions: PON 423 · Paediatric Surgery, PON 423 · Urology, PON 423 · Neurosurgery, PON 423 · Cardiothoracic Surgery, PON 423 · Reconstructive (Plastic) Surgery. Choose the ONE best answer for each question. Each correct answer carries 1 mark. You have 100 minutes.',
       timestamptz '2026-11-03 08:00:00+01', timestamptz '2026-11-03 10:00:00+01', 100, (select array_agg(x.id order by d.n) from ponew d join public.questions x on x.source = d.source and x.q = d.q where d.paper = 4),
       true, true, 100, true, true, 1, 'relaxed', 'periop'
where not exists (select 1 from public.exam_exams where title = 'Perioperative Mock — Day 2 Morning (100 Questions)');
update public.exam_exams set question_ids = (select array_agg(x.id order by d.n) from ponew d join public.questions x on x.source = d.source and x.q = d.q where d.paper = 5), instructions = 'Perioperative Nursing — Day 2 Afternoon. 100 questions: PON 417 · Maxillofacial Surgery, PON 417 · Ophthalmic Surgery, PON 415 · Otorhinolaryngology (ENT), Radiology & Radiation Safety, GSO 410 · Occupational Health & Ergonomics, Nursing Theories. Choose the ONE best answer for each question. Each correct answer carries 1 mark. You have 100 minutes.', specialty = 'periop'
 where title = 'Perioperative Mock — Day 2 Afternoon (100 Questions)';
                               max_warnings, shuffle, all_candidates, attempts_allowed, proctor_level, specialty)
select 'Perioperative Mock — Day 2 Afternoon (100 Questions)', 'Perioperative Nursing — Day 2 Afternoon. 100 questions: PON 417 · Maxillofacial Surgery, PON 417 · Ophthalmic Surgery, PON 415 · Otorhinolaryngology (ENT), Radiology & Radiation Safety, GSO 410 · Occupational Health & Ergonomics, Nursing Theories. Choose the ONE best answer for each question. Each correct answer carries 1 mark. You have 100 minutes.',
       timestamptz '2026-11-03 12:00:00+01', timestamptz '2026-11-03 14:00:00+01', 100, (select array_agg(x.id order by d.n) from ponew d join public.questions x on x.source = d.source and x.q = d.q where d.paper = 5),
       true, true, 100, true, true, 1, 'relaxed', 'periop'
where not exists (select 1 from public.exam_exams where title = 'Perioperative Mock — Day 2 Afternoon (100 Questions)');
update public.exam_exams set question_ids = (select array_agg(x.id order by d.n) from ponew d join public.questions x on x.source = d.source and x.q = d.q where d.paper = 6), instructions = 'Perioperative Nursing — Day 2 Night. 100 questions: GST 403 · Research & Statistics, Nursing Process, Management, GSE 420 · Ethico-legal Aspects, GST 408 · Entrepreneurship, GST 405 · Computer Studies, GST 401 · Behavioural Science, GST 400 · Use of English. Choose the ONE best answer for each question. Each correct answer carries 1 mark. You have 100 minutes.', specialty = 'periop'
 where title = 'Perioperative Mock — Day 2 Night (100 Questions)';
                               max_warnings, shuffle, all_candidates, attempts_allowed, proctor_level, specialty)
select 'Perioperative Mock — Day 2 Night (100 Questions)', 'Perioperative Nursing — Day 2 Night. 100 questions: GST 403 · Research & Statistics, Nursing Process, Management, GSE 420 · Ethico-legal Aspects, GST 408 · Entrepreneurship, GST 405 · Computer Studies, GST 401 · Behavioural Science, GST 400 · Use of English. Choose the ONE best answer for each question. Each correct answer carries 1 mark. You have 100 minutes.',
       timestamptz '2026-11-03 19:00:00+01', timestamptz '2026-11-03 21:00:00+01', 100, (select array_agg(x.id order by d.n) from ponew d join public.questions x on x.source = d.source and x.q = d.q where d.paper = 6),
       true, true, 100, true, true, 1, 'relaxed', 'periop'
where not exists (select 1 from public.exam_exams where title = 'Perioperative Mock — Day 2 Night (100 Questions)');
select title, specialty, cardinality(question_ids) as questions, starts_at, ends_at
  from public.exam_exams where title like 'Perioperative Mock — Day %' order by starts_at;
commit;
