insert into ponew values
(1, 1, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'The intraoperative phase of perioperative care begins when the patient:', '["Arrives at theatre reception, and ends at extubation", "Receives premedication on the ward, and ends on return to the ward", "Signs the consent form, and ends at skin closure", "Is transferred onto the operating table, and ends on admission to the PACU"]'::jsonb, 3, 'Preoperative phase: decision for surgery until transfer to the OR table. Intraoperative: on the OR table until admission to PACU. Postoperative: PACU admission until follow-up evaluation is complete.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 2, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'During which phase of the WHO Surgical Safety Checklist do all team members introduce themselves by name and role?', '["Time Out (before skin incision)", "The ward pre-operative checklist", "Sign Out (before the patient leaves theatre)", "Sign In (before induction of anaesthesia)"]'::jsonb, 0, 'Time Out, just before incision, includes team introductions, confirmation of patient, site and procedure, anticipated critical events, antibiotic prophylaxis within 60 minutes and display of essential imaging.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 3, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'Confirming the patient''s identity, site, procedure and consent, the site marking, and the anaesthesia machine and pulse oximeter check is done at:', '["Sign Out — before the patient leaves the operating room", "Time Out — before skin incision", "Handover in the recovery room", "Sign In — before induction of anaesthesia"]'::jsonb, 3, 'Sign In is done with at least the nurse and anaesthetist before induction; it also covers known allergy, difficult airway/aspiration risk and risk of blood loss above 500 mL (7 mL/kg in children).', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 4, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'Instrument, swab and needle counts, specimen labelling and any equipment problems are confirmed during:', '["Handover — on arrival in the recovery room", "Sign Out — before the patient leaves the operating room", "Time Out — immediately before skin incision", "Sign In — before induction of anaesthesia"]'::jsonb, 1, 'At Sign Out the nurse confirms the procedure name, that counts are complete, specimens are correctly labelled, any equipment issues, and key concerns for recovery.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 5, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'Who should mark the operative site before surgery?', '["The anaesthetist, after the drapes are in place and before incision", "The theatre nurse, after the patient has been anaesthetised on the table", "The operating surgeon (or a delegate who will be present), with the patient awake", "The ward nurse, using the case notes, the night before the operation"]'::jsonb, 2, 'Site marking is done by the person performing the procedure, with an indelible mark that stays visible after prepping and draping, while the patient can confirm the side and site.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 6, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'The area of the operating suite where full surgical attire and masks are required because sterile procedures take place (operating rooms, scrub sinks) is the:', '["Semi-restricted zone", "Transitional (changing-room) zone", "Unrestricted zone", "Restricted zone"]'::jsonb, 3, 'Unrestricted: street clothes allowed (reception). Semi-restricted: theatre clothes and caps (corridors, sterile stores). Restricted: theatre clothes, caps AND masks where sterile items are open or scrubbed staff are present.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 7, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'Compared with the surrounding corridors, the air pressure inside an operating room should be:', '["Equal", "Negative", "Positive", "Alternating between positive and negative"]'::jsonb, 2, 'Positive pressure pushes air out of the theatre, so less clean corridor air (and airborne organisms) cannot flow in. Negative pressure is used for airborne-isolation rooms.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 8, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'Which is a principle of sterile technique?', '["The back of a sterile gown is sterile once it has been tied", "Only the top of a draped table is sterile; edges and below are not", "An item that falls below waist level stays sterile if untouched", "A sterile person may reach across an unsterile area if careful"]'::jsonb, 1, 'Sterile fields are kept in view and above waist/table level. The edges of a sterile wrapper or drape, the back of the gown, and anything below the waist or table level are unsterile.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 9, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'The parts of a sterile surgical gown that are considered sterile are:', '["The whole front from neck to hem, plus the entire sleeve up to the shoulder seam", "The front from chest to sterile-field level, and sleeves from 5 cm above the elbow to cuff", "The back of the gown once it has been tied by the circulating nurse", "The cuffs, the neckline and the axillae, because they are closest to the hands"]'::jsonb, 1, 'The neckline, shoulders, axillae, back and the area below the sterile field cannot be seen or kept sterile. Cuffs are covered by gloves and are treated as unsterile once the hands pass through.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 10, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'When performing a traditional surgical scrub with water, the hands are held:', '["Above elbow level, so water runs from the fingertips towards the elbows", "Below elbow level, so water runs from the elbows to the fingertips", "Down by the sides, and dried by shaking off the water", "Horizontally, at waist level"]'::jsonb, 0, 'Keeping the hands up lets water and soap flow from the cleanest area (hands) to the less clean area (elbows). Hands stay above the waist and away from the scrub attire.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 11, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'With an antimicrobial soap, the WHO-recommended duration of a surgical hand scrub is usually:', '["15–30 seconds, as for an alcohol hand rub", "At least 20 minutes for the first case only", "10–15 minutes for every scrub of the day", "2–5 minutes, as the manufacturer recommends"]'::jsonb, 3, 'Long scrubs (10 minutes or more) give no extra benefit and damage skin. Alcohol-based surgical hand rubs are an alternative, applied for the time the product specifies.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 12, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'Closed gloving is preferred when a scrub nurse gloves at the start of a case because:', '["It is faster than open gloving and so saves theatre time between cases", "It lets the nurse adjust the gown neckline after the gloves are on", "It needs no help at all from the circulating nurse during gowning", "The hands stay inside the sleeves, so bare skin never touches the gloves"]'::jsonb, 3, 'In closed gloving the fingers do not pass beyond the sleeve cuff until the glove is on. Open gloving is used when only gloves are changed or for procedures without a gown.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 13, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'Surgical counts of swabs, sharps and instruments should be performed:', '["Only at the end of the operation, after skin closure, by the scrub nurse alone", "Before incision, before closing a cavity, at skin closure, and when staff are relieved", "Only when the surgeon requests it or when the operation lasts over two hours", "Before incision and again after the patient has left the operating theatre"]'::jsonb, 1, 'The baseline count before incision allows later comparison. Counts are repeated at each layer of closure and at any permanent change of the scrub or circulating nurse, read aloud by both nurses.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 14, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'At the final count one abdominal swab is missing. The surgeon says the count must be wrong and starts closing the skin. The nurse should:', '["Recount once quietly and say nothing further if it is still missing", "Tell the surgeon at once, search, request an X-ray, and document and report it", "Wait until the patient reaches recovery, then order a plain X-ray", "Sign the count as correct, because the surgeon has overall responsibility"]'::jsonb, 1, 'A retained swab is a ''never event''. An unresolved count must be escalated before the patient leaves theatre: search, radiograph (swabs have radio-opaque markers), and complete an incident report.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 15, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'For monopolar electrosurgery, the patient return electrode (diathermy plate) should be placed on:', '["A clean, dry, well-perfused muscle mass near the site, away from bone and metal", "A bony prominence such as the iliac crest, because bone gives the firmest contact", "Hairy skin directly over a hip prosthesis, as long as it is well taped down", "The opposite side of the body, as far from the operative site as possible"]'::jsonb, 0, 'A large, well-vascularised contact area keeps current density low, preventing burns at the plate. Avoid hair, scar tissue, bony areas, fluid pooling and metal implants; the current path should not cross the heart or pacemaker.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 16, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'A patient with a cardiac pacemaker needs coagulation during surgery. The safest choice is:', '["Monopolar diathermy at the highest power setting for short bursts", "Bipolar diathermy, because current flows only between the two forceps tips", "Monopolar diathermy with the return plate on the opposite arm", "Monopolar diathermy with the return plate placed over the pacemaker"]'::jsonb, 1, 'Bipolar diathermy needs no return plate and the current stays between the tips, so it does not pass through the pacemaker. If monopolar is unavoidable, use short bursts, keep the current path away from the device, and have the device checked.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 17, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'An alcohol-based skin preparation has been used. To prevent a surgical fire, the nurse should:', '["Let the prep dry fully and fumes disperse before draping and diathermy", "Increase the oxygen flow under the drapes to dilute the alcohol vapour", "Drape immediately so that the alcohol fumes are trapped under the drapes", "Blot the prep with dry swabs and leave them on the skin under the drapes"]'::jsonb, 0, 'The fire triangle is an ignition source (diathermy, laser), fuel (alcohol, drapes, gauze) and an oxidiser (oxygen, nitrous oxide). Pooled or wet alcohol and trapped vapour under drapes can ignite.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 18, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'When placing an anaesthetised patient in the lithotomy position, the nurse should:', '["Lower the legs quickly at the end to restore their circulation", "Raise one leg first, then the other, so the pelvis stays stable", "Rest the outer side of the knee firmly against the stirrup post", "Raise and lower both legs together slowly, and pad the lateral knee"]'::jsonb, 3, 'Moving the legs separately can strain the pelvis and lumbar spine. Pressure on the fibular head injures the common peroneal nerve (foot drop). Lowering slowly prevents sudden hypotension as blood returns to the legs.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 19, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'In the prone position, the abdomen is allowed to hang free mainly to:', '["Make skin preparation and draping of the abdominal wall easier for the team", "Prevent pressure injury to the knees, iliac crests and the dorsum of the feet", "Increase intra-abdominal pressure so that the lumbar spine is better supported", "Reduce pressure on the IVC, improving venous return and ventilation and reducing bleeding"]'::jsonb, 3, 'Abdominal compression raises IVC and epidural venous pressure (more bleeding in spinal surgery), reduces cardiac output and impairs diaphragm movement. Eyes, breasts, genitals and the tube must also be protected.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 20, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'A recognised risk of the steep Trendelenburg (head-down) position is:', '["Lowered intraocular and intracranial pressure", "Raised intracranial and intraocular pressure, with stiffer lungs", "Improved functional residual capacity of the lungs", "Venous air embolism from the veins of the head and neck"]'::jsonb, 1, 'Head-down tilt pushes abdominal contents against the diaphragm (reduced FRC, compliance) and raises cerebral and ocular venous pressure; there is also a risk of the patient sliding and of regurgitation.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 21, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'Venous air embolism is most likely during surgery in which position?', '["Lateral position for a total hip replacement", "Sitting position for posterior fossa (neurosurgical) surgery", "Lithotomy position for a perineal operation", "Supine position for an open abdominal operation"]'::jsonb, 1, 'When the operative site is above the heart, the venous pressure there is below atmospheric pressure, so air can be drawn into open veins or dural sinuses. Monitor with end-tidal CO₂ (sudden fall) and precordial Doppler.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 22, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'To prevent brachial plexus injury in a supine patient with the arm on an arm board, the arm should be abducted no more than:', '["120 degrees", "135 degrees", "180 degrees", "90 degrees"]'::jsonb, 3, 'Abduction beyond 90° stretches the brachial plexus. The palm should face up (supinated) to protect the ulnar nerve at the elbow.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 23, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'For a pneumatic limb tourniquet, a commonly recommended maximum continuous inflation time is about:', '["4 hours", "30 minutes", "6 hours", "2 hours"]'::jsonb, 3, 'Prolonged ischaemia causes nerve and muscle damage. If longer is needed, the tourniquet is released for a period before re-inflation. Record inflation time, pressure, and alert the surgeon at set intervals.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 24, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'In a pre-vacuum steam steriliser running at 134 °C, the required holding (exposure) time is about:', '["3 minutes", "30 minutes", "60 minutes", "15 minutes"]'::jsonb, 0, 'Common steam cycles are 134–137 °C for 3 minutes or 121–124 °C for 15 minutes; higher temperature means a shorter holding time. Drying and cooling times are additional.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 25, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'Which organism''s spores are used as the biological indicator for steam sterilisation?', '["Geobacillus stearothermophilus", "Clostridioides difficile", "Staphylococcus aureus", "Bacillus atrophaeus"]'::jsonb, 0, 'Geobacillus stearothermophilus spores are highly resistant to moist heat, so their death shows that the cycle was effective. Bacillus atrophaeus is used for ethylene oxide and dry heat.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 26, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'The Bowie–Dick test is performed daily in a pre-vacuum steam steriliser to check:', '["That the biological spores have been killed", "That the steriliser door seal is cool", "Air removal and steam penetration", "The chemical residue left on instruments"]'::jsonb, 2, 'Any residual air prevents steam reaching all surfaces. The Bowie–Dick test pack is run in an empty chamber before the first load of the day; an uneven colour change means the steriliser must not be used.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 27, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'Ethylene oxide sterilisation is used for heat-sensitive items. Its main disadvantage is that:', '["Items need a long aeration time because the gas is toxic and carcinogenic", "It cannot kill bacterial spores, so it is only a disinfectant", "It corrodes all metal instruments, so only plastics can be processed", "It requires temperatures above 150 °C, which melt most plastics"]'::jsonb, 0, 'Ethylene oxide works at low temperature and penetrates well, but residues are toxic to patients and staff, so long aeration is required before use.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 28, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'According to the Spaulding classification, a flexible gastroscope (which contacts mucous membranes) requires, at minimum:', '["High-level disinfection", "Sterilisation", "Low-level disinfection", "Cleaning with detergent only"]'::jsonb, 0, 'Critical items (enter sterile tissue or blood) must be sterile; semi-critical items (contact mucous membranes or non-intact skin) need at least high-level disinfection; non-critical items (intact skin) need low-level disinfection.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 29, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'The most important first step in reprocessing used surgical instruments is:', '["Placing them straight into the steriliser after the case", "Thorough cleaning to remove blood, tissue and debris", "Wrapping them while still wet so they do not dry out", "Soaking them in normal saline overnight in the sluice"]'::jsonb, 1, 'Sterilisation cannot reliably penetrate organic debris (bioburden), and dried blood is hard to remove. Instruments are cleaned, inspected, dried and packed before sterilisation.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 30, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', '2% glutaraldehyde achieves sterilisation (not just high-level disinfection) only after immersion for about:', '["45 seconds", "20 minutes", "10 hours", "2 hours"]'::jsonb, 2, 'About 20 minutes of immersion gives high-level disinfection; sterilisation needs about 10 hours. It is irritant, so use ventilation and protective equipment, and rinse items with sterile water.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 31, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'An elective cholecystectomy, in which the biliary tract is entered without unusual contamination or spillage, is classified as a:', '["Clean wound", "Clean-contaminated wound", "Contaminated wound", "Dirty (infected) wound"]'::jsonb, 1, 'Clean: no entry into respiratory, GI, genital or urinary tracts. Clean-contaminated: these tracts entered under controlled conditions. Contaminated: open fresh accidental wounds, gross spillage or major break in asepsis. Dirty: old traumatic wounds or existing infection or perforation.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 32, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'A laparotomy for a perforated appendix with pus in the peritoneal cavity is classified as a:', '["Dirty (infected) wound", "Contaminated wound", "Clean-contaminated wound", "Clean wound"]'::jsonb, 0, 'Pus or a perforated viscus present at operation makes the wound class IV (dirty), with the highest risk of surgical site infection.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 33, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'Surgical antibiotic prophylaxis (e.g. cefazolin) should be given:', '["The evening before, on the surgical ward", "After the skin has been closed in theatre", "Only if the wound later becomes infected", "Within 60 minutes before skin incision"]'::jsonb, 3, 'Peak tissue levels are needed at the time of incision. Vancomycin and fluoroquinolones are started within 120 minutes because of their longer infusion times. Redose in long operations or major blood loss.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 34, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'If hair must be removed from the operative site, the recommended method is:', '["Shaving with a razor the night before surgery", "Clipping with electric clippers, as close to the time of surgery as possible", "Shaving with a razor in theatre", "Applying a depilatory cream in the operating room just before incision"]'::jsonb, 1, 'Razors cause tiny cuts that become colonised with bacteria and increase surgical site infection. Clipping close to the time of surgery, only where hair interferes, is safest.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 35, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'For an elective adult operation under general anaesthesia, the minimum fasting time for clear fluids is:', '["8 hours", "6 hours", "2 hours", "From midnight, whatever the time of surgery"]'::jsonb, 2, 'Common guidance: clear fluids 2 h, breast milk 4 h, infant formula or a light meal 6 h, fried or fatty food 8 h. Unnecessary prolonged fasting causes dehydration and discomfort.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 36, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'When a nurse witnesses a surgical consent form, the nurse is confirming that:', '["The patient is the person signing and appears to sign voluntarily", "The patient will not later change their mind", "The surgery is clinically necessary", "The nurse has explained all the risks and benefits of the operation"]'::jsonb, 0, 'The surgeon (or person doing the procedure) must explain the nature, benefits, risks and alternatives. If the patient seems not to understand or is sedated, the nurse should not witness and should inform the surgeon.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 37, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'Which of these is a duty of the CIRCULATING nurse rather than the scrub nurse?', '["Passing instruments and sutures directly to the surgeon", "Setting up and arranging the sterile instrument trolley", "Opening sterile supplies onto the field and documenting", "Holding retractors and swabs within the sterile field"]'::jsonb, 2, 'The circulating nurse remains unsterile, manages the room, opens and fetches supplies, performs counts with the scrub nurse, positions the patient and documents. The scrub nurse works within the sterile field.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 38, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'A tissue specimen is to be sent for FROZEN SECTION. It should be sent:', '["In 10% formalin, together with the routine histology", "Fresh, without formalin, immediately to the laboratory", "Frozen in the theatre fridge until the end of the list", "In 70% alcohol, so that the tissue does not dry out"]'::jsonb, 1, 'Frozen section is done during surgery to guide decisions (e.g. tumour margins). Formalin fixation would prevent rapid freezing and sectioning. Routine histology specimens go in 10% formalin.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 39, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'Babcock forceps are designed to:', '["Hold the skin edges evenly during subcuticular suturing at closure", "Grasp and hold dense tissue such as fascia firmly, using interlocking teeth", "Grasp delicate tubular structures such as appendix or bowel without crushing", "Clamp large blood vessels firmly before they are ligated and divided"]'::jsonb, 2, 'Babcock forceps have smooth, fenestrated, rounded jaws for atraumatic grasping. Allis forceps have fine teeth for firm grasp; Kocher''s are heavy toothed clamps; artery forceps clamp vessels.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 40, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'Which statement about surgical site marking and the ''Time Out'' is correct?', '["The Time Out can be done after the incision if the theatre list is busy", "Marking is not needed if the patient''s notes clearly state the correct side", "The mark should be made with washable ink so that it is easily removed", "If the site mark is not visible after draping, Time Out cannot be completed"]'::jsonb, 3, 'The Time Out is the final verbal check of patient, procedure and site immediately before incision, with all team members pausing. Any discrepancy must be resolved before starting.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 41, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'The left anterior descending (LAD) coronary artery mainly supplies:', '["The anterior left ventricle and anterior two-thirds of the septum", "The right ventricle and the SA node in most people", "The posterior wall of the left ventricle and the left atrium", "The inferior wall of the heart and the AV node in most people"]'::jsonb, 0, 'The LAD (from the left main) supplies the anterior LV and most of the septum. The right coronary artery supplies the RV, the inferior wall and, in most people, the SA and AV nodes.', 'PON 411 · Anatomy & Physiology'),
(1, 42, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'The normal adult blood volume is approximately:', '["150 mL/kg (about 10 L)", "40 mL/kg (about 3 L)", "70 mL/kg (about 5 L in an adult)", "20 mL/kg (about 1.5 L)"]'::jsonb, 2, 'Adult blood volume is about 70 mL/kg (65 in women, 75 in men); about 80–90 mL/kg in infants. It is used to estimate allowable blood loss.', 'PON 411 · Anatomy & Physiology'),
(1, 43, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'If stroke volume is 70 mL and heart rate is 75 beats/min, the cardiac output is:', '["0.525 L/min", "5.25 L/min", "52.5 L/min", "1.07 L/min"]'::jsonb, 1, 'Cardiac output = stroke volume × heart rate = 70 mL × 75 = 5,250 mL/min = 5.25 L/min (normal 4–8 L/min).', 'PON 411 · Anatomy & Physiology'),
(1, 44, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'Pulmonary surfactant, which reduces alveolar surface tension, is produced by:', '["Alveolar macrophages (dust cells)", "Goblet cells of the bronchial mucosa", "Type II pneumocytes (type II alveolar cells)", "Type I pneumocytes lining the alveoli"]'::jsonb, 2, 'Type I cells form the thin gas-exchange surface; type II cells secrete surfactant and can regenerate type I cells. Surfactant deficiency causes respiratory distress syndrome in preterm babies.', 'PON 411 · Anatomy & Physiology'),
(1, 45, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'The volume of air remaining in the lungs at the end of a normal, quiet expiration is the:', '["Residual volume", "Vital capacity", "Functional residual capacity", "Tidal volume"]'::jsonb, 2, 'FRC = residual volume + expiratory reserve volume. It is the oxygen reservoir between breaths; it falls with anaesthesia, obesity, supine and head-down positions.', 'PON 411 · Anatomy & Physiology'),
(1, 46, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'Antidiuretic hormone (ADH) increases water reabsorption mainly in the:', '["Ascending limb of the loop of Henle", "Glomerulus", "Collecting ducts of the nephron", "Proximal convoluted tubule"]'::jsonb, 2, 'ADH (from the posterior pituitary) inserts aquaporin channels into collecting-duct cells. Surgery and pain increase ADH secretion, causing water retention after operations.', 'PON 411 · Anatomy & Physiology'),
(1, 47, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'The normal adult glomerular filtration rate is approximately:', '["25 mL/min", "125 mL/min", "1,200 mL/min", "500 mL/min"]'::jsonb, 1, 'Normal GFR is about 120–125 mL/min (180 L/day), of which about 99% is reabsorbed. Renal blood flow is about 1,200 mL/min.', 'PON 411 · Anatomy & Physiology'),
(1, 48, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'Vitamin K is needed by the liver to produce clotting factors:', '["II, VII, IX and X", "I, V and VIII", "XI, XII and XIII", "III, IV and VI"]'::jsonb, 0, 'Warfarin blocks vitamin K–dependent factors II, VII, IX and X (and proteins C and S). Obstructive jaundice reduces vitamin K absorption, so it is given before biliary surgery.', 'PON 411 · Anatomy & Physiology'),
(1, 49, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'After splenectomy, a patient is at greatest risk of overwhelming infection from:', '["Mycobacterium tuberculosis reactivation", "Herpes simplex and other viruses", "Encapsulated bacteria such as Streptococcus pneumoniae", "Candida albicans and other fungi"]'::jsonb, 2, 'The spleen filters encapsulated organisms (pneumococcus, Haemophilus influenzae type b, meningococcus). Vaccinate (ideally 2 weeks before elective splenectomy) and consider antibiotic prophylaxis.', 'PON 411 · Anatomy & Physiology'),
(1, 50, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'Cerebrospinal fluid (CSF) is mainly produced by the:', '["Dura mater", "Pineal gland", "Choroid plexus in the ventricles", "Arachnoid granulations"]'::jsonb, 2, 'About 500 mL/day is produced; the total volume is about 150 mL. It is reabsorbed through arachnoid granulations into the venous sinuses. Obstruction of flow causes hydrocephalus.', 'PON 411 · Anatomy & Physiology'),
(1, 51, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'In adults the spinal cord usually ends at the level of:', '["S2", "L1–L2 vertebrae", "L4–L5", "T10"]'::jsonb, 1, 'Below the conus medullaris lies the cauda equina. Spinal anaesthesia is therefore given below L2 (usually L3–L4 or L4–L5) to avoid cord injury. In newborns the cord ends lower (about L3).', 'PON 411 · Anatomy & Physiology'),
(1, 52, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'The nerve at risk during parotid gland surgery, whose injury causes facial weakness on that side, is the:', '["Glossopharyngeal nerve (cranial nerve IX)", "Hypoglossal nerve (cranial nerve XII)", "Facial nerve (cranial nerve VII)", "Trigeminal nerve (cranial nerve V)"]'::jsonb, 2, 'The facial nerve passes through the parotid gland and divides into five branches there. Facial nerve monitoring is often used during parotidectomy.', 'PON 411 · Anatomy & Physiology'),
(1, 53, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'Hoarseness of voice after thyroidectomy is most likely due to injury of the:', '["Recurrent laryngeal nerve", "Accessory nerve", "Hypoglossal nerve", "Phrenic nerve"]'::jsonb, 0, 'The recurrent laryngeal nerve supplies all intrinsic laryngeal muscles except cricothyroid. Unilateral injury causes hoarseness; bilateral injury can cause stridor and airway obstruction after extubation.', 'PON 411 · Anatomy & Physiology'),
(1, 54, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'The diaphragm is supplied by the phrenic nerve, which arises from the spinal roots:', '["C1 and C2", "T1 to T6", "C6, C7 and C8", "C3, C4 and C5"]'::jsonb, 3, '''C3, 4, 5 keeps the diaphragm alive.'' High cervical cord injury or phrenic nerve injury (e.g. during neck or thoracic surgery) can cause diaphragmatic paralysis.', 'PON 411 · Anatomy & Physiology'),
(1, 55, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'In an emergency when the recipient''s blood group is unknown, the red cells that can be given are:', '["Group B Rh-positive", "Group A Rh-negative", "Group O Rh-negative", "Group AB Rh-positive"]'::jsonb, 2, 'Group O red cells have no A or B antigens; Rh-negative avoids sensitisation (important in girls and women of childbearing age). Group AB is the universal plasma donor.', 'PON 411 · Anatomy & Physiology'),
(1, 56, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'The correct order of the main stages of haemostasis is:', '["Coagulation, then vascular spasm, then platelet plug", "Fibrinolysis, coagulation, then the platelet plug", "Vascular spasm, platelet plug, then coagulation", "Platelet plug, fibrinolysis, then vascular spasm"]'::jsonb, 2, 'Injury causes immediate vasoconstriction, then platelets adhere and aggregate, then the clotting cascade forms fibrin to stabilise the plug. Fibrinolysis later dissolves the clot.', 'PON 411 · Anatomy & Physiology'),
(1, 57, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'Body temperature is regulated mainly by the:', '["Medulla oblongata", "Thyroid gland", "Cerebellum", "Hypothalamus"]'::jsonb, 3, 'The hypothalamus compares core temperature with its set point and triggers heat loss or heat gain. General anaesthesia impairs this control, so patients become hypothermic in theatre.', 'PON 411 · Anatomy & Physiology'),
(1, 58, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'An indirect inguinal hernia passes through the:', '["Femoral canal, below and lateral to the pubic tubercle", "Hesselbach''s triangle, medial to the inferior epigastric vessels", "Deep inguinal ring, lateral to the inferior epigastric vessels", "Linea alba, just above the umbilicus in the midline"]'::jsonb, 2, 'Indirect hernias follow the path of the testis (patent processus vaginalis) and can reach the scrotum. Direct hernias bulge through a weak posterior wall (Hesselbach''s triangle). Femoral hernias lie below and lateral to the pubic tubercle.', 'PON 411 · Anatomy & Physiology'),
(1, 59, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'McBurney''s point, the usual site of maximum tenderness in appendicitis, lies:', '["Midway between the umbilicus and the pubic symphysis", "One-third of the way from the right anterior superior iliac spine to the umbilicus", "At the tip of the ninth costal cartilage", "Two-thirds of the way from the umbilicus to the left anterior superior iliac spine"]'::jsonb, 1, 'McBurney''s point is on the line from the right ASIS to the umbilicus, one-third of the way from the ASIS. The gridiron (McBurney) incision for open appendicectomy is made here.', 'PON 411 · Anatomy & Physiology'),
(1, 60, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'From lateral to medial, the contents of the femoral triangle are:', '["Femoral vein, femoral artery, femoral nerve (then canal)", "Femoral artery, femoral nerve, femoral vein (then canal)", "Femoral nerve, femoral artery, femoral vein (then the femoral canal)", "Femoral canal, femoral vein, femoral artery, femoral nerve"]'::jsonb, 2, 'Mnemonic NAVY (Nerve, Artery, Vein, Y-fronts/empty space) from lateral to medial. The femoral pulse is felt at the mid-inguinal point; the vein lies medial for femoral line insertion.', 'PON 411 · Anatomy & Physiology'),
(1, 61, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'The brachial plexus is formed from the anterior rami of spinal nerves:', '["C5 to T1", "T1 to T6", "C1 to C4", "C3 to C7"]'::jsonb, 0, 'The brachial plexus supplies the upper limb. It is at risk from shoulder abduction beyond 90°, the lateral and prone positions, and arm board malposition during surgery.', 'PON 411 · Anatomy & Physiology'),
(1, 62, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'Which layer of the skin has no blood vessels?', '["Dermis", "Hypodermis (subcutaneous layer)", "Epidermis", "Papillary dermis"]'::jsonb, 2, 'The epidermis is nourished by diffusion from the dermis. This explains why superficial (epidermal) burns do not bleed and heal without scarring.', 'PON 411 · Anatomy & Physiology'),
(1, 63, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'The correct order of the stages of fracture (bone) healing is:', '["Granulation, remodelling, haematoma, consolidation, callus", "Remodelling, haematoma, granulation, callus, consolidation", "Callus, haematoma, granulation, remodelling, consolidation", "Haematoma, granulation, callus, consolidation, remodelling"]'::jsonb, 3, 'Bleeding forms a haematoma, which is replaced by granulation tissue, then soft and hard callus. Woven bone consolidates into lamellar bone and is remodelled over months.', 'PON 411 · Anatomy & Physiology'),
(1, 64, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'The adrenal medulla mainly secretes:', '["Antidiuretic hormone and oxytocin", "Aldosterone and other mineralocorticoids", "Adrenaline (epinephrine) and noradrenaline", "Cortisol and other glucocorticoids"]'::jsonb, 2, 'The adrenal cortex produces cortisol (zona fasciculata), aldosterone (zona glomerulosa) and sex hormones. The medulla is part of the sympathetic system and releases catecholamines.', 'PON 411 · Anatomy & Physiology'),
(1, 65, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'The metabolic stress response to major surgery typically causes:', '["Hypoglycaemia, with decreased protein breakdown and positive nitrogen balance", "Raised cortisol, catecholamines and ADH, with fluid retention and hyperglycaemia", "Lowered cortisol and catecholamines, with increased urine output and diuresis", "Reduced ADH and aldosterone, with dilute polyuria and sodium loss in the urine"]'::jsonb, 1, 'Surgery activates the hypothalamic–pituitary–adrenal axis and sympathetic system: cortisol, glucagon, catecholamines, ADH and aldosterone rise, causing catabolism, hyperglycaemia and fluid retention with low urine output in the first 24–48 h.', 'PON 411 · Anatomy & Physiology'),
(1, 66, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'The normal adult serum potassium range is:', '["1.5–2.5 mmol/L", "5.5–7.0 mmol/L", "3.5–5.0 mmol/L", "135–145 mmol/L"]'::jsonb, 2, 'Potassium is mostly intracellular. Both hypokalaemia and hyperkalaemia cause arrhythmias, and anaesthesia (e.g. suxamethonium) and tissue damage can raise potassium. 135–145 mmol/L is the sodium range.', 'PON 411 · Anatomy & Physiology'),
(1, 67, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'The normal arterial blood pH range is:', '["7.50–7.65", "6.80–7.00", "7.35–7.45", "7.00–7.20"]'::jsonb, 2, 'Below 7.35 is acidaemia, above 7.45 is alkalaemia. Normal PaCO₂ is 35–45 mmHg and bicarbonate 22–26 mmol/L.', 'PON 411 · Anatomy & Physiology'),
(1, 68, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'Which change shifts the oxyhaemoglobin dissociation curve to the RIGHT (so oxygen is released more readily to tissues)?', '["Raised temperature, PaCO₂, acidity and 2,3-DPG", "Carbon monoxide and fetal haemoglobin", "Low PaCO₂ with low red-cell 2,3-DPG", "Hypothermia, alkalosis and a low PaCO₂"]'::jsonb, 0, 'Active, hot, acidic tissues favour oxygen release (Bohr effect). Hypothermia, alkalosis, carbon monoxide, fetal haemoglobin and low 2,3-DPG shift the curve to the left.', 'PON 411 · Anatomy & Physiology'),
(1, 69, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'The common bile duct is formed by the union of the:', '["Pancreatic duct and the cystic duct", "Right and left hepatic ducts", "Common hepatic duct and the pancreatic duct", "Cystic duct and the common hepatic duct"]'::jsonb, 3, 'The right and left hepatic ducts join to form the common hepatic duct, which joins the cystic duct to form the common bile duct. It joins the pancreatic duct at the ampulla of Vater.', 'PON 411 · Anatomy & Physiology'),
(1, 70, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'During cholecystectomy, Calot''s triangle is identified because it contains the:', '["Hepatic artery proper; bounded by the stomach and the duodenum", "Cystic artery; bounded by cystic duct, common hepatic duct and liver", "Common bile duct; bounded by the gallbladder fundus and liver", "Portal vein; bounded by the pancreas, duodenum and the stomach"]'::jsonb, 1, 'Clearly displaying Calot''s triangle (the ''critical view of safety'') before clipping the cystic duct and artery prevents injury to the common bile duct.', 'PON 411 · Anatomy & Physiology'),
(1, 71, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'The organism most commonly responsible for surgical site infections is:', '["Escherichia coli", "Staphylococcus aureus", "Pseudomonas aeruginosa", "Streptococcus pneumoniae"]'::jsonb, 1, 'Staph aureus (a Gram-positive coccus in clusters), often carried in the nose and on the skin, is the leading cause of SSI, especially in clean surgery. Gut organisms dominate after bowel surgery.', 'GSM 402 · Microbiology & Infection Control'),
(1, 72, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'A patient colonised with MRSA is listed for surgery. Apart from standard precautions, the patient needs:', '["Airborne precautions, with an N95 respirator for every member of the team", "No special measures, because MRSA does not cause surgical site infection", "Cancellation of all surgery until three consecutive negative screening swabs", "Contact precautions, with decolonisation and suitable prophylaxis as per policy"]'::jsonb, 3, 'MRSA spreads by contact through hands and equipment. Use gloves and gowns, dedicated equipment, thorough cleaning, and often list the patient last; pre-operative decolonisation (e.g. nasal mupirocin, chlorhexidine washes) reduces SSI.', 'GSM 402 · Microbiology & Infection Control'),
(1, 73, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'Gas gangrene after a contaminated wound is caused mainly by:', '["Clostridium tetani", "Bacteroides fragilis", "Streptococcus pyogenes", "Clostridium perfringens"]'::jsonb, 3, 'Clostridium perfringens is a spore-forming anaerobe producing alpha-toxin, causing rapidly spreading myonecrosis with gas in the tissues (crepitus), brown foul discharge and shock. Treatment is urgent radical debridement plus high-dose penicillin (and clindamycin).', 'GSM 402 · Microbiology & Infection Control'),
(1, 74, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'A farmer with a deep, soil-contaminated wound does not know his tetanus immunisation history. The recommended prophylaxis is:', '["Wound debridement, tetanus toxoid AND human tetanus immunoglobulin", "No prophylaxis unless trismus or spasms develop in the next week", "Tetanus toxoid vaccine only, with a booster dose in one month", "Oral penicillin only, for seven days, with a review at the clinic"]'::jsonb, 0, 'For tetanus-prone wounds with unknown or incomplete immunisation, give both active (toxoid) and passive (immunoglobulin) immunisation at different sites, plus thorough wound cleaning and debridement.', 'GSM 402 · Microbiology & Infection Control'),
(1, 75, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'Instruments used on a patient with suspected Creutzfeldt–Jakob disease (CJD) need special handling because prions:', '["Are killed rapidly by 70% alcohol wipes within a few seconds", "Are highly resistant to standard sterilisation and disinfection", "Are reliably destroyed by routine 121 °C steam for 15 minutes", "Are spread only through the air by coughing and sneezing"]'::jsonb, 1, 'Prions resist heat, radiation and most chemicals. Instruments used on high-risk tissue (brain, spinal cord, posterior eye) in suspected CJD are quarantined or destroyed, following national guidance; single-use instruments are preferred.', 'GSM 402 · Microbiology & Infection Control'),
(1, 76, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'After a needlestick injury from an infected source, the bloodborne virus with the HIGHEST transmission risk is:', '["Hepatitis C (in anyone exposed)", "Hepatitis B (in a non-immune person)", "HIV (human immunodeficiency virus)", "Hepatitis A (in a non-immune person)"]'::jsonb, 1, 'Approximate risks after percutaneous exposure: hepatitis B up to 30% (non-immune), hepatitis C about 2%, HIV about 0.3%. All theatre staff should be vaccinated against hepatitis B and their antibody response checked.', 'GSM 402 · Microbiology & Infection Control'),
(1, 77, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'The hepatitis B vaccination course for health workers is usually given at:', '["A single dose at birth only", "0, 1 and 6 months", "0 and 12 months only", "0, 1, 2 and 3 years"]'::jsonb, 1, 'Three doses at 0, 1 and 6 months (an accelerated schedule exists), followed by a check of anti-HBs antibody level 1–2 months after completion to confirm immunity.', 'GSM 402 · Microbiology & Infection Control'),
(1, 78, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', '''Standard precautions'' means that:', '["Only patients known to have HIV, hepatitis B or hepatitis C need any precautions", "Gloves and aprons are worn only when the patient has a fever or a known infection", "Precautions apply only inside the operating theatre and not on the surgical wards", "Blood, body fluids, broken skin and mucous membranes of EVERY patient are treated as infectious"]'::jsonb, 3, 'Standard precautions include hand hygiene, PPE based on the expected exposure, safe sharps handling, respiratory hygiene, safe injection practices, cleaning and waste management — for all patients at all times.', 'GSM 402 · Microbiology & Infection Control'),
(1, 79, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'After using a hypodermic needle, the correct action is to:', '["Discard it at once, without recapping, into a sharps container at the point of use", "Recap it carefully with both hands, then discard it into the yellow clinical waste", "Bend the needle to prevent re-use, then discard it into the general waste bin", "Place it on the instrument tray so that it is removed at the end of the case"]'::jsonb, 0, 'Most needlestick injuries happen during recapping or disposal. Sharps containers should be at the point of use and closed when three-quarters full. In theatre, use a neutral zone or tray for passing sharps.', 'GSM 402 · Microbiology & Infection Control'),
(1, 80, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'The anaerobic organism that commonly causes infection after colorectal surgery, and is treated with metronidazole, is:', '["Streptococcus pyogenes", "Staphylococcus epidermidis", "Pseudomonas aeruginosa", "Bacteroides fragilis"]'::jsonb, 3, 'Bacteroides fragilis is a Gram-negative anaerobe of the large bowel. Prophylaxis for colorectal surgery therefore covers both Gram-negatives (e.g. cefuroxime or gentamicin) and anaerobes (metronidazole).', 'GSM 402 · Microbiology & Infection Control'),
(1, 81, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'A burn wound produces green-blue pus with a sweet, grape-like smell. The most likely organism is:', '["Pseudomonas aeruginosa", "Clostridium perfringens", "Candida albicans", "Staphylococcus aureus"]'::jsonb, 0, 'Pseudomonas produces blue-green pigments (pyocyanin) and is common in burns, moist environments and ventilated patients. It is often resistant to many antibiotics.', 'GSM 402 · Microbiology & Infection Control'),
(1, 82, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'The key difference between sterilisation and disinfection is that sterilisation:', '["Uses only chemicals, while disinfection always uses heat such as boiling water", "Only kills viruses, while disinfection is needed to kill bacteria and fungi", "Is less effective than high-level disinfection for heat-sensitive endoscopes", "Kills all microorganisms including spores; disinfection does not reliably kill spores"]'::jsonb, 3, 'Sterilisation (steam, dry heat, ethylene oxide, hydrogen peroxide plasma, irradiation) kills all life forms. Disinfection reduces organisms to a safe level; high-level disinfection kills all vegetative organisms but not necessarily all spores.', 'GSM 402 · Microbiology & Infection Control'),
(1, 83, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'On Gram staining, Gram-negative bacteria appear:', '["Unstained, because Gram-negative bacteria have no cell wall", "Green, because they take up the malachite green counterstain", "Purple, because their thick peptidoglycan wall retains the dye", "Pink/red, because their thin wall does not retain crystal violet"]'::jsonb, 3, 'Gram-positive organisms (thick peptidoglycan) stay purple; Gram-negative organisms lose the crystal violet with alcohol and take up the red counterstain (safranin).', 'GSM 402 · Microbiology & Infection Control'),
(1, 84, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'A surgical site infection is defined as one occurring within how long of an operation without an implant?', '["30 days", "1 year", "7 days", "48 hours"]'::jsonb, 0, 'SSI surveillance: within 30 days of surgery, or up to 90 days (or 1 year in older definitions) when an implant such as a joint prosthesis or mesh is left in place.', 'GSM 402 · Microbiology & Infection Control'),
(1, 85, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'Infection of an orthopaedic implant is hard to eradicate with antibiotics mainly because:', '["Bacteria form a protective biofilm on the implant surface", "Implants release toxins that inactivate antibiotics", "Antibiotics cannot enter bone at all", "The organisms are always viruses"]'::jsonb, 0, 'Biofilms (e.g. of Staph epidermidis and Staph aureus) shield bacteria from antibiotics and immune cells, so infected implants often need removal or revision. Prevention (laminar flow, prophylaxis, minimal traffic) is key.', 'GSM 402 · Microbiology & Infection Control'),
(1, 86, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'Mycobacterium tuberculosis is identified on a sputum smear using:', '["Gram stain (Gram-positive cocci)", "Giemsa stain", "India ink stain", "Ziehl–Neelsen stain (acid-fast bacilli)"]'::jsonb, 3, 'The waxy mycolic acid cell wall resists decolourisation by acid-alcohol, so TB appears as red acid-fast bacilli. GeneXpert is now widely used for rapid diagnosis and rifampicin resistance.', 'GSM 402 · Microbiology & Infection Control'),
(1, 87, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'Ultra-clean (laminar flow) air ventilation in theatres is mainly used for:', '["Emergency caesarean sections", "Minor procedures under local anaesthesia", "Implant surgery such as joint replacement", "Dental extractions"]'::jsonb, 2, 'Laminar flow directs filtered air over the operative field at a uniform velocity, reducing airborne bacteria that settle on implants. Minimising door opening and staff movement also reduces contamination.', 'GSM 402 · Microbiology & Infection Control'),
(1, 88, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'Medical asepsis differs from surgical asepsis in that medical asepsis:', '["Is used only in the operating theatre, while surgical asepsis is used on wards", "Requires every item used to be sterile, while surgical asepsis allows clean items", "Reduces the number and spread of organisms; surgical asepsis excludes all organisms", "Is exactly the same as sterilisation, but carried out by ward nurses not theatre"]'::jsonb, 2, 'Medical asepsis includes hand hygiene and cleaning (e.g. general ward care). Surgical asepsis (sterile technique) is used for invasive procedures, surgery, catheterisation and central lines.', 'GSM 402 · Microbiology & Infection Control'),
(1, 89, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'The most resistant form of microbial life to heat and chemicals, apart from prions, is:', '["Fungal yeasts", "Vegetative Gram-positive bacteria", "Enveloped viruses", "Bacterial spores"]'::jsonb, 3, 'Spores (Clostridium, Bacillus) have thick protective coats and survive boiling and many disinfectants. Enveloped viruses (HIV, hepatitis B) are the most easily destroyed.', 'GSM 402 · Microbiology & Infection Control'),
(1, 90, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'Septic shock in Gram-negative infection is triggered mainly by:', '["Exotoxins secreted by Gram-positive cocci such as Staphylococcus", "Endotoxin (lipopolysaccharide) from the Gram-negative outer membrane", "Bacterial spores released into the bloodstream from the wound", "Antibodies formed by the patient against the invading bacteria"]'::jsonb, 1, 'Lipopolysaccharide triggers a massive inflammatory cytokine release, causing vasodilation, capillary leak and organ dysfunction. Urinary, biliary and bowel-related infections are common sources.', 'GSM 402 · Microbiology & Infection Control'),
(1, 91, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'A surgical patient develops profuse watery diarrhoea after a course of broad-spectrum antibiotics. The likely organism and correct hand hygiene are:', '["Candida albicans — use alcohol rub only", "Staphylococcus aureus — alcohol hand rub is sufficient", "Escherichia coli — no hand hygiene needed with gloves", "Clostridioides difficile — wash hands with soap and water"]'::jsonb, 3, 'Antibiotics disrupt the gut flora, allowing C. difficile overgrowth. Its spores are not killed by alcohol, so washing with soap and water, contact precautions and chlorine-based cleaning are needed.', 'GSM 402 · Microbiology & Infection Control'),
(1, 92, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'Two days after minor surgery, a patient has severe wound pain out of proportion to its appearance, rapidly spreading redness, dusky skin, crepitus and septic shock. The most important action is:', '["Warm compresses, elevation and simple analgesia, then observation", "Urgent surgical debridement plus broad-spectrum IV antibiotics", "Wait for blood culture results before starting any treatment", "Oral antibiotics, wound swab, and review in the clinic in 48 hours"]'::jsonb, 1, 'Necrotising fasciitis (often Group A Streptococcus or polymicrobial) spreads along fascial planes. Mortality falls with early radical debridement; antibiotics alone are not enough.', 'GSM 402 · Microbiology & Infection Control'),
(1, 93, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'Eye protection (goggles or a face shield) is required for theatre staff when:', '["Only during orthopaedic operations that use power tools", "Splashing or spraying of blood or body fluid is likely", "Never, because a surgical mask protects the face fully", "Only when the patient is known to have HIV infection"]'::jsonb, 1, 'Standard precautions require PPE chosen according to the expected exposure: mucous membranes of the eyes, nose and mouth must be protected whenever splashes are possible (e.g. irrigation, vascular, orthopaedic and obstetric surgery).', 'GSM 402 · Microbiology & Infection Control'),
(1, 94, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'Antimicrobial stewardship in surgery includes:', '["Giving the antibiotics after skin closure instead of before the incision", "Using the broadest-spectrum antibiotic available for all surgical patients", "Continuing prophylactic antibiotics for 7 days after every surgical operation", "Prophylaxis only when indicated, at the right time, stopped within 24 hours"]'::jsonb, 3, 'Prolonged ''prophylaxis'' does not reduce SSI and increases resistance and C. difficile infection. Most operations need a single pre-incision dose, repeated only in long operations or large blood loss.', 'GSM 402 · Microbiology & Infection Control'),
(1, 95, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'Malaria caused by Plasmodium falciparum is particularly dangerous in surgical patients because it can cause:', '["Severe anaemia, hypoglycaemia, cerebral malaria and multi-organ failure", "Lasting immunity to all bacterial infections after one attack", "Only a mild fever that settles without any lasting complications", "Permanent dormancy in the liver that never produces symptoms"]'::jsonb, 0, 'P. falciparum causes heavy parasitaemia and sequestration of infected red cells in small vessels. In endemic areas such as Nigeria, unexplained post-operative fever should prompt a malaria test; treat severe malaria with IV artesunate.', 'GSM 402 · Microbiology & Infection Control'),
(1, 96, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'The best single measure to prevent cross-infection in the operating theatre and wards is:', '["Spraying the theatre with disinfectant between cases", "Routine use of prophylactic antibiotics for all staff", "Hand hygiene at the right moments", "Wearing two pairs of gloves for every task"]'::jsonb, 2, 'Hand hygiene follows the WHO ''5 moments'': before touching a patient, before a clean or aseptic procedure, after body fluid exposure risk, after touching a patient, and after touching patient surroundings.', 'GSM 402 · Microbiology & Infection Control'),
(1, 97, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'Candida albicans infection is most likely in a surgical patient who:', '["Is immunocompromised or has had long broad-spectrum antibiotics, TPN or a central line", "Has a simple closed fracture treated in a plaster cast with no surgical incision", "Has had a short, clean operation with no antibiotics and was discharged the same day", "Is a healthy young adult on the first day after an open inguinal hernia repair"]'::jsonb, 0, 'Candida is part of normal flora. It becomes an opportunistic pathogen when normal bacteria are suppressed or immunity is low, causing oral thrush, line infections and candidaemia.', 'GSM 402 · Microbiology & Infection Control'),
(1, 98, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'The main purpose of a biological indicator in sterilisation monitoring is to:', '["Confirm the cycle killed highly resistant spores", "Show only that the pack went through the steriliser", "Test the electrical safety of the steriliser itself", "Measure the humidity of the theatre and the store"]'::jsonb, 0, 'Chemical indicators (e.g. indicator tape) only show exposure to the process. Biological indicators contain living spores and give direct evidence of lethality; they are used routinely and with every load containing implants.', 'GSM 402 · Microbiology & Infection Control'),
(1, 99, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'Which statement about surgical masks in theatre is correct?', '["It covers nose and mouth, is changed between cases or when damp, and never hangs at the neck", "It needs to cover only the mouth, because the nose filters organisms naturally", "A damp mask filters better than a dry one, so it should be moistened before use", "It can be worn hanging around the neck between cases, to save time and reduce waste"]'::jsonb, 0, 'A damp or loosely worn mask loses its filtration efficiency. Masks are discarded by touching the ties only, followed by hand hygiene.', 'GSM 402 · Microbiology & Infection Control'),
(1, 100, 'Perioperative Mock — Day 1 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'Clostridium tetani causes disease after a dirty puncture wound because it is:', '["It is an anaerobic spore-former whose exotoxin blocks inhibitory neurotransmission", "It is a fungus that grows on the skin surface and spreads along the nerves", "It is a virus that multiplies in skeletal muscle and destroys the muscle fibres", "It is an aerobic organism that invades and multiplies directly in the bloodstream"]'::jsonb, 0, 'Spores enter deep, poorly oxygenated wounds and germinate. The toxin blocks release of glycine and GABA, causing rigidity, trismus and spasms. Prevention is wound debridement plus tetanus toxoid and immunoglobulin when indicated.', 'GSM 402 · Microbiology & Infection Control'),
(2, 1, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'The ASA physical status classification for a patient with well-controlled hypertension and no other disease is:', '["ASA III", "ASA I", "ASA IV", "ASA II"]'::jsonb, 3, 'ASA I is a normal healthy patient; ASA II has mild systemic disease without functional limitation (controlled hypertension, mild asthma); ASA III has severe systemic disease; ASA IV has severe disease that is a constant threat to life.', 'PAN 414 · Anaesthesia'),
(2, 2, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'For an adult having elective surgery, current fasting guidelines usually allow clear fluids up to:', '["2 hours before induction", "24 hours before induction", "12 hours before induction", "30 minutes before induction"]'::jsonb, 0, 'The ''6-4-2'' style rule: light meal/formula 6 hours, breast milk 4 hours, clear fluids 2 hours. Prolonged fasting causes dehydration, hypoglycaemia and discomfort without reducing aspiration risk.', 'PAN 414 · Anaesthesia'),
(2, 3, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'The correct order of the classic phases of general anaesthesia is:', '["Induction, emergence, maintenance", "Maintenance, induction, emergence", "Emergence, induction, maintenance", "Induction, maintenance, emergence (recovery)"]'::jsonb, 3, 'Induction takes the patient from awake to anaesthetised, maintenance keeps a stable depth during surgery, and emergence returns the patient to consciousness with protective reflexes.', 'PAN 414 · Anaesthesia'),
(2, 4, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'Cricoid pressure (Sellick manoeuvre) during rapid sequence induction is applied to:', '["Compress the oesophagus against the vertebra to reduce regurgitation", "Push the larynx forward so the cords are seen in every patient", "Stop the patient coughing on the tube as the cuff is inflated", "Close the glottis so that bronchospasm cannot occur at intubation"]'::jsonb, 0, 'Firm backward pressure on the cricoid ring (about 30 N once unconscious) occludes the upper oesophagus. It is released only on the anaesthetist''s instruction after cuff inflation and confirmation of tube position.', 'PAN 414 · Anaesthesia'),
(2, 5, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'The most reliable immediate confirmation that an endotracheal tube is in the trachea is:', '["A sustained capnography trace over several breaths", "Misting seen inside the tube on expiration", "No gurgling heard over the stomach on inflation", "The chest rising on one side with each breath"]'::jsonb, 0, 'Misting and chest movement can occur with oesophageal intubation. A consistent end-tidal CO2 trace over at least six breaths is the gold standard bedside confirmation.', 'PAN 414 · Anaesthesia'),
(2, 6, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'Suxamethonium is best described as a:', '["Non-depolarising blocker with slow onset, reversed by neostigmine", "Depolarising blocker with rapid onset and short duration", "Volatile anaesthetic agent given through the vaporiser", "Short-acting opioid analgesic used to blunt laryngoscopy"]'::jsonb, 1, 'Suxamethonium causes fasciculations then paralysis within about 60 seconds, lasting 5-10 minutes. Side effects include hyperkalaemia, bradycardia, muscle pain and triggering of malignant hyperthermia.', 'PAN 414 · Anaesthesia'),
(2, 7, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'A patient who received suxamethonium remains paralysed for over an hour. The most likely cause is:', '["Local anaesthetic systemic toxicity", "Plasma cholinesterase deficiency", "Malignant hyperthermia crisis", "Opioid overdose from fentanyl"]'::jsonb, 1, 'Suxamethonium is broken down by plasma cholinesterase. Inherited or acquired deficiency prolongs apnoea (''scoline apnoea''). Management is continued sedation and ventilation until recovery.', 'PAN 414 · Anaesthesia'),
(2, 8, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'Neostigmine is given at the end of surgery to:', '["Reverse opioid respiratory depression by blocking mu receptors", "Treat malignant hyperthermia by reducing muscle calcium release", "Reverse non-depolarising block by inhibiting acetylcholinesterase", "Reverse benzodiazepine sedation by blocking GABA receptors"]'::jsonb, 2, 'Neostigmine increases acetylcholine at the neuromuscular junction. It is given with glycopyrrolate or atropine to block its muscarinic effects such as bradycardia and secretions.', 'PAN 414 · Anaesthesia'),
(2, 9, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'Sugammadex reverses neuromuscular blockade caused by:', '["Atracurium and cisatracurium only", "Fentanyl and morphine", "Suxamethonium", "Rocuronium and vecuronium"]'::jsonb, 3, 'Sugammadex encapsulates the steroidal blockers rocuronium and vecuronium, giving rapid reversal even from deep block. It has no effect on suxamethonium or benzylisoquinoliniums.', 'PAN 414 · Anaesthesia'),
(2, 10, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'Malignant hyperthermia is triggered by:', '["Volatile agents and suxamethonium", "Propofol and fentanyl together", "Nitrous oxide given on its own", "Local anaesthetics such as lidocaine"]'::jsonb, 0, 'MH is an inherited skeletal muscle disorder (RYR1 mutation). Triggers cause uncontrolled calcium release, producing rising end-tidal CO2, tachycardia, rigidity, hyperthermia and acidosis.', 'PAN 414 · Anaesthesia'),
(2, 11, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'The earliest and most sensitive sign of malignant hyperthermia under anaesthesia is usually:', '["A core temperature above 40 °C", "An unexplained rise in end-tidal CO₂", "Dark, cola-coloured urine output", "A sudden fall in blood glucose"]'::jsonb, 1, 'Hypermetabolism raises CO2 production before temperature rises. Hyperthermia is often a late sign. Masseter rigidity after suxamethonium is another early warning.', 'PAN 414 · Anaesthesia'),
(2, 12, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'The specific drug for malignant hyperthermia is:', '["Flumazenil", "Neostigmine", "Dantrolene", "Naloxone"]'::jsonb, 2, 'Dantrolene reduces calcium release from the sarcoplasmic reticulum. Initial dose is 2.5 mg/kg IV, repeated as needed. Triggers are stopped, the patient is cooled and hyperkalaemia and acidosis are treated.', 'PAN 414 · Anaesthesia'),
(2, 13, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'Propofol is commonly chosen for induction because it:', '["Has no effect on breathing, so apnoea never occurs after induction", "Gives smooth induction with quick, clear-headed recovery and less nausea", "Raises blood pressure and heart rate, so it is ideal in shocked patients", "Provides strong analgesia, so no opioid is needed during surgery"]'::jsonb, 1, 'Propofol causes hypotension and apnoea, so monitoring is essential. It is painful on injection, supports bacterial growth, and must be handled aseptically and discarded within the recommended time.', 'PAN 414 · Anaesthesia'),
(2, 14, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'Ketamine is particularly useful in a shocked trauma patient because it:', '["Maintains blood pressure and airway reflexes while giving analgesia", "Lowers blood pressure markedly, which reduces bleeding from wounds", "Causes no hallucinations or dreams, even in adults on emergence", "Is a muscle relaxant, so intubation is possible without other drugs"]'::jsonb, 0, 'Ketamine is a dissociative agent with sympathomimetic effects. Emergence phenomena (vivid dreams, hallucinations) are reduced by a quiet recovery environment and benzodiazepines.', 'PAN 414 · Anaesthesia'),
(2, 15, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'The minimum alveolar concentration (MAC) of a volatile agent is the concentration that:', '["Causes death in 50% of the patients exposed", "Is needed to produce full muscle relaxation", "Prevents movement to incision in 50% of patients", "Causes complete amnesia in every patient"]'::jsonb, 2, 'MAC is a measure of potency: the lower the MAC, the more potent the agent. It is reduced by age, opioids, hypothermia and pregnancy, and increased in children and alcoholics.', 'PAN 414 · Anaesthesia'),
(2, 16, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'Spinal (subarachnoid) anaesthesia involves injection of local anaesthetic into the:', '["Paravertebral muscles of the lower back on one side", "CSF below the end of the spinal cord, usually L3–L4", "Peripheral nerves of the brachial plexus in the arm", "Epidural space at any level of the thoracic spine"]'::jsonb, 1, 'In adults the cord usually ends at L1-L2, so spinal injection is made below this. CSF flow from the needle confirms placement. Onset is fast and the block is dense.', 'PAN 414 · Anaesthesia'),
(2, 17, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'The most common early complication after spinal anaesthesia is:', '["Hypotension from sympathetic block", "Generalised tonic–clonic seizures", "Hyperthermia from vasoconstriction", "Hypertension with a severe headache"]'::jsonb, 0, 'Blocking sympathetic fibres causes vasodilation and sometimes bradycardia. It is managed with fluids, vasopressors (e.g. ephedrine, phenylephrine) and left uterine displacement in pregnancy.', 'PAN 414 · Anaesthesia'),
(2, 18, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'A post-dural puncture headache is typically:', '["Associated with a high fever and rash in every case", "Constant and unaffected by any change in posture", "Worse on sitting or standing, eased by lying flat", "Worse on lying flat, eased by sitting up"]'::jsonb, 2, 'CSF leak lowers pressure, pulling on pain-sensitive structures. Treatment includes rest, fluids, analgesia, caffeine and, if persistent, an epidural blood patch.', 'PAN 414 · Anaesthesia'),
(2, 19, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'A ''high'' or total spinal block presents with:', '["Increased urine output with flushing and a mild headache", "Leg pain and tingling only, settling within one hour", "Hypotension, bradycardia, arm weakness, breathing difficulty", "Hypertension and tachycardia, with normal arm power"]'::jsonb, 2, 'Excessive cephalad spread blocks the cardiac accelerators and phrenic nerves. Management is airway support, ventilation, fluids, vasopressors and atropine.', 'PAN 414 · Anaesthesia'),
(2, 20, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'Early signs of local anaesthetic systemic toxicity (LAST) include:', '["Rash and itching only, with wheeze around the injection site", "Hypothermia and shivering only, without any neurological change", "Increased urine output, thirst and a rising blood sugar level", "Circumoral numbness, metallic taste, tinnitus and lightheadedness"]'::jsonb, 3, 'Toxicity progresses to agitation, seizures, then cardiac arrhythmias and arrest. Injection is stopped, help called, airway and seizures managed, and 20% lipid emulsion given.', 'PAN 414 · Anaesthesia'),
(2, 21, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'The specific antidote for severe local anaesthetic systemic toxicity is:', '["IV protamine sulphate", "IV 20% lipid emulsion", "IV naloxone in boluses", "IV dantrolene 2.5 mg/kg"]'::jsonb, 1, 'Lipid emulsion acts as a ''lipid sink'' for fat-soluble local anaesthetics like bupivacaine. CPR may need to continue for a prolonged time.', 'PAN 414 · Anaesthesia'),
(2, 22, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'Adrenaline is added to local anaesthetic solutions mainly to:', '["Treat or prevent any allergy the patient may have to the drug", "Speed up the onset of general anaesthesia given at the same time", "Reduce the pH of the solution so that it works faster in tissues", "Cause vasoconstriction, prolonging the block and reducing absorption"]'::jsonb, 3, 'Adrenaline-containing solutions have traditionally been avoided in end-artery areas such as digits and penis because of the risk of ischaemia.', 'PAN 414 · Anaesthesia'),
(2, 23, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'In an epidural, the epidural space is identified by:', '["Free flow of clear cerebrospinal fluid from the hub of the needle", "A click felt as the needle tip enters the bone of the vertebral body", "Loss of resistance to saline or air as the needle passes the ligamentum flavum", "Blood flashing back in the hub when the needle reaches the space"]'::jsonb, 2, 'Unlike spinal anaesthesia, the dura is not punctured. CSF flow means accidental dural puncture; blood suggests a vessel, and the catheter is resited.', 'PAN 414 · Anaesthesia'),
(2, 24, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'The laryngeal mask airway (LMA) differs from an endotracheal tube in that it:', '["Must always be inserted with a laryngoscope blade", "Is suitable only for children because of its design", "Sits over the larynx and does not fully prevent aspiration", "Passes through the vocal cords and seals the trachea"]'::jsonb, 2, 'LMAs are used for short fasted cases with spontaneous breathing. They are avoided in patients at high aspiration risk, such as full stomach or emergency abdominal surgery.', 'PAN 414 · Anaesthesia'),
(2, 25, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'The Mallampati classification is used before anaesthesia to:', '["Classify the severity of blood loss in trauma", "Assess cardiac fitness from exercise tolerance", "Predict difficult intubation by viewing the oropharynx", "Grade the depth of anaesthesia during surgery"]'::jsonb, 2, 'With the mouth open and tongue protruded, class I shows soft palate, fauces, uvula and pillars; class IV shows only the hard palate, suggesting difficult laryngoscopy.', 'PAN 414 · Anaesthesia'),
(2, 26, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'If the anaesthetist cannot intubate and cannot oxygenate (CICO), the immediate rescue is:', '["Emergency front-of-neck access (cricothyroidotomy)", "Repeated attempts at laryngoscopy until successful", "Waking the patient by giving more opioid drugs", "Giving more muscle relaxant and waiting for help"]'::jsonb, 0, 'Difficult Airway Society guidelines move from plan A (intubation) to B (supraglottic device) to C (face mask) and D (front-of-neck access). The theatre nurse must know where the difficult airway trolley is.', 'PAN 414 · Anaesthesia'),
(2, 27, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'Before every anaesthetic, the anaesthetic machine should be:', '["Checked only once a month by the biomedical engineer, not before each case", "Checked only by the surgeon at the Time Out, after the patient is draped", "Used without checks if it worked normally for the last case the day before", "Checked with a standard checklist covering gases, leaks, suction and backup"]'::jsonb, 3, 'Checks cover gas supplies and pipelines, vaporiser filling, breathing system leaks, ventilator, monitors, suction, and the availability of a self-inflating bag and backup oxygen.', 'PAN 414 · Anaesthesia'),
(2, 28, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'The pin-index safety system on gas cylinders is designed to:', '["Prevent the wrong gas cylinder being fitted to the machine yoke", "Warm the gas as it leaves the cylinder to prevent hypothermia", "Show by a colour change when the cylinder is nearly empty", "Measure the pressure of the gas remaining inside the cylinder"]'::jsonb, 0, 'Each gas has a unique arrangement of pins and holes. Colour coding and labelling are additional safety features; Nigeria uses international colours (oxygen is white shoulder).', 'PAN 414 · Anaesthesia'),
(2, 29, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'In a circle breathing system, soda lime is used to:', '["Absorb exhaled CO₂ so gases can be rebreathed", "Remove anaesthetic vapour before it is rebreathed", "Humidify the fresh oxygen supply to the patient", "Filter bacteria and viruses from the exhaled air"]'::jsonb, 0, 'Soda lime reacts with CO2, producing heat and water. Exhausted soda lime changes colour (indicator) and must be replaced, or CO2 rebreathing occurs.', 'PAN 414 · Anaesthesia'),
(2, 30, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'Pulse oximetry measures:', '["Partial pressure of carbon dioxide in arterial blood", "Haemoglobin concentration in grams per decilitre", "Respiratory rate directly from chest wall movement", "Oxygen saturation of arterial haemoglobin by light absorption"]'::jsonb, 3, 'Readings are unreliable with poor perfusion, cold fingers, nail polish, carbon monoxide poisoning and motion. A normal SpO2 does not guarantee adequate ventilation.', 'PAN 414 · Anaesthesia'),
(2, 31, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'The role of the anaesthetic nurse during induction includes:', '["Opening the sterile packs onto the instrument trolley for the scrub team", "Positioning the surgical lights and the diathermy machine for the surgeon", "Leaving the room to collect instruments and sutures for the scrub nurse", "Staying with the patient, assisting with the airway and applying cricoid when asked"]'::jsonb, 3, 'Induction is a high-risk time. The anaesthetic nurse provides reassurance, monitors, passes equipment, assists with difficult airways and helps secure the tube.', 'PAN 414 · Anaesthesia'),
(2, 32, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'Total intravenous anaesthesia (TIVA) uses:', '["Only local anaesthetic infiltrated by the surgeon", "Only nitrous oxide and oxygen through a face mask", "Volatile agents given through a laryngeal mask", "IV infusions such as propofol and remifentanil only"]'::jsonb, 3, 'TIVA reduces postoperative nausea and vomiting and avoids MH triggers. It requires reliable IV access that must be visible and secure throughout.', 'PAN 414 · Anaesthesia'),
(2, 33, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'Awareness under general anaesthesia is most likely when:', '["The patient breathes spontaneously under deep anaesthesia", "The volatile agent concentration is high throughout surgery", "The patient is paralysed but given too little anaesthetic", "Only regional anaesthesia is used without any sedation"]'::jsonb, 2, 'Risk is increased in caesarean section, cardiac surgery, trauma and TIVA with disconnection. Depth-of-anaesthesia monitoring (e.g. BIS) may be used.', 'PAN 414 · Anaesthesia'),
(2, 34, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'The purpose of pre-oxygenation before induction is to:', '["Sedate the patient so the induction dose can be reduced", "Increase blood pressure before the induction agent is given", "Replace lung nitrogen with oxygen, extending safe apnoea time", "Reduce gastric acid volume and so the risk of aspiration"]'::jsonb, 2, 'Breathing 100% oxygen through a tight mask for about 3 minutes (end-tidal O2 above 80-90%) gives the anaesthetist more time before desaturation during intubation.', 'PAN 414 · Anaesthesia'),
(2, 35, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'Before transferring a patient to theatre, the ward nurse confirms that:', '["Consent, ID band, site mark, fasting and allergies are checked", "The relatives have started the IV fluids on the ward", "The patient has eaten a light meal for energy before surgery", "All jewellery, dentures and hearing aids are left in place"]'::jsonb, 0, 'A preoperative checklist reduces wrong-patient and wrong-site errors and ensures dentures, prostheses and jewellery are removed or documented.', 'PAN 414 · Anaesthesia'),
(2, 36, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'The specific antidote for opioid-induced respiratory depression is:', '["Atropine", "Naloxone", "Neostigmine", "Flumazenil"]'::jsonb, 1, 'Naloxone is a pure opioid antagonist. It has a shorter duration than many opioids, so re-narcotisation can occur and the patient must be observed. Small titrated doses avoid sudden severe pain.', 'PAN 412 · Pharmacology'),
(2, 37, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'Flumazenil is used to reverse:', '["Opioid overdose", "Heparin anticoagulation", "Neuromuscular blockade", "Benzodiazepine sedation"]'::jsonb, 3, 'Flumazenil is a benzodiazepine antagonist. It may precipitate seizures in patients on long-term benzodiazepines or with tricyclic overdose.', 'PAN 412 · Pharmacology'),
(2, 38, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'Protamine sulphate is given to:', '["Treat insulin-induced hypoglycaemia", "Reverse the effect of warfarin", "Reverse the effect of aspirin", "Reverse the effect of heparin"]'::jsonb, 3, 'Protamine binds heparin. It is given slowly to avoid hypotension and anaphylactoid reactions, especially in patients with fish allergy or previous protamine-containing insulin use.', 'PAN 412 · Pharmacology'),
(2, 39, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'Warfarin effect is urgently reversed before emergency surgery with:', '["Naloxone given in small repeated IV doses", "Protamine sulphate given slowly by IV injection", "Vitamin K plus prothrombin complex (or FFP)", "Desmopressin alone, given before the incision"]'::jsonb, 2, 'Vitamin K restores production of factors II, VII, IX and X but takes hours. PCC (or FFP if unavailable) replaces the factors immediately. INR guides treatment.', 'PAN 412 · Pharmacology'),
(2, 40, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'Midazolam given as premedication mainly provides:', '["Muscle paralysis for intubation", "Prevention of nausea and vomiting", "Anxiolysis, sedation and amnesia", "Strong analgesia for the incision"]'::jsonb, 2, 'Midazolam is a short-acting benzodiazepine. It can depress breathing, especially with opioids and in the elderly, so oxygen saturation must be monitored.', 'PAN 412 · Pharmacology'),
(2, 41, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'Atropine is used in anaesthesia to:', '["Treat bradycardia and dry secretions", "Raise the blood glucose before surgery", "Reverse opioid respiratory depression", "Induce sleep at the start of anaesthesia"]'::jsonb, 0, 'Atropine is an anticholinergic (muscarinic blocker). Side effects include dry mouth, tachycardia, urinary retention, blurred vision and confusion in the elderly.', 'PAN 412 · Pharmacology'),
(2, 42, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'Ondansetron is used perioperatively as:', '["A short-acting muscle relaxant", "A 5-HT3 antagonist antiemetic", "A sedative premedication", "A dopamine-blocking antihypertensive"]'::jsonb, 1, 'Ondansetron is effective for postoperative nausea and vomiting. It may cause headache, constipation and QT prolongation.', 'PAN 412 · Pharmacology'),
(2, 43, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'Metoclopramide may cause which important side effect in young women?', '["Bradycardia and complete heart block", "Acute dystonia such as oculogyric crisis", "Severe hypertension and headache", "Hypoglycaemia and sweating"]'::jsonb, 1, 'Metoclopramide is a dopamine antagonist. Acute dystonia is more common in young people and is treated with an anticholinergic such as procyclidine.', 'PAN 412 · Pharmacology'),
(2, 44, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'Prophylactic antibiotics for surgery are most effective when given:', '["After the wound is closed", "Three days before surgery", "Within 60 minutes before skin incision", "Only if the patient develops fever"]'::jsonb, 2, 'Tissue levels must be high at the time of contamination. Doses are repeated in long operations or with major blood loss. Prolonged courses increase resistance without benefit.', 'PAN 412 · Pharmacology'),
(2, 45, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'Gentamicin requires monitoring because it is:', '["A cause of hyperglycaemia", "Cardiotoxic only", "Hepatotoxic only", "Nephrotoxic and ototoxic"]'::jsonb, 3, 'Aminoglycoside levels are monitored, renal function checked and the drug used cautiously with other nephrotoxins and in the elderly.', 'PAN 412 · Pharmacology'),
(2, 46, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'Metronidazole is particularly useful in surgery against:', '["Fungal infections such as Candida", "Mycobacterium tuberculosis in the wound", "Anaerobes such as Bacteroides and Clostridium", "Viral infections such as herpes simplex"]'::jsonb, 2, 'Metronidazole is used in colorectal and gynaecological prophylaxis. Patients must avoid alcohol because of a disulfiram-like reaction.', 'PAN 412 · Pharmacology'),
(2, 47, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'Tranexamic acid reduces surgical bleeding by:', '["Replacing the clotting factors", "Inhibiting fibrinolysis", "Reversing the effect of heparin", "Activating platelets directly"]'::jsonb, 1, 'Tranexamic acid is an antifibrinolytic used in trauma, orthopaedic, cardiac and obstetric surgery. In trauma it is most effective within 3 hours of injury.', 'PAN 412 · Pharmacology'),
(2, 48, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'Low molecular weight heparin (e.g. enoxaparin) is given postoperatively mainly to:', '["Reduce post-operative wound pain", "Prevent DVT and pulmonary embolism", "Prevent stress ulcers in the stomach", "Treat or prevent wound infection"]'::jsonb, 1, 'LMWH is given subcutaneously. Timing around spinal or epidural catheters is critical to prevent spinal haematoma.', 'PAN 412 · Pharmacology'),
(2, 49, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'The major risk of giving potassium chloride as an undiluted IV bolus is:', '["Severe hypoglycaemia", "Acute bronchospasm", "Profound hypothermia", "Arrhythmia or cardiac arrest"]'::jsonb, 3, 'Concentrated potassium must always be diluted and infused by pump, usually no faster than 10 mmol/hour on a ward. It is a high-alert medicine stored separately.', 'PAN 412 · Pharmacology'),
(2, 50, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'Paracetamol overdose is dangerous because it causes:', '["Liver failure", "Acute pancreatitis", "Respiratory alkalosis", "Kidney stones"]'::jsonb, 0, 'Toxic metabolite NAPQI depletes glutathione. N-acetylcysteine is the antidote. Adult maximum dose is 4 g per 24 hours, less in low body weight or liver disease.', 'PAN 412 · Pharmacology'),
(2, 51, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'Non-steroidal anti-inflammatory drugs (NSAIDs) such as diclofenac should be used cautiously in patients with:', '["Peptic ulcer, renal impairment, asthma or bleeding risk", "Mild headache or toothache needing short-term relief", "Simple sprains and strains in young healthy adults", "Normal renal function and no history of stomach upset"]'::jsonb, 0, 'NSAIDs inhibit cyclo-oxygenase, reducing protective prostaglandins in the stomach and kidney. They can also trigger bronchospasm in sensitive asthmatics.', 'PAN 412 · Pharmacology'),
(2, 52, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'Morphine''s most dangerous side effect after surgery is:', '["Respiratory depression", "Severe diarrhoea", "Rebound hypertension", "Malignant hyperthermia"]'::jsonb, 0, 'Sedation level and respiratory rate are monitored. Increasing sedation is an early warning that precedes respiratory depression. Other effects include nausea, itching, constipation and urinary retention.', 'PAN 412 · Pharmacology'),
(2, 53, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'Patient-controlled analgesia (PCA) is safe mainly because:', '["Relatives and visitors can press the button for the patient", "There is no maximum dose, so pain is always fully relieved", "A sedated patient cannot press, and the lockout limits doses", "It contains no opioid, so respiratory depression cannot occur"]'::jsonb, 2, 'Only the patient may press the demand button. Nurses monitor pain, sedation, respiratory rate, SpO2 and the pump settings regularly.', 'PAN 412 · Pharmacology'),
(2, 54, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'Insulin for a diabetic patient fasting for surgery is managed by:', '["Giving oral glucose drinks only, until the patient eats again", "Adjusted doses or a variable rate insulin infusion with glucose checks", "Stopping all insulin for a week before and after the operation", "Giving the full usual morning dose of insulin without any food"]'::jsonb, 1, 'Type 1 diabetics always need some insulin to prevent ketoacidosis. Capillary glucose is checked frequently and the patient listed early on the theatre list.', 'PAN 412 · Pharmacology'),
(2, 55, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'A patient on long-term oral steroids having major surgery needs:', '["Steroid cover to prevent adrenal crisis", "A double dose of insulin on the morning", "Steroids stopped one day before surgery", "No special care, as steroids are harmless"]'::jsonb, 0, 'Long-term steroids suppress the adrenal glands, which cannot respond to surgical stress. Hydrocortisone is given at induction and continued postoperatively.', 'PAN 412 · Pharmacology'),
(2, 56, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'Adrenaline for adult anaphylaxis is given first-line as:', '["5 mg IV bolus over 1 minute", "1 mg orally as a tablet", "0.5 mg (0.5 mL of 1:1000) IM", "0.5 mg of 1:1000 by IV push"]'::jsonb, 2, 'IM adrenaline into the anterolateral thigh is repeated after 5 minutes if needed. IV adrenaline is given only by experienced staff with monitoring, in diluted small titrated doses.', 'PAN 412 · Pharmacology'),
(2, 57, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'The drug of choice for treating eclamptic seizures is:', '["Phenytoin loading", "Magnesium sulphate", "Diazepam infusion", "Paracetamol IV"]'::jsonb, 1, 'Magnesium toxicity is monitored by checking patellar reflexes, respiratory rate and urine output. Calcium gluconate is the antidote.', 'PAN 412 · Pharmacology'),
(2, 58, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'Oxytocin is given after delivery of the baby at caesarean section to:', '["Contract the uterus and reduce PPH", "Relax the uterus for delivery", "Suppress lactation after delivery", "Lower the maternal blood pressure"]'::jsonb, 0, 'Rapid IV bolus may cause hypotension and tachycardia; it is given slowly or as an infusion.', 'PAN 412 · Pharmacology'),
(2, 59, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'Heparin infusion is monitored using:', '["APTT (activated partial thromboplastin time)", "Bleeding time measured at the bedside", "Platelet count alone, checked every day", "INR (international normalised ratio)"]'::jsonb, 0, 'Warfarin is monitored by INR. Heparin can also cause heparin-induced thrombocytopenia, so platelets are monitored too.', 'PAN 412 · Pharmacology'),
(2, 60, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'Before administering a drug, the nurse checks the ''rights''. Which set is correct?', '["Right doctor, ward, bed, time, cost and the pharmacy", "Right patient, drug, dose, route, time and documentation", "Right relative, room, diagnosis, theatre and surgeon", "Right weight, height, pulse, temperature and diet"]'::jsonb, 1, 'Checking against the prescription and the patient''s identity band, plus checking allergies and expiry dates, prevents most medication errors.', 'PAN 412 · Pharmacology'),
(2, 61, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'A drug with a narrow therapeutic index is one where:', '["The effective dose is far below the toxic dose", "The drug can never cause toxicity in practice", "The toxic dose is close to the effective dose", "The drug can only be given by the oral route"]'::jsonb, 2, 'Examples are digoxin, gentamicin, lithium, phenytoin and warfarin. Blood levels or effects must be monitored closely.', 'PAN 412 · Pharmacology'),
(2, 62, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'Digoxin toxicity is suggested by:', '["Tachycardia with high blood pressure only", "Increased appetite and better sleep", "Weight gain and ankle swelling alone", "Nausea, yellow vision, bradycardia and arrhythmias"]'::jsonb, 3, 'Hypokalaemia increases the risk of digoxin toxicity. The apical pulse is checked before each dose; it is withheld if below 60 per minute unless directed.', 'PAN 412 · Pharmacology'),
(2, 63, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'Furosemide, a loop diuretic, most commonly causes:', '["Hypercalcaemia and stones", "Hypokalaemia and dehydration", "Hyperkalaemia and oedema", "Weight gain and fluid retention"]'::jsonb, 1, 'Electrolytes, fluid balance and blood pressure are monitored. High IV doses given fast can cause ototoxicity.', 'PAN 412 · Pharmacology'),
(2, 64, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'Clopidogrel is usually stopped before elective surgery because it:', '["Raises blood glucose and causes diabetic ketoacidosis", "Irreversibly inhibits platelets and increases bleeding", "Causes severe rebound hypertension under anaesthesia", "Interacts dangerously with all anaesthetic agents"]'::jsonb, 1, 'It is usually stopped about 7 days before surgery. Patients with recent coronary stents must not stop it without cardiology advice because of the risk of stent thrombosis.', 'PAN 412 · Pharmacology'),
(2, 65, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'Calcium gluconate is given intravenously in hyperkalaemia to:', '["Lower the serum potassium level directly and quickly", "Stabilise the myocardium and protect against arrhythmias", "Correct the metabolic acidosis that causes hyperkalaemia", "Increase urine output so potassium is excreted faster"]'::jsonb, 1, 'Calcium protects the heart but does not reduce potassium. Insulin with glucose and salbutamol shift potassium into cells; resins or dialysis remove it.', 'PAN 412 · Pharmacology'),
(2, 66, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'On arrival in the recovery room (PACU), the first priority of the recovery nurse is:', '["Recording the patient''s name and details in the register", "Assessing and maintaining a clear airway and breathing", "Offering the patient a drink to relieve the dry mouth", "Checking the wound dressing and the drains for bleeding"]'::jsonb, 1, 'Airway-Breathing-Circulation comes first. The handover from the anaesthetist is then received while the nurse stays with the patient.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 67, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'The most common cause of airway obstruction in an unconscious patient in recovery is:', '["A foreign body such as a dislodged tooth", "Laryngospasm, which is present in every case", "Bronchospasm in the small airways", "The tongue falling back against the pharynx"]'::jsonb, 3, 'Chin lift, jaw thrust, lateral position and oropharyngeal or nasopharyngeal airways relieve tongue obstruction.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 68, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'Laryngospasm in recovery presents with:', '["Slow deep breathing with a normal oxygen saturation", "Wheeze on expiration only, with a prolonged expiratory phase", "Productive cough with frothy pink sputum and crackles", "Stridor, or silent obstruction with paradoxical chest movement"]'::jsonb, 3, 'It is triggered by secretions or stimulation in light anaesthesia. Treatment: remove the stimulus, 100% oxygen with CPAP via tight mask, jaw thrust, and if it persists propofol or suxamethonium.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 69, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'The recovery position for an unconscious patient without airway device is:', '["Sitting upright at 90 degrees with legs dependent", "Lateral, with the head slightly down to drain secretions", "Supine, with two pillows placed under the head", "Prone, with the face turned down into the pillow"]'::jsonb, 1, 'Lateral positioning allows the tongue to fall forward and secretions or vomit to drain from the mouth, reducing aspiration risk.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 70, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'A patient in PACU has snoring respiration. The nurse should first:', '["Sit the patient upright immediately", "Give more opioid", "Call the surgeon", "Perform chin lift or jaw thrust"]'::jsonb, 3, 'Snoring indicates partial obstruction by the tongue or soft palate. Airway manoeuvres and adjuncts are used; continuing obstruction needs anaesthetist review.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 71, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'The patient may be removed from the oropharyngeal (Guedel) airway when:', '["The patient first arrives in the recovery room", "The patient is deeply asleep and snoring loudly", "The surgeon asks for it to be removed on the round", "Protective reflexes return and the patient rejects it"]'::jsonb, 3, 'Leaving it in a patient who has regained the gag reflex may cause vomiting or laryngospasm. It is removed gently when the patient gags or pushes it out.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 72, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'The Aldrete score is used in PACU to:', '["Assess readiness for discharge", "Classify surgical wounds", "Grade the severity of pain", "Assess the fluid deficit"]'::jsonb, 0, 'It scores activity, respiration, circulation, consciousness and oxygen saturation (0-2 each). A total of 9 or more out of 10 is usually needed for discharge.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 73, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'Which finding is a criterion for discharge from PACU to the ward?', '["Respiratory rate of 6 per minute with deep sedation after the opioid", "Core temperature of 34.5 °C with shivering under a single cotton sheet", "Systolic blood pressure 30% below baseline and still steadily falling", "Awake or easily rousable, stable vital signs, pain and nausea controlled"]'::jsonb, 3, 'Patients must protect their own airway, have adequate oxygenation, stable circulation, acceptable temperature, controlled pain and nausea, and a check of the surgical site and drains.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 74, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'Post-operative hypothermia should be prevented because it causes:', '["Reduced blood loss, because cold tissues bleed less after surgery", "Lower infection rates, because cold reduces the inflammatory response", "Shivering, higher O₂ demand, poor clotting, infection and delayed recovery", "Faster wound healing, because cold slows the growth of skin bacteria"]'::jsonb, 2, 'Forced warm air blankets, warmed fluids and covering the patient maintain normothermia (above 36 C).', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 75, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'Shivering after anaesthesia increases oxygen consumption, so the nurse should:', '["Give oxygen, actively warm, and give a prescribed drug such as pethidine if severe", "Ignore it as harmless, because shivering always stops within a few minutes", "Remove all the blankets so that the patient can cool down and stop shivering", "Give cold IV fluids quickly to reduce the metabolic rate and oxygen demand"]'::jsonb, 0, 'Shivering can increase oxygen consumption several-fold, dangerous in cardiac patients. Warming and oxygen are first-line.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 76, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'Hypotension in PACU with tachycardia, pallor and increasing wound drain output most likely indicates:', '["Pain alone, with no bleeding", "Opioid overdose from the PCA", "Hypothermia after a long case", "Haemorrhage (hypovolaemia)"]'::jsonb, 3, 'Signs of hypovolaemic shock call for immediate oxygen, fluid resuscitation, informing surgeon and anaesthetist, checking the wound and drains, and preparing for return to theatre.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 77, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'Hypertension in PACU is most commonly caused by:', '["Excess bleeding from the wound or from the drains", "A residual spinal anaesthetic block that is wearing off", "Pain, anxiety, full bladder, hypoxia or hypercarbia", "Hypothermia alone, with no other contributing cause"]'::jsonb, 2, 'Treat the cause first: analgesia, bladder emptying, oxygen and reassurance. Antihypertensives are given if hypertension persists.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 78, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'A patient in PACU is drowsy, with pinpoint pupils and respiratory rate of 7 per minute. The most likely cause is:', '["Hypoglycaemia", "Opioid overdose", "Hypovolaemic shock", "Local anaesthetic toxicity"]'::jsonb, 1, 'The nurse supports the airway, gives oxygen and assists breathing as needed, calls the anaesthetist and prepares naloxone.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 79, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'Emergence delirium in PACU is more common in:', '["Children and young adults, especially after volatile agents or ketamine", "Elderly patients after local anaesthesia only, for minor procedures", "Patients under spinal anaesthesia only, with no sedation at all", "Patients who received no drugs at all during the procedure"]'::jsonb, 0, 'Hypoxia, pain and full bladder must be excluded first. The patient is protected from injury and reassured in a calm environment.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 80, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'Post-operative nausea and vomiting (PONV) risk is higher in:', '["Female non-smokers with motion sickness who receive opioids", "Patients receiving TIVA with no opioid at all", "Patients having local anaesthesia without sedation", "Male smokers with no previous history of PONV"]'::jsonb, 0, 'The Apfel score uses female sex, non-smoker, PONV/motion sickness history and post-operative opioids. Prophylactic antiemetics are given to high-risk patients.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 81, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'A vomiting patient in PACU who is not fully conscious should be:', '["Turned on the side, head down, with suction", "Given oral fluids immediately to rehydrate", "Sat upright and left alone to settle", "Turned prone with the face in the pillow"]'::jsonb, 0, 'Positioning and suction prevent aspiration of gastric contents into the lungs, which causes aspiration pneumonitis.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 82, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'Hypoxaemia in PACU after a long abdominal operation is commonly due to:', '["Hyperthermia increasing the oxygen demand of the tissues", "Atelectasis and hypoventilation from residual drugs or pain", "Excess oxygen therapy causing oxygen toxicity in the lungs", "Diuresis causing dehydration and thick bronchial secretions"]'::jsonb, 1, 'Oxygen therapy, sitting up when safe, deep breathing, good analgesia and early mobilisation prevent and treat atelectasis.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 83, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'Residual neuromuscular blockade in PACU may be recognised by:', '["Strong, equal hand grip and a good cough", "Normal tidal volumes and respiratory rate", "A sustained head lift for 5 seconds or more", "Weak jerky movements, no sustained head lift"]'::jsonb, 3, 'Inadequate reversal causes respiratory insufficiency and aspiration risk. Oxygen, airway support and anaesthetist review for further reversal are required.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 84, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'Pain assessment in PACU in a conscious adult is best done using:', '["The report given by the patient''s relatives", "A validated tool such as the 0–10 numerical rating scale", "The surgeon''s opinion based on the type of operation", "Observation of the blood pressure and pulse alone"]'::jsonb, 1, 'Pain is what the patient says it is. For patients unable to self-report, behavioural tools are used. Pain is reassessed after each intervention.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 85, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'A patient following spinal anaesthesia can be discharged from PACU when:', '["The block has disappeared completely in every case, however long it takes", "The patient can stand and walk unaided immediately after arriving in PACU", "Vital signs are stable and the block is regressing, with the level documented", "The patient has eaten a full meal and passed urine in the recovery room"]'::jsonb, 2, 'The level of sensory and motor block is documented. A rising block, or a block that does not regress, needs urgent review (consider epidural haematoma).', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 86, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'The recovery nurse receives handover from the anaesthetist. Which information is essential?', '["The cleaning schedule and the next case on the list", "Only the surgeon''s name and the finishing time", "Procedure, anaesthetic, airway, drugs, fluids, blood loss", "Only the patient''s home address and next of kin"]'::jsonb, 2, 'Structured handover (e.g. SBAR) prevents omission of key information such as allergies, analgesia given, and anticipated problems.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 87, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'Urine output in an adult post-operatively should be at least:', '["50 mL per day", "0.5 mL/kg/hour", "0.1 mL/kg/hour", "5 mL/kg/hour"]'::jsonb, 1, 'Lower outputs suggest hypovolaemia or renal impairment. Check catheter patency before assuming oliguria.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 88, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'A patient in PACU is restless and confused, SpO2 is 86%. The nurse should first:', '["Remove the oxygen mask because it upsets the patient", "Give an IV sedative to calm the restless patient", "Restrain the patient so they do not fall from the trolley", "Give high-flow oxygen and assess airway and breathing"]'::jsonb, 3, 'Restlessness is an early sign of hypoxia. Sedating a hypoxic patient can be fatal.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 89, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'Stridor developing after thyroidectomy in recovery may indicate:', '["Normal recovery after any neck surgery, which needs no action", "Opioid overdose, which is treated with naloxone only", "Neck haematoma compressing the airway, or recurrent laryngeal nerve injury", "Hypocalcaemia only, which never causes stridor or airway problems"]'::jsonb, 2, 'A tense neck swelling needs urgent removal of skin clips/sutures at the bedside (clip removers kept at the bedside) and return to theatre.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 90, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'Post-thyroidectomy tingling around the mouth and fingers, with carpopedal spasm, suggests:', '["Hypocalcaemia from parathyroid injury", "Hypercalcaemia from excess PTH release", "Thyroid storm from handling of the gland", "Hypokalaemia from post-operative vomiting"]'::jsonb, 0, 'Chvostek''s and Trousseau''s signs confirm hypocalcaemia. Treatment is IV calcium gluconate.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 91, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'A post-operative patient who has not passed urine for 8 hours with lower abdominal discomfort most likely has:', '["Acute renal failure in all cases", "Normal post-operative state", "Fluid overload", "Urinary retention"]'::jsonb, 3, 'Bladder scanning confirms retention. Causes include opioids, spinal anaesthesia, anticholinergics and pain. Catheterisation may be needed.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 92, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'Bronchospasm in recovery presents with:', '["Increased urine output with warm, flushed peripheries", "Bradycardia with warm skin and a clear chest only", "Wheeze, long expiration, rising airway pressure and falling SpO₂", "Inspiratory crowing only, with a normal oxygen saturation"]'::jsonb, 2, 'Treatment includes oxygen, bronchodilators such as salbutamol, and consideration of anaphylaxis if accompanied by rash and hypotension.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 93, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'A patient in PACU with a new irregular pulse of 150/min and dizziness most likely has:', '["Sinus bradycardia with ectopic beats", "Atrial fibrillation with a fast ventricular rate", "First-degree heart block with dizziness", "Normal sinus rhythm with anxiety"]'::jsonb, 1, 'Causes include electrolyte imbalance, hypoxia, pain and fluid shifts. A 12-lead ECG, electrolytes and medical review are needed; unstable patients may need cardioversion.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 94, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'Before transferring a patient from PACU to the ward, the nurse should ensure:', '["That the anaesthetist has gone home and the surgeon has seen the patient", "That all IV lines, drains and catheters have been removed before the transfer", "Full handover, with observations, drugs given and post-op orders documented", "Only that the bed is clean and that the porter has arrived to collect the patient"]'::jsonb, 2, 'Safe transfer includes a fully charted record of observations, analgesia, antiemetics, fluids and any events.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 95, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'In a day-case surgery patient, discharge home requires:', '["The patient may drive themselves home after one hour", "No written instructions, as verbal advice is enough", "Discharge immediately on waking from the anaesthetic", "Stable signs, pain controlled, fluids taken, adult escort"]'::jsonb, 3, 'Patients should not drive, operate machinery or sign legal documents for 24 hours after general anaesthesia.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 96, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'The patient in recovery has a temperature of 39.5 C with tachycardia and muscle rigidity. The nurse should suspect:', '["Malignant hyperthermia", "Opioid toxicity", "Normal post-operative fever", "Hypothermia"]'::jsonb, 0, 'MH can present in recovery. Call for help, dantrolene, and active cooling.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 97, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'Pressure area care in PACU is important because:', '["Pressure areas are only a ward concern and not a recovery concern", "Patients have been immobile under anaesthesia and are at risk", "Anaesthesia protects the skin by improving the local circulation", "Pressure injuries only develop after several weeks of bed rest"]'::jsonb, 1, 'Skin over bony prominences is checked and documented; any damage from positioning in theatre is reported.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 98, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'The recommended observation frequency in PACU for a patient just arrived after general anaesthesia is:', '["At least every 5 minutes at first", "Every 4 hours, as on the ward", "Once on arrival, then on discharge", "Every hour until the patient wakes"]'::jsonb, 0, 'Frequent observations detect early deterioration. Frequency is reduced as the patient stabilises.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 99, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'Post-operative wound drain output of 400 mL of fresh blood in the first hour in PACU should be:', '["Managed by removing the drain so that the bleeding stops", "Documented at the end of the shift on the fluid balance chart", "Reported immediately to the surgeon as possible active bleeding", "Ignored, because drains always lose this much in the first hour"]'::jsonb, 2, 'Large or increasing fresh blood loss suggests active bleeding needing surgical review, possible return to theatre, cross-match and resuscitation.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 100, 'Perioperative Mock — Day 1 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'Capnography in PACU for a patient with a supraglottic airway is mainly used to:', '["Measure the arterial oxygen saturation continuously", "Estimate the blood loss from the change in waveform", "Measure the core body temperature through the airway", "Confirm ventilation and detect obstruction or apnoea early"]'::jsonb, 3, 'Loss of the waveform indicates disconnection, obstruction or apnoea. A rising end-tidal CO2 indicates hypoventilation.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(3, 1, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 416 · General Surgery', 'Pain that starts around the umbilicus and later shifts to the right iliac fossa is typical of:', '["Acute appendicitis", "Acute cholecystitis", "Perforated peptic ulcer", "Renal colic"]'::jsonb, 0, 'Early visceral pain is periumbilical; as the parietal peritoneum becomes inflamed, pain localises to McBurney''s point. Anorexia, nausea and low-grade fever are common.', 'PON 416 · General Surgery'),
(3, 2, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 416 · General Surgery', 'Rovsing''s sign is positive when:', '["Pain is felt in the shoulder tip when lying flat", "There is bluish bruising around the umbilicus", "Pressing the right upper quadrant stops deep inspiration", "Pressing the left iliac fossa causes right iliac fossa pain"]'::jsonb, 3, 'Rovsing''s sign supports appendicitis. Murphy''s sign (inspiratory arrest on RUQ palpation) suggests cholecystitis; Cullen''s sign (periumbilical bruising) suggests haemorrhagic pancreatitis or ruptured ectopic.', 'PON 416 · General Surgery'),
(3, 3, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 416 · General Surgery', 'The classic triad of intestinal obstruction is:', '["Fever with rigors, jaundice and right upper quadrant pain", "Haematuria, loin pain and a palpable mass in the flank", "Diarrhoea, tenesmus and passage of blood and mucus", "Colicky pain, vomiting, distension and absolute constipation"]'::jsonb, 3, 'Small bowel obstruction gives early vomiting; large bowel obstruction gives early distension and constipation. Common causes are adhesions, hernias and tumours.', 'PON 416 · General Surgery'),
(3, 4, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 416 · General Surgery', 'Initial management of adhesive small bowel obstruction without signs of strangulation is:', '["A high-fibre diet and oral fluids to stimulate the bowel to start working", "Oral laxatives and a phosphate enema to clear the obstruction quickly", "''Drip and suck'': nil by mouth, IV fluids, NG decompression, monitoring", "Immediate laparotomy for every patient, even without any signs of ischaemia"]'::jsonb, 2, 'Many adhesive obstructions settle conservatively. Fever, tachycardia, constant pain, peritonism or raised lactate suggest strangulation needing urgent surgery.', 'PON 416 · General Surgery'),
(3, 5, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 416 · General Surgery', 'A strangulated hernia differs from an irreducible (incarcerated) hernia because it:', '["Contains only omental fat with a good blood supply, so it is harmless", "Has its blood supply cut off, causing ischaemia and needing urgent surgery", "Never causes pain, because the contents are compressed and numbed", "Can always be pushed back easily, so it can wait for an elective repair"]'::jsonb, 1, 'Strangulation produces a tense, tender, red lump with systemic upset and possible obstruction. Delay leads to gangrene and perforation.', 'PON 416 · General Surgery'),
(3, 6, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 416 · General Surgery', 'Which hernia is most likely to strangulate?', '["Umbilical hernia in an infant", "Direct inguinal hernia", "Incisional hernia with wide neck", "Femoral hernia"]'::jsonb, 3, 'The femoral canal has a narrow rigid neck. Femoral hernias are more common in women and lie below and lateral to the pubic tubercle.', 'PON 416 · General Surgery'),
(3, 7, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 416 · General Surgery', 'Charcot''s triad of ascending cholangitis is:', '["Hypotension, muffled heart sounds and raised JVP", "Fever with rigors, jaundice and RUQ pain", "Headache, vomiting and papilloedema on fundoscopy", "Haematuria, urinary frequency and painful dysuria"]'::jsonb, 1, 'Reynolds'' pentad adds hypotension and confusion. Treatment is antibiotics, resuscitation and biliary drainage (ERCP).', 'PON 416 · General Surgery'),
(3, 8, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 416 · General Surgery', 'A patient with acute pancreatitis typically presents with:', '["Colicky loin pain radiating to the groin, with blood in the urine", "Painless jaundice with a palpable gallbladder and weight loss over months", "Sudden pain in the left iliac fossa with fever and diarrhoea with blood", "Epigastric pain to the back, eased by leaning forward, with raised amylase"]'::jsonb, 3, 'Common causes are gallstones and alcohol. Management is supportive: fluids, analgesia, nutrition and monitoring for complications.', 'PON 416 · General Surgery'),
(3, 9, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 416 · General Surgery', 'Painless obstructive jaundice with a palpable gallbladder (Courvoisier''s law) suggests:', '["Carcinoma of the head of the pancreas", "Acute cholecystitis", "Gallstone in the common bile duct", "Viral hepatitis"]'::jsonb, 0, 'Gallstone disease causes a fibrosed, shrunken gallbladder, so a palpable non-tender gallbladder with jaundice suggests malignant obstruction.', 'PON 416 · General Surgery'),
(3, 10, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 416 · General Surgery', 'Perforated peptic ulcer classically presents with:', '["Gradual onset of painless jaundice with dark urine and pale stools", "Colicky pain with vomiting of faeculent material and visible peristalsis", "Sudden epigastric pain, board-like rigidity, and gas under the diaphragm", "Burning epigastric pain relieved by eating and by antacid medicines"]'::jsonb, 2, 'It is a surgical emergency: resuscitation, nil by mouth, nasogastric tube, antibiotics, PPI, and laparoscopic or open repair.', 'PON 416 · General Surgery'),
(3, 11, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 416 · General Surgery', 'Haematemesis with ''coffee-ground'' vomitus usually indicates:', '["Lower GI bleeding from the rectum or sigmoid colon", "Haemoptysis from the lungs that has been swallowed", "Upper GI bleeding with blood altered by gastric acid", "Bleeding from the nose only, with no stomach cause"]'::jsonb, 2, 'Melaena (black tarry stools) also indicates upper GI bleeding. Causes include peptic ulcer, varices and Mallory-Weiss tear.', 'PON 416 · General Surgery'),
(3, 12, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 416 · General Surgery', 'Following thyroidectomy, a hoarse voice suggests injury to the:', '["Phrenic nerve", "Recurrent laryngeal nerve", "Facial nerve", "Hypoglossal nerve"]'::jsonb, 1, 'Unilateral injury gives hoarseness; bilateral injury can cause stridor and airway obstruction needing urgent intervention.', 'PON 416 · General Surgery'),
(3, 13, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 416 · General Surgery', 'Thyroid storm after surgery presents with:', '["Hypoglycaemia and drowsiness only, without fever", "Hypothermia, bradycardia and slowed mental function", "Hyperpyrexia, severe tachycardia, agitation and heart failure", "Low blood pressure with a slow pulse and dry skin"]'::jsonb, 2, 'It is prevented by making the patient euthyroid before surgery. Treatment includes beta-blockers, antithyroid drugs, iodine, steroids and cooling.', 'PON 416 · General Surgery'),
(3, 14, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 416 · General Surgery', 'A colostomy is described as healthy when the stoma is:', '["Pale and retracted below the skin", "Black, dry and firm to the touch", "Moist, pink to red and slightly raised", "Purple, swollen and with no output for days"]'::jsonb, 2, 'A dusky, dark or black stoma suggests ischaemia and must be reported immediately. Output and peristomal skin are assessed regularly.', 'PON 416 · General Surgery'),
(3, 15, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 416 · General Surgery', 'An ileostomy produces output that is:', '["Always bloody, because the ileum bleeds easily", "Liquid and enzyme-rich, so the skin needs strong protection", "Mainly gas, with very little faecal output at all", "Formed and solid, so it is passed once or twice a day"]'::jsonb, 1, 'High-output ileostomies risk dehydration and electrolyte loss. Appliances should fit closely to prevent skin excoriation.', 'PON 416 · General Surgery'),
(3, 16, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 416 · General Surgery', 'Before major bowel surgery, the patient is counselled and the stoma site is:', '["Placed exactly on the belt line, so the trousers support the bag", "Marked before surgery by the stoma nurse, sitting, standing and lying", "Placed within a skin fold, so that the bag is hidden from view", "Chosen by the surgeon during the operation only, under the drapes"]'::jsonb, 1, 'Correct siting away from folds, scars, bony prominences and the belt line makes appliance management easier.', 'PON 416 · General Surgery'),
(3, 17, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 416 · General Surgery', 'Paralytic ileus after abdominal surgery is characterised by:', '["Frequent diarrhoea with urgency and cramping", "Absent bowel sounds, distension, vomiting, no flatus", "Normal bowel function with a mild loss of appetite", "Hyperactive tinkling bowel sounds with colicky pain"]'::jsonb, 1, 'It is managed with nil by mouth, nasogastric drainage, IV fluids and correction of electrolytes, especially potassium.', 'PON 416 · General Surgery'),
(3, 18, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 416 · General Surgery', 'Anastomotic leak after bowel resection is suggested by:', '["Fever, tachycardia, worsening pain and peritonism, around day 3–7", "Bradycardia and hypothermia on day 1 only, settling by day 2", "An improving appetite with flatus and a soft, non-tender abdomen", "Normal observations with a mild wound itch from the dressing"]'::jsonb, 0, 'It is a serious complication that needs urgent investigation (CT), antibiotics, resuscitation and often return to theatre.', 'PON 416 · General Surgery'),
(3, 19, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 416 · General Surgery', 'Wound dehiscence is often preceded by:', '["Thick yellow pus only, with no fever", "Complete absence of any wound drainage", "Serosanguinous (pink) wound discharge", "Clear watery fluid that tests as urine"]'::jsonb, 2, 'If burst abdomen (evisceration) occurs, cover with sterile saline-soaked dressings, position with knees flexed, keep nil by mouth and notify surgeon urgently.', 'PON 416 · General Surgery'),
(3, 20, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 416 · General Surgery', 'Risk factors for surgical wound infection include:', '["Short, clean operations lasting under one hour with no implant", "Obesity, diabetes, smoking, malnutrition and long or contaminated surgery", "Normal blood glucose levels and stopping smoking weeks before surgery", "Young age, good nutrition and normal body weight before the operation"]'::jsonb, 1, 'Prevention bundles include optimising glucose, avoiding hair removal by shaving, timed prophylaxis, normothermia and strict asepsis.', 'PON 416 · General Surgery'),
(3, 21, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 416 · General Surgery', 'A Clavien-Dindo grade measures:', '["Severity of post-operative complications", "Anaesthetic fitness before surgery", "Wound contamination class at surgery", "Intensity of post-operative pain"]'::jsonb, 0, 'Grades range from I (minor deviation without treatment) to V (death), allowing standard reporting of surgical outcomes.', 'PON 416 · General Surgery'),
(3, 22, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 416 · General Surgery', 'Surgical wound classes: an appendicectomy for non-perforated appendicitis is classed as:', '["Clean-contaminated", "Contaminated", "Dirty", "Clean"]'::jsonb, 0, 'Entry into the GI, respiratory or urinary tract under controlled conditions is clean-contaminated. A perforated appendix with pus is dirty.', 'PON 416 · General Surgery'),
(3, 23, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 416 · General Surgery', 'A breast lump that is hard, irregular, fixed and painless in a 55-year-old woman is most suggestive of:', '["Fibroadenoma", "Breast carcinoma", "Breast abscess", "Simple cyst"]'::jsonb, 1, 'Triple assessment is used: clinical examination, imaging (mammography/ultrasound) and tissue biopsy.', 'PON 416 · General Surgery'),
(3, 24, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 416 · General Surgery', 'After mastectomy with axillary clearance, the nurse advises the patient to:', '["Keep the arm completely still in a sling for several weeks after surgery", "Avoid all shoulder movement permanently to prevent the wound from opening", "Protect the arm from injections, BP cuffs and injury, and do arm exercises", "Use the affected arm for blood sampling and drips to preserve the other arm"]'::jsonb, 2, 'Lymphoedema risk is reduced by protecting the arm. Gentle exercises prevent frozen shoulder.', 'PON 416 · General Surgery'),
(3, 25, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 416 · General Surgery', 'The main concern with a tense neck swelling after thyroidectomy is:', '["Loss of taste from lingual nerve injury", "Hypercalcaemia from parathyroid damage", "Facial nerve palsy from neck retraction", "Airway compression from haematoma"]'::jsonb, 3, 'Clip/stitch removers are kept at the bedside so the wound can be opened immediately to release the haematoma.', 'PON 416 · General Surgery'),
(3, 26, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 416 · General Surgery', 'Haemorrhoids are classified as fourth degree when they:', '["Are prolapsed and cannot be reduced", "Prolapse and then reduce on their own", "Bleed but never prolapse at all", "Prolapse and need manual reduction"]'::jsonb, 0, 'First degree do not prolapse, second degree prolapse and reduce spontaneously, third degree need manual reduction, fourth degree remain prolapsed.', 'PON 416 · General Surgery'),
(3, 27, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 416 · General Surgery', 'Post-operative care after haemorrhoidectomy includes:', '["Analgesia, stool softeners, fibre, sitz baths, and watching for bleeding and retention", "Strict bed rest and constipating agents so that the patient does not open the bowels", "Daily enemas and digital dilatation of the anus by the nurse for one week", "Avoiding all oral fluids for 48 hours to reduce the volume of stool produced"]'::jsonb, 0, 'Urinary retention is common after anorectal surgery. Reactionary bleeding can occur in the first 24 hours.', 'PON 416 · General Surgery'),
(3, 28, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 416 · General Surgery', 'Varicose vein surgery patients are encouraged post-operatively to:', '["Stand still for long periods so that the wounds are not disturbed", "Stay in bed for one week with the legs kept flat on the mattress", "Walk early, wear compression, and elevate the legs when resting", "Cross the legs when sitting to support the veins of the calf"]'::jsonb, 2, 'Early mobilisation and compression reduce DVT risk and bruising.', 'PON 416 · General Surgery'),
(3, 29, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 416 · General Surgery', 'A patient with burns of 30% total body surface area needs fluid calculated mainly using:', '["Parkland: 4 mL × kg × %TBSA over 24 h, half in the first 8 h", "Maintenance fluids only: 100 mL/kg/day for the first 10 kg", "Whole blood transfusion only, 1 unit per 10% of burn area", "1 litre of normal saline per day until the patient can drink"]'::jsonb, 0, 'Timing starts from the time of the burn, not hospital arrival. Urine output of 0.5 mL/kg/hr guides adjustment.', 'PON 416 · General Surgery'),
(3, 30, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 416 · General Surgery', 'The ''rule of nines'' assigns which percentage to one entire adult arm?', '["9%", "1%", "36%", "18%"]'::jsonb, 0, 'Head 9%, each arm 9%, each leg 18%, front trunk 18%, back trunk 18%, perineum 1%. Children have a relatively larger head.', 'PON 416 · General Surgery'),
(3, 31, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 416 · General Surgery', 'Escharotomy is performed in circumferential full-thickness burns to:', '["Reduce the volume of IV fluid needed in the first 24 hours", "Release constriction that threatens circulation or breathing", "Remove all the burnt skin so that grafting can begin at once", "Drain infected blisters and reduce the risk of wound sepsis"]'::jsonb, 1, 'Tight eschar acts like a tourniquet on limbs or restricts chest movement. Incisions are made through the eschar.', 'PON 416 · General Surgery'),
(3, 32, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 416 · General Surgery', 'Peritonitis on examination typically shows:', '["A pulsatile, expansile mass only, with no tenderness at all", "Guarding, rebound tenderness, rigidity and absent bowel sounds", "A soft non-tender abdomen with active, normal bowel sounds", "Visible peristalsis only, with a soft abdomen between waves"]'::jsonb, 1, 'The patient lies still because movement worsens pain. Causes include perforation and anastomotic leak.', 'PON 416 · General Surgery'),
(3, 33, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 416 · General Surgery', 'A ruptured abdominal aortic aneurysm presents with:', '["Gradual right iliac fossa pain with low-grade fever and anorexia", "Painless haematuria with clots and a mass felt in the loin", "Sudden abdominal or back pain, hypotension and a pulsatile mass", "Colicky right upper quadrant pain with jaundice after fatty meals"]'::jsonb, 2, 'It is a vascular emergency with high mortality. Permissive hypotension may be used until the aorta is controlled in theatre.', 'PON 416 · General Surgery'),
(3, 34, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 416 · General Surgery', 'The 6 Ps of acute limb ischaemia are:', '["Pain, pressure, pulse, pallor, polyuria and polydipsia", "Pyrexia, pus, pain, pressure, pallor and a bounding pulse", "Purpura, petechiae, pain, pallor, paralysis and pus", "Pain, pallor, pulselessness, paraesthesia, paralysis, perishing cold"]'::jsonb, 3, 'Paralysis and paraesthesia are late signs indicating threatened limb viability. Urgent embolectomy or revascularisation is needed.', 'PON 416 · General Surgery'),
(3, 35, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 416 · General Surgery', 'A sigmoid volvulus is classically shown on X-ray as:', '["A ''string sign'' in the terminal ileum on barium study", "Free gas under the diaphragm on erect chest X-ray", "Air-fluid levels in the gallbladder and biliary tree", "A ''coffee bean'' sign of a hugely dilated colon loop"]'::jsonb, 3, 'Sigmoid volvulus is common in Nigeria and elderly patients. It may be decompressed with a flatus tube or sigmoidoscopy, or need surgery if gangrenous.', 'PON 416 · General Surgery'),
(3, 36, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 416 · General Surgery', 'Typhoid ileal perforation, common in Nigeria, usually occurs in the:', '["Terminal ileum, in the 2nd–3rd week of illness", "Sigmoid colon, after the fever has settled", "Oesophagus, from repeated vomiting early on", "Stomach, within the first day of the fever"]'::jsonb, 0, 'Salmonella Typhi causes ulceration of Peyer''s patches. Perforation causes peritonitis needing resuscitation and laparotomy.', 'PON 416 · General Surgery'),
(3, 37, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 416 · General Surgery', 'A nasogastric tube position is confirmed before feeding by:', '["Blowing air and listening (whoosh test) alone", "Asking the patient to swallow", "Placing the tube end in water to look for bubbles", "Testing aspirate pH (5.5 or below) or chest X-ray"]'::jsonb, 3, 'The whoosh test is unreliable and has led to deaths. pH testing or X-ray are the approved methods.', 'PON 416 · General Surgery'),
(3, 38, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 416 · General Surgery', 'Enhanced recovery after surgery (ERAS) includes:', '["Routine nasogastric tubes and drains for all patients until bowel sounds return", "Prolonged bed rest for 5 days to allow the wound and anastomosis to heal", "Routine long fasting from the evening before and for 3 days after surgery", "Carbohydrate loading, short fasting, early feeding and mobilisation, fewer opioids"]'::jsonb, 3, 'ERAS pathways reduce complications and hospital stay by minimising the stress response.', 'PON 416 · General Surgery'),
(3, 39, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 416 · General Surgery', 'A pilonidal sinus most commonly occurs in the:', '["Umbilicus, in obese middle-aged adults", "Groin, in relation to the inguinal canal", "Axilla, in relation to sweat glands", "Natal cleft over the sacrococcygeal region"]'::jsonb, 3, 'It is associated with hair, sitting and hirsutism. It is common in young men and often recurs.', 'PON 416 · General Surgery'),
(3, 40, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 416 · General Surgery', 'Day-case surgery suitability depends mainly on:', '["The surgeon''s convenience only, to shorten the ward list", "The patient''s insurance cover only, regardless of the operation", "Patient fitness, a predictable procedure and an adult at home", "The patient''s preference only, whatever their health status"]'::jsonb, 2, 'Day-case criteria also include access to a telephone and reasonable travel distance.', 'PON 416 · General Surgery'),
(3, 41, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'A closed fracture is one in which:', '["Bone protrudes through the skin", "The bone is broken into many pieces", "There is a wound communicating with the fracture", "The skin over the fracture is intact"]'::jsonb, 3, 'An open (compound) fracture has a wound communicating with the fracture site and needs antibiotics, tetanus cover and urgent debridement.', 'PON 417 · Trauma & Orthopaedics'),
(3, 42, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'Compartment syndrome is earliest recognised by:', '["Pain out of proportion, worse on passive muscle stretch", "A pale, cold limb with mottled skin", "Absent distal pulse on palpation of the limb", "Paralysis of the muscles in the compartment"]'::jsonb, 0, 'Pulses are often present until late. Treatment is releasing tight casts/dressings and urgent fasciotomy.', 'PON 417 · Trauma & Orthopaedics'),
(3, 43, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'When a patient with a plaster cast complains of severe increasing pain, the nurse should first:', '["Elevate to heart level, check neurovascular status, split the cast, inform doctor", "Lower the limb below the level of the heart to improve the blood flow", "Give more analgesia and wait, because pain is expected after a new cast", "Reassure the patient and ignore it, because the cast prevents swelling"]'::jsonb, 0, 'Unrelieved pain may signal compartment syndrome. The limb should not be elevated above heart level if compartment syndrome is suspected.', 'PON 417 · Trauma & Orthopaedics'),
(3, 44, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'Neurovascular observations of an injured limb include:', '["Colour, warmth, refill, pulses, sensation, movement, pain", "Urine output and fluid balance over the last 24 hours", "Temperature of the limb only, compared with the room", "Blood pressure and pulse only, recorded every 4 hours"]'::jsonb, 0, 'These are compared with the unaffected limb and documented frequently after injury, casting or surgery.', 'PON 417 · Trauma & Orthopaedics'),
(3, 45, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'Fat embolism syndrome typically appears:', '["Only after skull fractures, with CSF leak from the nose and the ears", "24–72 h after a long bone fracture: confusion, breathlessness, petechiae", "Several months later, as a chronic cough and weight loss after healing", "Immediately at the time of injury, with loss of consciousness and shock"]'::jsonb, 1, 'Petechiae on the chest, axilla and conjunctiva are characteristic. Early fixation of fractures reduces risk; treatment is supportive.', 'PON 417 · Trauma & Orthopaedics'),
(3, 46, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'A fractured neck of femur typically presents with:', '["Lengthened, internally rotated leg with knee pain", "Normal leg position with ankle pain and bruising", "Shortened, externally rotated leg with hip pain after a fall", "Swelling of the knee only, with a normal hip"]'::jsonb, 2, 'Elderly women with osteoporosis are at highest risk. Early surgery (within 36 hours) reduces complications.', 'PON 417 · Trauma & Orthopaedics'),
(3, 47, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'Avascular necrosis is a particular risk with:', '["Intracapsular (subcapital) femoral neck fractures", "Closed fractures of the shaft of the fibula", "Extracapsular intertrochanteric femoral fractures", "Simple undisplaced fractures of the ribs"]'::jsonb, 0, 'The blood supply to the femoral head runs along the neck. Displaced intracapsular fractures are often treated with hemiarthroplasty.', 'PON 417 · Trauma & Orthopaedics'),
(3, 48, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'After total hip replacement (posterior approach), the patient should avoid:', '["Walking with a frame on the first day after the operation", "Hip flexion beyond 90°, crossing the legs and internal rotation", "Sitting on a high chair with arms when out of bed", "Lying with an abduction pillow between the legs at night"]'::jsonb, 1, 'These movements risk dislocation. An abduction pillow, raised toilet seat and high chair are used.', 'PON 417 · Trauma & Orthopaedics'),
(3, 49, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'Skin traction differs from skeletal traction in that:', '["Skin traction is used for heavy pulls lasting many weeks or months", "Skin traction pulls through the skin with lighter weights for shorter periods", "Skeletal traction never needs pin-site care because the pins are sterile", "Skin traction uses pins or wires passed through the bone itself"]'::jsonb, 1, 'Skeletal traction uses pins or wires through bone and allows heavier weights, requiring pin-site care to prevent infection.', 'PON 417 · Trauma & Orthopaedics'),
(3, 50, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'Nursing care for a patient in traction includes ensuring that:', '["Weights are removed whenever the patient feels uncomfortable", "The patient is pulled to the foot of the bed to increase the pull", "Weights rest on the floor when the patient is asleep at night", "Weights hang freely, ropes run in pulleys, counter-traction maintained"]'::jsonb, 3, 'Weights must never be removed without an order. Skin, pin sites, neurovascular status and pressure areas are checked.', 'PON 417 · Trauma & Orthopaedics'),
(3, 51, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'Pin-site care aims to:', '["Loosen the pins so they can be removed", "Allow the pins to be removed earlier", "Prevent infection along the pins and wires", "Promote bleeding to keep the track open"]'::jsonb, 2, 'Signs of infection are redness, swelling, purulent discharge, pain and loosening. Local policy guides cleaning frequency and solution.', 'PON 417 · Trauma & Orthopaedics'),
(3, 52, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'A Colles'' fracture is a fracture of the:', '["Scaphoid waist, after a fall onto a dorsiflexed wrist", "Distal radius, dorsally displaced, after a fall on the hand", "Proximal humerus, after a direct blow to the shoulder", "Ulnar shaft alone, after warding off a blow"]'::jsonb, 1, 'It gives a ''dinner fork'' deformity. Elderly women with osteoporosis are most at risk.', 'PON 417 · Trauma & Orthopaedics'),
(3, 53, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'Scaphoid fracture is important because it may cause:', '["Fat embolism syndrome within the first three days", "Compartment syndrome of the forearm in all cases", "Avascular necrosis and non-union, often missed at first", "Radial nerve palsy with wrist drop on the same side"]'::jsonb, 2, 'Tenderness in the anatomical snuffbox after a fall needs immobilisation and repeat imaging even if initial X-ray is normal.', 'PON 417 · Trauma & Orthopaedics'),
(3, 54, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'Osteomyelitis is most commonly caused by:', '["Staphylococcus aureus", "Candida", "Escherichia coli", "Streptococcus pneumoniae only"]'::jsonb, 0, 'In sickle cell disease, Salmonella is also a common cause. Treatment is long-course antibiotics and sometimes surgical debridement.', 'PON 417 · Trauma & Orthopaedics'),
(3, 55, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'A patient on a fracture bed is at risk of venous thromboembolism. Prevention includes:', '["Restricting fluids to reduce swelling in the injured limb", "Massaging the calf whenever it becomes swollen and painful", "Strict immobility of both legs until the fracture has fully united", "Early mobilisation, leg exercises, compression and anticoagulation"]'::jsonb, 3, 'Massaging a swollen painful calf could dislodge a clot. Signs of DVT must be reported.', 'PON 417 · Trauma & Orthopaedics'),
(3, 56, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'Volkmann''s ischaemic contracture is a complication of:', '["A skull fracture with a small haematoma", "A simple ankle sprain in a crepe bandage", "Femoral neck fracture after hemiarthroplasty", "Untreated forearm compartment syndrome"]'::jsonb, 3, 'Brachial artery injury or swelling in supracondylar fractures in children can lead to muscle necrosis and claw-hand contracture.', 'PON 417 · Trauma & Orthopaedics'),
(3, 57, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'The first aid principle for a suspected fracture is to:', '["Straighten the limb forcefully first", "Apply heat to reduce the swelling", "Immobilise the joints above and below", "Massage the injured area gently"]'::jsonb, 2, 'Splinting reduces pain, bleeding and further damage. Open wounds are covered with sterile dressings.', 'PON 417 · Trauma & Orthopaedics'),
(3, 58, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'Delayed union of a fracture may be caused by:', '["Poor blood supply, infection, smoking and poor immobilisation", "Young age with a thick periosteum around the bone", "Good nutrition with adequate protein and vitamin intake", "Adequate immobilisation with a well-fitting cast"]'::jsonb, 0, 'Diabetes, steroids and NSAIDs may also slow healing.', 'PON 417 · Trauma & Orthopaedics'),
(3, 59, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'The stages of bone healing, in order, are:', '["Callus, haematoma, remodelling, inflammation, ossification", "Haematoma, inflammation, callus, ossification, remodelling", "Remodelling, callus, haematoma, ossification, inflammation", "Ossification, haematoma, callus, inflammation, remodelling"]'::jsonb, 1, 'Remodelling may continue for months to years after clinical union.', 'PON 417 · Trauma & Orthopaedics'),
(3, 60, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'Internal fixation of fractures involves:', '["An external frame with pins outside the skin", "Plates, screws, nails or wires placed at operation", "Skin or skeletal traction with hanging weights", "A plaster of Paris cast applied after manipulation"]'::jsonb, 1, 'Open reduction and internal fixation (ORIF) allows earlier mobilisation but carries risks of infection and implant failure.', 'PON 417 · Trauma & Orthopaedics'),
(3, 61, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'A patient with a spinal cord injury is moved by:', '["Asking them to turn themselves slowly onto their side", "Log-rolling with in-line immobilisation of the head and neck", "Sitting them up first to assess the level of the injury", "Lifting them by the arms and legs onto the trolley"]'::jsonb, 1, 'Log-rolling keeps the spine aligned. Head holder controls the timing of movement.', 'PON 417 · Trauma & Orthopaedics'),
(3, 62, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'Autonomic dysreflexia in a patient with spinal cord injury above T6 is commonly triggered by:', '["Excess oral fluid intake", "Hypothermia on its own", "A low blood glucose level", "A full bladder or constipation"]'::jsonb, 3, 'It presents with severe hypertension, headache, bradycardia and flushing above the injury. Treat by sitting up and removing the trigger.', 'PON 417 · Trauma & Orthopaedics'),
(3, 63, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'Plaster of Paris casts should be allowed to dry by:', '["Covering it with plastic so it dries evenly overnight", "Resting it on a hard surface so it keeps its shape", "Drying it quickly with direct high heat from a dryer", "Leaving it uncovered on pillows, avoiding fingertip pressure"]'::jsonb, 3, 'Dents from fingers can cause pressure sores. A plaster cast takes 24-72 hours to dry fully.', 'PON 417 · Trauma & Orthopaedics'),
(3, 64, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'Rhabdomyolysis after crush injury causes risk of:', '["Dehydration from polyuria caused by muscle damage", "Hypoglycaemia from muscle glycogen breakdown", "Acute kidney injury from myoglobin, and hyperkalaemia", "Hypercalcaemia only, from muscle calcium release"]'::jsonb, 2, 'Treatment includes aggressive IV fluids to maintain a high urine output and monitoring of potassium.', 'PON 417 · Trauma & Orthopaedics'),
(3, 65, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'A dislocation is defined as:', '["A break in the bone near the joint line", "Inflammation of a bursa overlying the joint", "Complete loss of contact between the joint surfaces", "Partial tearing of a ligament around the joint"]'::jsonb, 2, 'Subluxation is partial displacement. Neurovascular status must be checked before and after reduction.', 'PON 417 · Trauma & Orthopaedics'),
(3, 66, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'In total knee replacement, an early rehabilitation device that moves the knee is the:', '["Halo vest with skull pins", "Collar and cuff sling", "Continuous passive motion (CPM) machine", "Thomas splint with skin traction"]'::jsonb, 2, 'CPM helps range of movement. Early physiotherapy, analgesia and VTE prophylaxis are essential.', 'PON 417 · Trauma & Orthopaedics'),
(3, 67, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'A Thomas splint is used mainly for:', '["Femoral shaft fractures", "Clavicle fractures", "Wrist fractures", "Neck fractures"]'::jsonb, 0, 'It provides traction and immobilisation and reduces bleeding into the thigh.', 'PON 417 · Trauma & Orthopaedics'),
(3, 68, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'Osteoporosis increases fracture risk mainly because:', '["Bones become too dense and brittle", "Muscles become weaker but bones stay normal", "Joints become infected and unstable", "Bone mass and density are reduced"]'::jsonb, 3, 'Risk factors are post-menopausal state, steroids, smoking, low calcium/vitamin D and immobility.', 'PON 417 · Trauma & Orthopaedics'),
(3, 69, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'Gas gangrene after a contaminated wound is caused by:', '["Pseudomonas only", "Staphylococcus epidermidis", "Streptococcus pyogenes only", "Clostridium perfringens"]'::jsonb, 3, 'It causes crepitus, foul-smelling discharge and rapid systemic toxicity. Treatment is urgent debridement, antibiotics and sometimes amputation.', 'PON 417 · Trauma & Orthopaedics'),
(3, 70, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'After amputation of a lower limb, the stump is positioned to prevent:', '["Hip and knee flexion contractures", "Muscle strengthening", "Swelling of the opposite limb", "Hip extension"]'::jsonb, 0, 'Avoid placing pillows under the stump for long periods. The patient lies prone periodically if allowed. Phantom limb pain is real and treated.', 'PON 417 · Trauma & Orthopaedics'),
(3, 71, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'The most common indication for caesarean section is:', '["Previous caesarean section, fetal distress and obstructed labour", "A small but healthy baby at term in cephalic presentation", "Maternal request alone, without any medical indication", "Uncomplicated twin pregnancy at 26 weeks of gestation"]'::jsonb, 0, 'Indications include cephalopelvic disproportion, placenta praevia, malpresentation, fetal distress, failed induction and previous scars.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 72, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'Before caesarean section, the theatre nurse ensures the patient is positioned:', '["Flat supine without any tilt", "Right lateral position on the table", "Supine with a left lateral tilt", "Prone with pillows under the hips"]'::jsonb, 2, 'Left tilt reduces aortocaval compression by the gravid uterus, preventing supine hypotension and fetal distress.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 73, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'Placenta praevia classically presents with:', '["Bleeding that occurs only after the delivery", "Sudden sharp abdominal pain without any bleeding", "Painful dark bleeding with a hard, tender uterus", "Painless bright red bleeding in late pregnancy"]'::jsonb, 3, 'Digital vaginal examination is avoided until praevia is excluded. Placental abruption is painful with a woody hard uterus.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 74, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'Placental abruption differs from placenta praevia in that abruption:', '["Is always painless, with bright red bleeding and a soft uterus", "Causes painful bleeding with a tense, tender uterus and fetal distress", "Only occurs before 20 weeks, so it is a cause of miscarriage", "Never causes maternal shock, because the blood loss is visible"]'::jsonb, 1, 'Concealed haemorrhage means visible blood loss may underestimate the true loss. DIC is a risk.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 75, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'The commonest site for an ectopic pregnancy is the:', '["Fallopian tube (ampulla)", "Abdominal cavity", "Cervix", "Ovary"]'::jsonb, 0, 'Risk factors are previous PID, tubal surgery, IUCD and previous ectopic. Ruptured ectopic is a surgical emergency.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 76, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'A ruptured ectopic pregnancy presents with:', '["Painless heavy bleeding at term with a soft, non-tender uterus", "Vulval itching and a thick white discharge without any pain", "Amenorrhoea, abdominal pain, spotting, shoulder tip pain and shock", "High blood pressure with headache, visual blurring and protein"]'::jsonb, 2, 'Shoulder tip pain is from blood irritating the diaphragm. Management: resuscitate, cross-match and urgent laparotomy/laparoscopy.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 77, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'The most common cause of primary postpartum haemorrhage is:', '["Retained placenta only", "Coagulation disorders", "Uterine atony", "Genital tract trauma only"]'::jsonb, 2, 'The ''4 Ts'': Tone, Trauma, Tissue, Thrombin. Atony is treated with uterine massage, oxytocics, bimanual compression and surgery if needed.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 78, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'Primary postpartum haemorrhage is defined as blood loss of:', '["500 mL or more within 24 h of vaginal birth", "50 mL or more within the first hour of birth", "500 mL or more between 6 and 12 weeks later", "100 mL or more within 24 h of vaginal birth"]'::jsonb, 0, 'For caesarean section, 1000 mL or more is often used. Secondary PPH occurs between 24 hours and 12 weeks.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 79, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'Surgical options when uterine atony does not respond to drugs include:', '["Cholecystectomy if the bleeding is from the liver bed after birth", "Bilateral tubal ligation to stop blood flowing through the tubes", "Balloon tamponade, B-Lynch suture, artery ligation, then hysterectomy", "Appendicectomy and peritoneal lavage to remove the retained blood"]'::jsonb, 2, 'The stepwise approach preserves fertility where possible; hysterectomy is the last resort.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 80, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'Hysterectomy that removes the uterus and cervix is called:', '["Total hysterectomy", "Myomectomy", "Oophorectomy", "Subtotal hysterectomy"]'::jsonb, 0, 'Subtotal leaves the cervix. Radical hysterectomy (Wertheim''s) includes parametrium, upper vagina and pelvic lymph nodes.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 81, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'Myomectomy is the surgical removal of:', '["The whole uterus and cervix", "Fibroids, keeping the uterus", "The fallopian tubes only", "Both ovaries and the tubes"]'::jsonb, 1, 'It is used in women who want to keep fertility. Blood loss can be significant; tourniquets or vasopressin may be used.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 82, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'Uterine fibroids (leiomyomas) are most common in:', '["Pre-pubertal girls, before the menarche begins", "Women on long-term progestogen-only contraception", "Post-menopausal women only, after oestrogen falls", "Women of reproductive age, especially of African descent"]'::jsonb, 3, 'They are benign oestrogen-dependent tumours causing heavy bleeding, pressure symptoms and infertility.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 83, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'The lithotomy position for vaginal surgery carries the risk of:', '["Common peroneal nerve injury and DVT from poor leg positioning", "Corneal eye injury in every case done under anaesthesia", "A pressure sore on the forehead from the head ring", "Brachial plexus injury only, from the arm boards being too high"]'::jsonb, 0, 'Both legs are lifted and lowered together by two people to avoid hip dislocation and back strain. Padding protects the lateral knee.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 84, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'During caesarean section, after delivery of the baby, the scrub nurse should be ready with:', '["A chest drain and underwater seal", "A bone saw and mallet for the pelvis", "Cord clamps and a bowl for the placenta", "An orthopaedic drill and a screw set"]'::jsonb, 2, 'The scrub nurse also records any swabs left in the uterus and ensures the count includes items used for the baby.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 85, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'Ovarian torsion presents with:', '["Vulval itching with a thick discharge and no pain", "Sudden one-sided pelvic pain with vomiting and an adnexal mass", "Gradual painless swelling of the abdomen over many months", "Painless bleeding from the bladder with clots in the urine"]'::jsonb, 1, 'It is a surgical emergency: urgent laparoscopy to detort and preserve the ovary.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 86, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'Vesicovaginal fistula (VVF), common in Nigeria, most often results from:', '["Long-term use of hormonal contraception", "Repeated lower urinary tract infections", "An uncomplicated elective caesarean section", "Prolonged obstructed labour causing pressure necrosis"]'::jsonb, 3, 'It causes continuous urinary leakage. Prevention is access to skilled birth attendance and timely caesarean section.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 87, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'Post-operative care after VVF repair includes:', '["Removing the catheter on day 1 so the patient can void normally", "Free bladder drainage for about 14 days, high fluid intake, patency checks", "Clamping the catheter regularly to train the bladder to hold urine", "Fluid restriction to reduce the pressure of urine on the repair"]'::jsonb, 1, 'A blocked catheter can rupture the repair. Fluid intake keeps urine dilute.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 88, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'Dilatation and curettage (D&C) may be complicated by:', '["Tension pneumothorax on one side", "Uterine perforation and haemorrhage", "Fracture of the neck of the femur", "Facial nerve palsy from positioning"]'::jsonb, 1, 'Signs of perforation include sudden loss of resistance to the instrument; observations and bleeding are monitored afterwards.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 89, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'Evacuation of retained products of conception (ERPC) is indicated in:', '["Normal pregnancy", "Ectopic pregnancy", "Threatened miscarriage with closed os and live fetus", "Incomplete miscarriage with heavy bleeding"]'::jsonb, 3, 'Manual vacuum aspiration is commonly used in Nigeria and is safer than sharp curettage.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 90, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'Pfannenstiel incision is a:', '["Low transverse suprapubic incision", "Vertical lower midline incision", "Lateral thoracotomy incision", "Right subcostal (Kocher) incision"]'::jsonb, 0, 'It gives good cosmesis and lower risk of hernia than vertical incisions.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 91, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'Classical (vertical upper segment) caesarean section is significant because:', '["It allows a safe trial of normal labour in the next pregnancy", "It carries a higher risk of uterine rupture in future pregnancies", "It does not leave any scar on the wall of the uterus", "It is the most common type of caesarean section done today"]'::jsonb, 1, 'Women with a classical scar should usually have elective caesarean section in subsequent pregnancies.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 92, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'The main intra-operative risk of laparoscopy in gynaecology is:', '["Cold burns to the skin from the CO₂ instruments", "Bowel, bladder or major vessel injury at trocar entry", "Brachial plexus injury from the steep head-up tilt", "Eye injury from the laparoscope light source"]'::jsonb, 1, 'Carbon dioxide insufflation can also cause shoulder tip pain and gas embolism.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 93, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'Ovarian hyperstimulation syndrome is associated with:', '["Total abdominal hysterectomy", "Elective caesarean section", "Fertility treatment with ovulation induction", "The natural menopause"]'::jsonb, 2, 'It causes fluid shift, ascites, haemoconcentration and thrombosis risk.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 94, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'Bartholin''s abscess is treated by:', '["Bilateral tubal ligation", "Cervical cerclage suture", "Total abdominal hysterectomy", "Incision, drainage and marsupialisation"]'::jsonb, 3, 'Marsupialisation creates a new opening to prevent recurrence.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 95, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'Cervical cerclage (e.g. McDonald suture) is done to:', '["Remove submucous fibroids through the cervix", "Induce labour by ripening and dilating the cervix", "Treat a cervical ectopic pregnancy without surgery", "Prevent miscarriage or preterm birth from cervical weakness"]'::jsonb, 3, 'The stitch is removed at about 37 weeks or if labour begins.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 96, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'Uterine rupture during labour may present with:', '["Painless rupture of the membranes with clear liquor draining", "Normal progress of labour with steady descent of the head", "Increased frequency of contractions only, with normal fetal heart", "Sudden severe pain, contractions stop, maternal shock, fetal distress"]'::jsonb, 3, 'Risk is higher with a previous scar and oxytocin use. Management is resuscitation and immediate laparotomy.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 97, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'After hysterectomy, a nurse should monitor for:', '["Hair loss caused by the anaesthetic agents used during surgery", "Vaginal bleeding, urinary retention or injury, DVT and wound infection", "Eye infection caused by the antiseptic used for skin preparation", "Hearing loss caused by the noise of the theatre equipment"]'::jsonb, 1, 'Ureteric injury may cause flank pain, fever or urine leakage. Early mobilisation is encouraged.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 98, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'Bilateral tubal ligation is a:', '["Treatment for tubal infertility", "Method of inducing labour at term", "Permanent method of sterilisation", "Temporary, reversible contraceptive"]'::jsonb, 2, 'Informed consent must stress permanence. It can be done at caesarean section or laparoscopically.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 99, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'Anti-D immunoglobulin after delivery is given to a:', '["Rh-negative mother with an Rh-positive baby", "Rh-positive mother with an Rh-negative baby", "Rh-negative baby born to any mother", "Any mother whose blood group is O"]'::jsonb, 0, 'It prevents maternal sensitisation, protecting future pregnancies from haemolytic disease of the newborn. It is given within 72 hours.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 100, 'Perioperative Mock — Day 1 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'Post-caesarean section, early mobilisation is encouraged mainly to:', '["Reduce the need for breastfeeding", "Reduce wound pain in the first day", "Reduce DVT and chest complications", "Reduce lochia flow from the uterus"]'::jsonb, 2, 'Pregnancy and the post-partum period increase VTE risk; LMWH and stockings may be prescribed.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(4, 1, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Paediatric Surgery', 'Projectile non-bilious vomiting in a 5-week-old boy with an ''olive'' mass in the epigastrium suggests:', '["Ileocolic intussusception", "Duodenal atresia with stenosis", "Hypertrophic pyloric stenosis", "Hirschsprung''s disease of the colon"]'::jsonb, 2, 'It causes hypochloraemic hypokalaemic metabolic alkalosis. Fluids and electrolytes are corrected before Ramstedt''s pyloromyotomy.', 'PON 423 · Paediatric Surgery'),
(4, 2, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Paediatric Surgery', 'Before pyloromyotomy, the most important preparation is:', '["Giving frequent small oral feeds to build up the baby''s strength", "Giving IV sodium bicarbonate to correct the acid-base disturbance", "Correcting dehydration and alkalosis with IV fluids and potassium", "Taking the baby to theatre immediately on arrival in the ward"]'::jsonb, 2, 'It is not a surgical emergency but a medical one. Anaesthesia with uncorrected alkalosis risks post-operative apnoea.', 'PON 423 · Paediatric Surgery'),
(4, 3, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Paediatric Surgery', 'Intussusception in an infant classically presents with:', '["Colicky pain with legs drawn up, a sausage mass and redcurrant jelly stool", "Failure to pass meconium in 48 hours with a distended abdomen only", "Painless projectile vomiting after every feed, with an olive-shaped mass", "Continuous drooling of frothy saliva with choking on the first feed"]'::jsonb, 0, 'Air or contrast enema reduction is first-line if no peritonitis; surgery if it fails or perforation occurs.', 'PON 423 · Paediatric Surgery'),
(4, 4, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Paediatric Surgery', 'Failure to pass meconium within 48 hours, abdominal distension and bilious vomiting in a newborn suggests:', '["Pyloric stenosis", "Inguinal hernia", "Hirschsprung''s disease", "Umbilical hernia"]'::jsonb, 2, 'Absence of ganglion cells in the distal bowel. Diagnosis is by rectal suction biopsy. Treatment is a pull-through procedure, sometimes after a colostomy.', 'PON 423 · Paediatric Surgery'),
(4, 5, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Paediatric Surgery', 'Bilious (green) vomiting in a newborn should always be treated as:', '["Normal possetting, which settles as the stomach matures", "A sign of overfeeding, managed by smaller, more frequent feeds", "A feeding problem only, managed by changing the formula", "A surgical emergency until malrotation with volvulus is excluded"]'::jsonb, 3, 'Midgut volvulus can cause bowel ischaemia within hours. Urgent contrast study and surgery (Ladd''s procedure) may be needed.', 'PON 423 · Paediatric Surgery'),
(4, 6, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Paediatric Surgery', 'A ''double bubble'' sign on newborn abdominal X-ray suggests:', '["Hirschsprung''s disease", "Gastroschisis", "Duodenal atresia", "Pyloric stenosis"]'::jsonb, 2, 'It is associated with Down syndrome. Management is nasogastric decompression, fluids and duodenoduodenostomy.', 'PON 423 · Paediatric Surgery'),
(4, 7, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Paediatric Surgery', 'Oesophageal atresia with tracheo-oesophageal fistula presents with:', '["Projectile non-bilious vomiting starting at about 6 weeks of age", "No anal opening, with meconium passing through the urethra", "Redcurrant jelly stool with colicky pain and a sausage-shaped mass", "Frothy saliva, choking and cyanosis with feeds; NG tube will not pass"]'::jsonb, 3, 'Preoperatively, a Replogle tube on continuous suction, nursing head-up, and nil by mouth prevent aspiration.', 'PON 423 · Paediatric Surgery'),
(4, 8, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Paediatric Surgery', 'Gastroschisis differs from exomphalos in that gastroschisis:', '["Has bowel outside beside the umbilicus with no covering sac", "Contains the liver and bowel within a thin covering sac", "Is always covered by a membrane of amnion and peritoneum", "Is strongly linked with trisomies and cardiac defects"]'::jsonb, 0, 'Exposed bowel is wrapped in cling film to reduce heat and fluid loss, the baby is nursed on the side, and IV fluids are started.', 'PON 423 · Paediatric Surgery'),
(4, 9, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Paediatric Surgery', 'Neonates are at special risk during surgery because of:', '["Mature thermoregulation that hides early signs of shock", "Low surface area to weight ratio that causes fluid overload", "High brown fat stores that cause overheating under the drapes", "Heat loss from large surface area, low glycogen and immature organs"]'::jsonb, 3, 'Theatre temperature is raised, warming mattresses and warmed fluids used, and glucose monitored.', 'PON 423 · Paediatric Surgery'),
(4, 10, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Paediatric Surgery', 'The usual age for repair of a cleft lip is about:', '["3 months of age", "1 week", "5 years", "12 years"]'::jsonb, 0, 'Common guidance is lip at 3 months (''rule of 10s'' historically), palate at 6-12 months before speech develops.', 'PON 423 · Paediatric Surgery'),
(4, 11, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Paediatric Surgery', 'After cleft palate repair, the child''s arms may be restrained with elbow splints to:', '["Prevent the child from crying after feeds", "Stop fingers and objects damaging the repair", "Encourage the child to sleep after surgery", "Prevent fractures of the arms on waking"]'::jsonb, 1, 'Feeding is by cup or spoon as advised; straws and teats may be avoided. Suction near the repair is avoided.', 'PON 423 · Paediatric Surgery'),
(4, 12, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Paediatric Surgery', 'Undescended testis (cryptorchidism) is usually corrected by orchidopexy at:', '["At puberty, when the testis enlarges", "6–12 months, before about 2 years", "At birth only, before the first feed", "In adulthood, when fertility is tested"]'::jsonb, 1, 'Early surgery reduces risk of infertility and makes testicular cancer easier to detect.', 'PON 423 · Paediatric Surgery'),
(4, 13, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Paediatric Surgery', 'Hypospadias is a condition in which:', '["The testis is absent from the scrotum on one side", "The urethral opening is on the upper side of the penis", "The foreskin is too tight to be pulled back over the glans", "The urethral opening is on the underside of the penis"]'::jsonb, 3, 'Circumcision is avoided because the foreskin may be needed for repair.', 'PON 423 · Paediatric Surgery'),
(4, 14, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Paediatric Surgery', 'An inguinal hernia in a child is usually due to:', '["Weak abdominal muscles from age", "A patent processus vaginalis", "Obesity", "Heavy lifting"]'::jsonb, 1, 'Infant hernias are repaired promptly because of a high risk of incarceration.', 'PON 423 · Paediatric Surgery'),
(4, 15, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Paediatric Surgery', 'Imperforate anus (anorectal malformation) is identified at birth by:', '["Absence of a normal anal opening on inspection", "Projectile vomiting after feeds in the first week", "Bilious vomiting starting at about 6 weeks of age", "Frothy saliva and choking at the first feed"]'::jsonb, 0, 'Associated anomalies form the VACTERL association (vertebral, anorectal, cardiac, tracheo-oesophageal, renal, limb).', 'PON 423 · Paediatric Surgery'),
(4, 16, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Paediatric Surgery', 'Wilms'' tumour (nephroblastoma) typically presents as:', '["A painless neck lump in an infant", "A painless abdominal mass in a young child", "Bone pain and swelling in a teenager", "Bloody diarrhoea with weight loss"]'::jsonb, 1, 'Avoid unnecessary palpation of the abdomen as it may cause rupture and spread.', 'PON 423 · Paediatric Surgery'),
(4, 17, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Paediatric Surgery', 'Fluid maintenance for a 10 kg child using the Holliday-Segar method is:', '["500 mL per 24 hours", "1000 mL per 24 hours", "2000 mL per 24 hours", "1500 mL per 24 hours"]'::jsonb, 1, '100 mL/kg for the first 10 kg, 50 mL/kg for the next 10 kg, and 20 mL/kg for each kg above 20.', 'PON 423 · Paediatric Surgery'),
(4, 18, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Paediatric Surgery', 'Pre-operative preparation of children should include:', '["Simple explanation, play therapy, and a parent at induction when possible", "Separating the child from the parents early so they settle in the ward", "Restraining the child firmly at induction without any explanation", "Telling the child nothing about the operation to avoid frightening them"]'::jsonb, 0, 'Reducing anxiety improves cooperation and reduces post-operative behavioural problems.', 'PON 423 · Paediatric Surgery'),
(4, 19, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Paediatric Surgery', 'Necrotising enterocolitis mostly affects:', '["School-age children after blunt abdominal trauma", "Adolescents presenting with acute appendicitis", "Toddlers after choking on a small toy or a peanut", "Premature neonates, with feed intolerance and bloody stool"]'::jsonb, 3, 'Management is stopping feeds, nasogastric decompression, antibiotics and surgery for perforation.', 'PON 423 · Paediatric Surgery'),
(4, 20, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Paediatric Surgery', 'Posterior urethral valves in boys cause:', '["Bloody diarrhoea with abdominal colic and weight loss", "Bladder outlet obstruction, poor stream and kidney damage", "An inguinal hernia only, with no effect on the kidneys", "Undescended testis with an empty scrotum on that side"]'::jsonb, 1, 'They may be diagnosed antenatally. Catheter drainage is followed by valve ablation.', 'PON 423 · Paediatric Surgery'),
(4, 21, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Urology', 'Renal colic pain is typically:', '["Dull constant suprapubic pain relieved by passing urine", "Central crushing chest pain radiating to the left arm", "Sharp pain on deep breathing only, with a pleural rub", "Severe colicky loin pain to the groin, with restlessness"]'::jsonb, 3, 'Haematuria is common. Analgesia (NSAIDs), imaging (CT KUB) and urgent decompression if infection with obstruction.', 'PON 423 · Urology'),
(4, 22, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Urology', 'An infected obstructed kidney requires:', '["Oral fluids and waiting for the stone to pass on its own", "Urgent drainage by nephrostomy or stent plus antibiotics", "Analgesia only, with a repeat scan in the clinic in 6 weeks", "Elective shock-wave lithotripsy booked in about 3 months"]'::jsonb, 1, 'Obstruction with infection can lead quickly to urosepsis and death.', 'PON 423 · Urology'),
(4, 23, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Urology', 'Benign prostatic hyperplasia commonly causes:', '["Fever, jaundice and right upper quadrant pain", "Haematemesis, epigastric pain and melaena", "Hesitancy, poor stream, frequency and nocturia", "A painful rash over the lower abdomen"]'::jsonb, 2, 'Treatment may include alpha-blockers, 5-alpha reductase inhibitors, or TURP.', 'PON 423 · Urology'),
(4, 24, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Urology', 'TURP syndrome results from:', '["Allergy to the latex of the three-way urinary catheter", "Absorption of normal saline irrigation, causing hypernatraemia", "Hypothermia only, from cold irrigation fluid in the bladder", "Absorption of hypotonic glycine irrigation, causing hyponatraemia"]'::jsonb, 3, 'Signs are confusion, nausea, bradycardia, hypertension then hypotension, visual disturbance and seizures. Spinal anaesthesia helps early detection because the patient is awake.', 'PON 423 · Urology'),
(4, 25, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Urology', 'After TURP, continuous bladder irrigation is used to:', '["Prevent clots and catheter blockage", "Provide nutrition through the bladder", "Treat post-operative hypertension", "Cool the patient''s core temperature"]'::jsonb, 0, 'Output must exceed irrigation input. Fluid balance should subtract the irrigation volume.', 'PON 423 · Urology'),
(4, 26, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Urology', 'If a three-way catheter with bladder irrigation blocks and the patient has suprapubic pain, the nurse should:', '["Stop the irrigation, check the system, and wash out or call the doctor", "Increase the irrigation rate to force the clot out of the catheter", "Clamp the drainage bag so the bladder fills and flushes itself", "Give an IV diuretic so that urine flow clears the blockage"]'::jsonb, 0, 'Continued irrigation into a blocked bladder can cause bladder distension and rupture.', 'PON 423 · Urology'),
(4, 27, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Urology', 'Testicular torsion is suspected in a teenager with:', '["Bilateral painless swelling that transilluminates", "Sudden severe testicular pain with a high-riding testis", "A painless, hard lump in the body of the testis", "Gradual mild ache over weeks, worse on standing"]'::jsonb, 1, 'It is a surgical emergency; the testis may be lost after 6 hours. Surgery is not delayed for imaging.', 'PON 423 · Urology'),
(4, 28, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Urology', 'A painless, firm testicular lump in a young man should be investigated urgently for:', '["Epididymitis only", "Varicocele only", "Testicular cancer", "Hydrocele only"]'::jsonb, 2, 'Ultrasound and tumour markers (AFP, beta-hCG, LDH) are done. Orchidectomy is via an inguinal approach.', 'PON 423 · Urology'),
(4, 29, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Urology', 'A hydrocele is:', '["Dilated veins of the spermatic cord", "A solid tumour of the testis itself", "Fluid around the testis that transilluminates", "An indirect inguinal hernia sac"]'::jsonb, 2, 'A varicocele feels like a ''bag of worms''. A hydrocele can be aspirated or repaired surgically.', 'PON 423 · Urology'),
(4, 30, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Urology', 'Painless frank haematuria in a smoker over 50 years should be investigated for:', '["Urinary tract infection only", "Renal colic", "Bladder cancer", "Prostatitis"]'::jsonb, 2, 'Investigations include cystoscopy and imaging of the upper tracts.', 'PON 423 · Urology'),
(4, 31, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Urology', 'Urinary diversion by ileal conduit means:', '["Urine drains normally through the urethra after bladder removal", "Ureters drain into an ileal segment brought out as a stoma", "The bladder is reconstructed using a segment of the colon", "A catheter is left permanently in the urethra after cystectomy"]'::jsonb, 1, 'Mucus in urine is normal. The stoma should be pink and moist; urine output is monitored.', 'PON 423 · Urology'),
(4, 32, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Urology', 'Percutaneous nephrolithotomy (PCNL) is done for:', '["Prostate enlargement, through the perineum", "Ureteric strictures, through the urethra", "Large renal stones, through a track in the loin", "Bladder tumours, through the suprapubic skin"]'::jsonb, 2, 'Complications include bleeding, infection and pleural injury.', 'PON 423 · Urology'),
(4, 33, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Urology', 'Extracorporeal shock wave lithotripsy (ESWL) is used to:', '["Create a urostomy without surgery", "Break kidney stones with external shock waves", "Untwist a torsion of the testis", "Remove the prostate through the urethra"]'::jsonb, 1, 'Fragments pass in the urine; patients are advised to drink plenty and strain urine.', 'PON 423 · Urology'),
(4, 34, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Urology', 'A suprapubic catheter is inserted:', '["Through the rectum into the bladder", "Through the abdominal wall into the bladder", "Through the loin into the kidney", "Through the urethra into the bladder"]'::jsonb, 1, 'It is used in urethral stricture, trauma or long-term catheterisation.', 'PON 423 · Urology'),
(4, 35, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Urology', 'Urethral catheterisation should not be attempted in pelvic trauma with:', '["Clear urine in the drainage bag", "A normal hourly urine output", "An associated fractured wrist", "Blood at the urethral meatus"]'::jsonb, 3, 'Blood at the meatus suggests urethral injury. A retrograde urethrogram is done first; suprapubic catheterisation may be needed.', 'PON 423 · Urology'),
(4, 36, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Urology', 'Before cystoscopy, the patient''s urine is checked to:', '["Determine the blood group", "Measure the blood glucose level", "Exclude an active urinary infection", "Check for pregnancy only"]'::jsonb, 2, 'Instrumenting an infected urinary tract may cause bacteraemia and sepsis.', 'PON 423 · Urology'),
(4, 37, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Urology', 'Radical prostatectomy is mainly associated with the long-term complications of:', '["Chronic kidney disease and anaemia", "Faecal incontinence and rectal prolapse", "Bladder stones and recurrent infection", "Urinary incontinence and erectile dysfunction"]'::jsonb, 3, 'Pelvic floor exercises are taught before and after surgery.', 'PON 423 · Urology'),
(4, 38, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Urology', 'Urethral stricture commonly follows:', '["Long-standing essential hypertension", "Trauma, instrumentation, or infection such as gonorrhoea", "Type 2 diabetes mellitus alone", "Pregnancy and childbirth in the previous year"]'::jsonb, 1, 'It presents with poor stream and straining. Treatment includes dilatation, urethrotomy or urethroplasty.', 'PON 423 · Urology'),
(4, 39, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Urology', 'Normal post-operative urine output for a 70 kg adult is at least about:', '["5 mL per hour", "3 mL per hour", "35 mL per hour", "100 mL per day"]'::jsonb, 2, '0.5 mL/kg/hour multiplied by 70 kg gives 35 mL/hour.', 'PON 423 · Urology'),
(4, 40, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Urology', 'A patient after nephrectomy should be monitored especially for:', '["Visual problems from the anaesthetic agents used", "Bleeding, function of the remaining kidney, and chest problems", "Hair loss from stress after the major operation", "Hearing loss from the loop diuretics given after surgery"]'::jsonb, 1, 'Flank incision near the diaphragm causes painful breathing and increases risk of atelectasis or pneumothorax.', 'PON 423 · Urology'),
(4, 41, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Neurosurgery', 'The Glasgow Coma Scale scores which three responses?', '["Pupils, pulse and blood pressure", "Speech, hearing and visual acuity", "Eye opening, verbal response and motor response", "Reflexes, sensation and power"]'::jsonb, 2, 'Scores range from 3 to 15. A GCS of 8 or less usually needs airway protection.', 'PON 423 · Neurosurgery'),
(4, 42, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Neurosurgery', 'Cushing''s triad of rising intracranial pressure is:', '["Hypotension, tachycardia and fever with a rapid, shallow breathing pattern", "Hypertension with wide pulse pressure, bradycardia and irregular breathing", "Tachycardia, hypertension and diarrhoea with flushing and sweating", "Hypotension, bradycardia and polyuria with dilute urine and thirst"]'::jsonb, 1, 'It is a late sign indicating imminent brain herniation and requires urgent intervention.', 'PON 423 · Neurosurgery'),
(4, 43, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Neurosurgery', 'A lucid interval after head injury followed by rapid deterioration is typical of:', '["Extradural (epidural) haematoma", "Chronic subdural haematoma", "Migraine", "Concussion"]'::jsonb, 0, 'It is usually from middle meningeal artery bleeding after a temporal bone fracture. Urgent craniotomy saves life.', 'PON 423 · Neurosurgery'),
(4, 44, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Neurosurgery', 'A fixed dilated pupil on one side after head injury suggests:', '["Hypoglycaemia from not eating since the time of the injury", "Opioid overdose from the analgesia given in the emergency room", "Oculomotor nerve compression from raised pressure on that side", "Normal recovery as the effect of the anaesthetic wears off"]'::jsonb, 2, 'This is a sign of uncal herniation and needs urgent neurosurgical intervention.', 'PON 423 · Neurosurgery'),
(4, 45, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Neurosurgery', 'Nursing measures to reduce raised intracranial pressure include:', '["Allowing the PaCO₂ and temperature to rise without treatment", "Encouraging coughing, straining and frequent deep suctioning", "Lying flat with the neck flexed forward on two pillows", "Head up 30°, head midline, loose ties, normal CO₂ and treating fever"]'::jsonb, 3, 'Hypoxia, hypercapnia, pain, seizures and fever all raise intracranial pressure.', 'PON 423 · Neurosurgery'),
(4, 46, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Neurosurgery', 'Mannitol is given in raised intracranial pressure to:', '["Increase the blood glucose for the brain", "Reduce headache by blocking pain fibres", "Prevent infection of the cerebrospinal fluid", "Draw water out of the brain by osmosis"]'::jsonb, 3, 'Urinary catheterisation is needed because of diuresis, and serum osmolality is monitored.', 'PON 423 · Neurosurgery'),
(4, 47, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Neurosurgery', 'Clear fluid leaking from the nose after a head injury that tests positive for glucose suggests:', '["CSF leak from a basal skull fracture", "Normal nasal secretion after crying", "Acute sinusitis from the nasal injury", "Allergic rhinitis triggered by dust"]'::jsonb, 0, 'The patient should not blow the nose; nasal tubes are avoided. Battle''s sign and raccoon eyes also suggest basal fracture.', 'PON 423 · Neurosurgery'),
(4, 48, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Neurosurgery', 'A ventriculo-peritoneal (VP) shunt is used to treat:', '["Stroke", "Hydrocephalus", "Migraine", "Brain abscess"]'::jsonb, 1, 'Shunt blockage presents with headache, vomiting, drowsiness and in infants a bulging fontanelle.', 'PON 423 · Neurosurgery'),
(4, 49, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Neurosurgery', 'After craniotomy, a sudden decrease in level of consciousness should be:', '["Treated with a sedative so the patient can rest well", "Reported at once as it may mean bleeding or swelling", "Ignored, because the patient is simply sleeping deeply", "Recorded at the end of the shift in the nursing notes"]'::jsonb, 1, 'Neurological observations are frequent post-operatively. A drop of 2 points or more in GCS is significant.', 'PON 423 · Neurosurgery'),
(4, 50, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Neurosurgery', 'Spina bifida with myelomeningocele requires pre-operative care that includes:', '["Nurse the baby supine on the sac to keep pressure on the defect", "Cover the sac with a sterile moist non-adherent dressing; nurse prone", "Leave the sac exposed and dry so that it forms a protective scab", "Apply a tight crepe bandage over the sac to prevent it rupturing"]'::jsonb, 1, 'This prevents rupture and infection. Hydrocephalus often develops; head circumference is monitored.', 'PON 423 · Neurosurgery'),
(4, 51, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Neurosurgery', 'Chronic subdural haematoma is most likely in:', '["Infants with fever only and no history of any injury at all", "Young athletes with immediate collapse after a heavy blow to the head", "Pregnant women with hypertension, proteinuria and headache", "Elderly people and alcoholics after minor injury, with gradual confusion"]'::jsonb, 3, 'Brain atrophy stretches bridging veins. Treatment is burr-hole drainage.', 'PON 423 · Neurosurgery'),
(4, 52, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Neurosurgery', 'Subarachnoid haemorrhage presents with:', '["Fever, productive cough and pleuritic chest pain for a week", "Sudden ''thunderclap'' headache, neck stiffness and photophobia", "Gradual mild headache that is relieved by rest and paracetamol", "Painless loss of vision in one eye with no headache at all"]'::jsonb, 1, 'It is most often due to ruptured berry aneurysm. Vasospasm is prevented with nimodipine.', 'PON 423 · Neurosurgery'),
(4, 53, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Neurosurgery', 'Diabetes insipidus after pituitary surgery presents with:', '["Large volumes of dilute urine with a rising sodium", "Very low urine output with fluid overload and oedema", "Low serum sodium with confusion and seizures", "Concentrated dark urine with a falling serum sodium"]'::jsonb, 0, 'It is due to lack of ADH. Fluid balance and serum sodium are monitored; desmopressin may be given.', 'PON 423 · Neurosurgery'),
(4, 54, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Neurosurgery', 'For a patient with a cervical spine injury, the airway is opened with:', '["Head tilt and chin lift", "Two pillows under the head", "Neck flexion on a pillow", "Jaw thrust without head tilt"]'::jsonb, 3, 'Manual in-line stabilisation protects the spinal cord.', 'PON 423 · Neurosurgery'),
(4, 55, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Neurosurgery', 'A patient with a skull fracture and bruising behind the ear has:', '["Cullen''s sign of acute pancreatitis", "Battle''s sign of a basal skull fracture", "Grey Turner''s sign of retroperitoneal bleeding", "Trousseau''s sign of hypocalcaemia"]'::jsonb, 1, 'Periorbital bruising (raccoon eyes) is another sign of basal skull fracture.', 'PON 423 · Neurosurgery'),
(4, 56, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Neurosurgery', 'Seizure prophylaxis after brain surgery commonly uses:', '["Aspirin", "Levetiracetam or phenytoin", "Paracetamol", "Ondansetron"]'::jsonb, 1, 'Seizures increase intracranial pressure and cerebral oxygen demand.', 'PON 423 · Neurosurgery'),
(4, 57, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Neurosurgery', 'Lumbar disc prolapse with saddle anaesthesia, urinary retention and leg weakness suggests:', '["Renal colic", "Simple back strain", "Cauda equina syndrome", "Sciatica only"]'::jsonb, 2, 'It is a surgical emergency requiring urgent MRI and decompression to prevent permanent bladder and bowel dysfunction.', 'PON 423 · Neurosurgery'),
(4, 58, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Neurosurgery', 'The positioning concern in neurosurgery performed in the sitting position is:', '["Venous air embolism", "Lithotomy nerve injury", "Hip dislocation", "Aortocaval compression"]'::jsonb, 0, 'Veins above heart level have negative pressure and can entrain air. Monitoring end-tidal CO2 and Doppler helps detection.', 'PON 423 · Neurosurgery'),
(4, 59, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Neurosurgery', 'The headache of raised intracranial pressure is typically:', '["Relieved by straining, coughing and bending forwards", "Relieved by lying flat and worse on sitting up or standing", "Present only in the evening, after a long day of work", "Worse in the morning and on coughing or bending, with vomiting"]'::jsonb, 3, 'Papilloedema may be seen on fundoscopy.', 'PON 423 · Neurosurgery'),
(4, 60, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Neurosurgery', 'Brain tumour patients are often given dexamethasone pre-operatively to:', '["Reduce oedema around the tumour", "Prevent pain only, with no other effect", "Treat infection in the tumour bed", "Lower the blood glucose before surgery"]'::jsonb, 0, 'Steroids raise blood glucose and increase infection risk; glucose is monitored.', 'PON 423 · Neurosurgery'),
(4, 61, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Cardiothoracic Surgery', 'Cardiopulmonary bypass during heart surgery:', '["Is used only for children, because adults cannot tolerate bypass", "Only removes carbon dioxide while the lungs continue to ventilate", "Takes over heart and lung function so the heart can be stopped", "Replaces the kidneys by filtering the blood during the operation"]'::jsonb, 2, 'Patients are fully heparinised during bypass, then heparin is reversed with protamine.', 'PON 423 · Cardiothoracic Surgery'),
(4, 62, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Cardiothoracic Surgery', 'After open heart surgery, cardiac tamponade presents with:', '["Hypotension, raised JVP, muffled heart sounds and a sudden fall in drain output", "Increased urine output with warm peripheries and strong peripheral pulses", "Low JVP with loud heart sounds and a steady drain output of serous fluid", "Hypertension with bradycardia and a large increase in chest drain output"]'::jsonb, 0, 'Sudden cessation of drainage may mean clots are blocking the tubes. Urgent re-opening may be needed.', 'PON 423 · Cardiothoracic Surgery'),
(4, 63, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Cardiothoracic Surgery', 'A chest drain connected to an underwater seal should be kept:', '["Clamped routinely during every transfer", "On the bed beside the patient''s pillow", "Below the level of the chest at all times", "Above the level of the chest when moving"]'::jsonb, 2, 'Keeping the bottle below the chest prevents fluid backflow into the pleural space.', 'PON 423 · Cardiothoracic Surgery'),
(4, 64, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Cardiothoracic Surgery', 'Swinging (tidalling) of fluid in the chest drain tube with breathing indicates:', '["The tube is patent and in the pleural space", "The tube is blocked by a clot or kink", "There is an air leak in the drainage system", "The patient is bleeding heavily into the chest"]'::jsonb, 0, 'Absence of swing may mean blockage, kinking or full lung re-expansion.', 'PON 423 · Cardiothoracic Surgery'),
(4, 65, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Cardiothoracic Surgery', 'Continuous bubbling in the underwater seal chamber suggests:', '["A blocked or kinked chest tube", "An air leak from the lung or the system", "Full re-expansion of the lung", "Normal functioning with no air leak"]'::jsonb, 1, 'Check connections from the patient to the bottle. Persistent air leak from the lung (bronchopleural fistula) is reported.', 'PON 423 · Cardiothoracic Surgery'),
(4, 66, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Cardiothoracic Surgery', 'If a chest drain becomes disconnected, the nurse should:', '["Leave the tube open to the air until the doctor reconnects it", "Remove the chest tube completely and cover the site with gauze", "Pull the tube out a few centimetres so that air cannot enter", "Put the end under sterile water (or clamp briefly) and reconnect"]'::jsonb, 3, 'Air entering through the tube can cause pneumothorax. Many units prefer to submerge the end in sterile water rather than clamp.', 'PON 423 · Cardiothoracic Surgery'),
(4, 67, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Cardiothoracic Surgery', 'Tension pneumothorax is treated immediately by:', '["High-flow oxygen alone and observation", "IV diuretics to reduce lung congestion", "Waiting for a chest X-ray to confirm it", "Needle decompression, then a chest drain"]'::jsonb, 3, 'It is a clinical diagnosis: hypoxia, hypotension, tracheal deviation away from the affected side, reduced breath sounds.', 'PON 423 · Cardiothoracic Surgery'),
(4, 68, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Cardiothoracic Surgery', 'Lung resection called pneumonectomy refers to removal of:', '["The trachea", "One lobe of a lung", "A wedge of lung tissue", "An entire lung"]'::jsonb, 3, 'After pneumonectomy, a chest drain is often not connected to suction to avoid mediastinal shift.', 'PON 423 · Cardiothoracic Surgery'),
(4, 69, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Cardiothoracic Surgery', 'A thoracotomy patient needs good analgesia mainly to:', '["Improve the appetite so that oral feeding can start early", "Reduce the urine output so that a catheter is not needed", "Allow deep breathing and coughing, preventing chest complications", "Prevent hair loss caused by the stress of major surgery"]'::jsonb, 2, 'Epidural or paravertebral blocks are often used.', 'PON 423 · Cardiothoracic Surgery'),
(4, 70, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Cardiothoracic Surgery', 'Mitral stenosis in Nigeria is most often due to:', '["Rheumatic heart disease after streptococcal throat infection", "Long-standing essential hypertension in older adults", "Diabetes mellitus causing valve calcification", "Congenital causes only, present from birth in all patients"]'::jsonb, 0, 'Rheumatic fever prevention includes treating sore throats with penicillin.', 'PON 423 · Cardiothoracic Surgery'),
(4, 71, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Cardiothoracic Surgery', 'Patients with mechanical heart valves need lifelong:', '["Warfarin anticoagulation with INR monitoring", "Long-term oral steroids to prevent rejection", "No medication once the wound has healed", "Low-dose aspirin only, with no blood tests"]'::jsonb, 0, 'Antibiotic prophylaxis may be advised for some procedures.', 'PON 423 · Cardiothoracic Surgery'),
(4, 72, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Cardiothoracic Surgery', 'Coronary artery bypass grafting commonly uses which vessels as grafts?', '["Ascending aorta and pulmonary artery", "Common carotid artery and radial vein", "Saphenous vein and internal mammary artery", "Femoral artery and internal jugular vein"]'::jsonb, 2, 'Leg wound care is important after saphenous vein harvest.', 'PON 423 · Cardiothoracic Surgery'),
(4, 73, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Cardiothoracic Surgery', 'Tetralogy of Fallot includes:', '["ASD, VSD, PDA and pulmonary hypertension together", "PDA, aortic stenosis, coarctation and LV hypertrophy", "ASD, mitral stenosis, dilated aorta and LV hypertrophy", "VSD, pulmonary stenosis, overriding aorta and RV hypertrophy"]'::jsonb, 3, 'Children may squat to relieve ''tet spells''. Surgical repair is usually done in infancy.', 'PON 423 · Cardiothoracic Surgery'),
(4, 74, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Cardiothoracic Surgery', 'Patent ductus arteriosus in a premature baby may close with:', '["Indomethacin or ibuprofen", "Diuretics only", "Oxygen restriction", "Prostaglandin E1"]'::jsonb, 0, 'Prostaglandin E1 keeps the duct open in duct-dependent heart lesions.', 'PON 423 · Cardiothoracic Surgery'),
(4, 75, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Cardiothoracic Surgery', 'Pericardiocentesis is performed to:', '["Remove ascitic fluid from the abdomen", "Remove fluid from the pericardial sac", "Drain urine from an obstructed bladder", "Remove fluid from the pleural space"]'::jsonb, 1, 'The patient is monitored on ECG because arrhythmias can occur if the needle touches the heart.', 'PON 423 · Cardiothoracic Surgery'),
(4, 76, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Cardiothoracic Surgery', 'After cardiac surgery, the nurse monitors for low cardiac output by observing:', '["Hypotension, cold peripheries, low urine output and rising lactate", "Bradycardia alone with good peripheral perfusion", "Normal blood pressure with warm hands and a falling lactate", "Warm pink skin, bounding pulses and a high urine output"]'::jsonb, 0, 'Inotropes, fluid and pacing may be required.', 'PON 423 · Cardiothoracic Surgery'),
(4, 77, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Cardiothoracic Surgery', 'Temporary epicardial pacing wires after heart surgery are used to:', '["Measure the oxygen saturation", "Measure the arterial blood pressure", "Treat bradycardia or heart block", "Drain blood from the pericardium"]'::jsonb, 2, 'The wires are removed before discharge; the patient is monitored for tamponade afterwards.', 'PON 423 · Cardiothoracic Surgery'),
(4, 78, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Cardiothoracic Surgery', 'Empyema thoracis is:', '["Blood in the pleural cavity", "Air in the pleural cavity", "Pus in the pleural cavity", "Fluid in the pericardium"]'::jsonb, 2, 'Treatment is antibiotics and drainage by chest tube or decortication.', 'PON 423 · Cardiothoracic Surgery'),
(4, 79, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Cardiothoracic Surgery', 'Before removal of a chest drain, the patient is asked to:', '["Cough repeatedly to push the tube out of the chest", "Breathe rapidly and shallowly while the tube is pulled out", "Lie prone with the arms above the head during removal", "Take a deep breath and hold it (or Valsalva) as it is pulled"]'::jsonb, 3, 'This reduces the chance of air entering the pleural space. An occlusive dressing is applied.', 'PON 423 · Cardiothoracic Surgery'),
(4, 80, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Cardiothoracic Surgery', 'Air embolism during central line removal is prevented by:', '["Sitting upright with the legs over the side of the bed", "Taking a deep breath in as the catheter is pulled out", "Lying flat or head-down, breath held, occlusive dressing", "Leaving the site uncovered so it can be observed"]'::jsonb, 2, 'This keeps venous pressure positive at the site.', 'PON 423 · Cardiothoracic Surgery'),
(4, 81, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Reconstructive (Plastic) Surgery', 'A split-thickness skin graft includes:', '["The full thickness of skin with fat", "Muscle and skin", "Bone and skin", "The epidermis and part of the dermis"]'::jsonb, 3, 'The donor site heals by re-epithelialisation in 10-14 days. Full-thickness grafts include all the dermis and are used on the face.', 'PON 423 · Reconstructive (Plastic) Surgery'),
(4, 82, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Reconstructive (Plastic) Surgery', 'The most common cause of skin graft failure is:', '["Too much immobilisation of the graft", "A clean, well-vascularised wound bed", "Using a split-thickness skin graft", "Haematoma or seroma under the graft"]'::jsonb, 3, 'Fluid separates the graft from the bed, preventing revascularisation. Infection and shear are also causes.', 'PON 423 · Reconstructive (Plastic) Surgery'),
(4, 83, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Reconstructive (Plastic) Surgery', 'The donor site of a split-thickness skin graft is often more painful than the recipient site because:', '["Nerve endings are exposed", "It is always bandaged tightly", "It is deeper than the recipient site", "It is infected"]'::jsonb, 0, 'The donor site is covered with a non-adherent dressing and left undisturbed while it heals.', 'PON 423 · Reconstructive (Plastic) Surgery'),
(4, 84, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Reconstructive (Plastic) Surgery', 'A free flap differs from a pedicled flap in that a free flap:', '["Does not need any monitoring once it has been sutured", "Keeps its original blood supply through an attached base", "Uses only skin and fat, without any named blood vessels", "Is fully detached and its vessels rejoined by microsurgery"]'::jsonb, 3, 'Free flaps need close monitoring of colour, temperature, capillary refill and Doppler signal.', 'PON 423 · Reconstructive (Plastic) Surgery'),
(4, 85, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Reconstructive (Plastic) Surgery', 'A free flap that becomes dark blue or purple with rapid capillary refill suggests:', '["Venous congestion", "Infection", "Normal flap", "Arterial insufficiency"]'::jsonb, 0, 'A pale cold flap with slow refill suggests arterial problems. Both require urgent surgical review.', 'PON 423 · Reconstructive (Plastic) Surgery'),
(4, 86, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Reconstructive (Plastic) Surgery', 'A patient with a free flap should avoid:', '["Smoking, caffeine, cold and pressure on the flap", "Adequate hydration with a good urine output", "Regular analgesia to control pain and anxiety", "A warm environment and warmed IV fluids"]'::jsonb, 0, 'Vasoconstriction compromises flap perfusion.', 'PON 423 · Reconstructive (Plastic) Surgery'),
(4, 87, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Reconstructive (Plastic) Surgery', 'Hypertrophic scars and keloids are more common in:', '["People with lighter skin only, in sun-exposed areas", "Elderly patients only, because their skin is thinner", "People with darker skin, and wounds under tension", "Wounds without tension, such as on the eyelids"]'::jsonb, 2, 'Keloids extend beyond the original wound; hypertrophic scars stay within it.', 'PON 423 · Reconstructive (Plastic) Surgery'),
(4, 88, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Reconstructive (Plastic) Surgery', 'Treatments for keloids include:', '["Steroid injection, pressure, silicone gel, and excision with adjuvant therapy", "Long courses of oral antibiotics, because keloids are caused by infection", "Simple surgical excision alone, which cures nearly every keloid permanently", "No treatment at all, because no method has any effect on keloid scars"]'::jsonb, 0, 'Simple excision alone has a high recurrence rate.', 'PON 423 · Reconstructive (Plastic) Surgery'),
(4, 89, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Reconstructive (Plastic) Surgery', 'Pressure garments after burns help to:', '["Promote bacterial growth", "Increase swelling of the limb", "Prevent the wound from healing", "Reduce hypertrophic scarring"]'::jsonb, 3, 'They are worn for up to 23 hours a day for many months.', 'PON 423 · Reconstructive (Plastic) Surgery'),
(4, 90, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Reconstructive (Plastic) Surgery', 'Z-plasty is used to:', '["Remove tattoos by excision and grafting", "Treat infected wounds by opening them", "Lengthen and reorient a scar contracture", "Close wounds without the need for sutures"]'::jsonb, 2, 'Burn contractures across joints are often released with Z-plasty or grafts.', 'PON 423 · Reconstructive (Plastic) Surgery'),
(4, 91, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Reconstructive (Plastic) Surgery', 'A pressure ulcer that involves full-thickness skin loss with visible fat but no bone or tendon is classified as:', '["Category/stage 1", "Category/stage 2", "Category/stage 3", "Category/stage 4"]'::jsonb, 2, 'Stage 4 involves exposed bone, tendon or muscle. Reconstruction may involve flaps.', 'PON 423 · Reconstructive (Plastic) Surgery'),
(4, 92, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Reconstructive (Plastic) Surgery', 'The ''reconstructive ladder'' refers to:', '["A ranking of plastic surgeons according to their experience", "Using the simplest closure that works, moving up to complex methods", "The ladders used in theatre to reach the high operating lights", "A grading of scars from flat and pale to raised and red"]'::jsonb, 1, 'Steps include healing by secondary intention, primary closure, grafts, local flaps, distant flaps and free flaps.', 'PON 423 · Reconstructive (Plastic) Surgery'),
(4, 93, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Reconstructive (Plastic) Surgery', 'The best way to preserve an amputated finger for replantation is:', '["Place the finger in a cup of tap water", "Wrap in saline-moist gauze, seal in a bag, then place on ice", "Place the finger directly on ice in a cool box", "Keep the finger dry at room temperature"]'::jsonb, 1, 'Direct contact with ice causes frostbite injury to the tissue.', 'PON 423 · Reconstructive (Plastic) Surgery'),
(4, 94, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Reconstructive (Plastic) Surgery', 'Tissue expansion involves:', '["Using hot water soaks to soften and stretch the skin", "Injecting fat into the skin to increase its thickness", "Gradually inflating a balloon under the skin to stretch it", "Grafting skin taken from another person (a donor)"]'::jsonb, 2, 'It is used in breast reconstruction and scalp reconstruction.', 'PON 423 · Reconstructive (Plastic) Surgery'),
(4, 95, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Reconstructive (Plastic) Surgery', 'Cleft palate surgery mainly aims to:', '["Improve speech, feeding and hearing", "Treat a fracture of the upper jaw", "Improve vision and eye movement", "Correct an associated inguinal hernia"]'::jsonb, 0, 'A multidisciplinary team includes speech therapists, orthodontists and ENT.', 'PON 423 · Reconstructive (Plastic) Surgery'),
(4, 96, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Reconstructive (Plastic) Surgery', 'Breast reconstruction after mastectomy can use:', '["Implants or flaps such as latissimus dorsi or DIEP", "Bone grafts taken from the iliac crest", "Cartilage grafts taken from the ribs only", "Split-thickness skin grafts only, without any implant"]'::jsonb, 0, 'Timing may be immediate or delayed.', 'PON 423 · Reconstructive (Plastic) Surgery'),
(4, 97, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Reconstructive (Plastic) Surgery', 'A full-thickness skin graft is preferred for the face because it:', '["Can cover much larger areas than a split graft", "Has better colour match and less contraction", "Heals faster at the donor site than a split graft", "Is quicker and easier to take than other grafts"]'::jsonb, 1, 'Common donor sites are behind the ear and above the clavicle.', 'PON 423 · Reconstructive (Plastic) Surgery'),
(4, 98, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Reconstructive (Plastic) Surgery', 'Graft ''take'' begins with:', '["Infection, then granulation of the bed", "Immediate full blood supply from the bed", "Scar formation, then epithelial growth", "Plasmatic imbibition, then inosculation"]'::jsonb, 3, 'The graft absorbs nutrients from the bed for the first 48 hours, then vessels connect.', 'PON 423 · Reconstructive (Plastic) Surgery'),
(4, 99, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Reconstructive (Plastic) Surgery', 'Surgical debridement of a wound means:', '["Adding healthy tissue such as a skin graft", "Applying an antiseptic dressing to the wound", "Closing the wound immediately with sutures", "Removal of dead, damaged or infected tissue"]'::jsonb, 3, 'Debridement promotes healing and reduces infection.', 'PON 423 · Reconstructive (Plastic) Surgery'),
(4, 100, 'Perioperative Mock — Day 2 Morning (Nov 2026)', 'PON 423 · Reconstructive (Plastic) Surgery', 'Negative pressure wound therapy (vacuum dressing) helps by:', '["Removing exudate, reducing oedema, promoting granulation", "Reducing blood flow to the wound to stop bleeding", "Keeping bacteria in the wound to stimulate healing", "Drying out the wound bed completely so it scabs over"]'::jsonb, 0, 'It is contraindicated over exposed vessels, untreated osteomyelitis and malignancy.', 'PON 423 · Reconstructive (Plastic) Surgery'),
(5, 1, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'PON 417 · Maxillofacial Surgery', 'After mandibular fracture fixation with intermaxillary (wire) fixation, the item that must always be at the bedside is:', '["Wire cutters or scissors", "A plaster saw", "A urinary catheter", "A tongue depressor only"]'::jsonb, 0, 'If the patient vomits or the airway is compromised, the wires must be cut immediately. Staff must know which wires to cut.', 'PON 417 · Maxillofacial Surgery'),
(5, 2, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'PON 417 · Maxillofacial Surgery', 'The main airway risk after major maxillofacial surgery is:', '["Swelling, bleeding and secretions blocking the upper airway", "Bronchospasm from the volatile agent used during the operation", "Laryngeal oedema from an allergy to the antibiotic given", "Tension pneumothorax from the central line inserted in theatre"]'::jsonb, 0, 'Patients may have a nasopharyngeal airway or tracheostomy. Suction, head elevation and close observation are essential.', 'PON 417 · Maxillofacial Surgery'),
(5, 3, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'PON 417 · Maxillofacial Surgery', 'A Le Fort I fracture is a:', '["A fracture through the neck of the mandibular condyle", "A horizontal fracture separating the tooth-bearing maxilla", "A fracture separating the whole face from the skull", "A fracture of the nasal bones and septum only"]'::jsonb, 1, 'Le Fort II is pyramidal through the nasal bridge; Le Fort III is craniofacial dysjunction.', 'PON 417 · Maxillofacial Surgery'),
(5, 4, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'PON 417 · Maxillofacial Surgery', 'In facial trauma with suspected Le Fort II or III fracture, the nurse should avoid:', '["Sitting up once the spine is cleared", "Giving high-flow oxygen by face mask", "Passing a nasogastric or nasopharyngeal tube", "Suctioning blood from the mouth"]'::jsonb, 2, 'These fractures can involve the cribriform plate; a tube passed through the nose can enter the cranial cavity.', 'PON 417 · Maxillofacial Surgery'),
(5, 5, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'PON 417 · Maxillofacial Surgery', 'Ludwig''s angina is:', '["A type of cardiac chest pain that radiates up into the lower jaw", "A deep dental cavity in a lower molar causing severe toothache", "A stone blocking the submandibular duct, causing swelling at meals", "Spreading cellulitis of the mouth floor that can block the airway"]'::jsonb, 3, 'It is usually from a lower molar infection. Airway management is the priority, followed by antibiotics and surgical drainage.', 'PON 417 · Maxillofacial Surgery'),
(5, 6, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'PON 417 · Maxillofacial Surgery', 'The commonest cause of trismus after dental extraction or infection is:', '["Fracture of the skull base after the extraction", "Hypocalcaemia only, from poor oral intake", "Facial nerve palsy from the dental injection", "Spasm of the chewing muscles from inflammation"]'::jsonb, 3, 'Trismus can make intubation very difficult; anaesthetists may need fibreoptic intubation.', 'PON 417 · Maxillofacial Surgery'),
(5, 7, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'PON 417 · Maxillofacial Surgery', 'Oral care after jaw surgery with intermaxillary fixation includes:', '["A hard toothbrush to remove debris trapped around the wires", "Solid food to exercise and strengthen the jaws as they heal", "Frequent mouthwashes, soft brushing and a high-calorie liquid diet", "Avoiding all oral hygiene until the wires are removed in 6 weeks"]'::jsonb, 2, 'Good oral hygiene prevents infection; nutrition is maintained with liquid feeds.', 'PON 417 · Maxillofacial Surgery'),
(5, 8, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'PON 417 · Maxillofacial Surgery', 'Fracture of the zygoma may cause:', '["Loss of taste only on the front of the tongue", "A flat cheek, cheek numbness and double vision", "Painless haematuria from associated kidney injury", "Hearing loss only on the side of the injury"]'::jsonb, 1, 'The infraorbital nerve may be damaged, and the orbital floor may be involved, causing eye problems.', 'PON 417 · Maxillofacial Surgery'),
(5, 9, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'PON 417 · Maxillofacial Surgery', 'Noma (cancrum oris), seen in malnourished children in Nigeria, is:', '["Gangrene destroying the soft tissue and bone of the face", "A benign, slow-growing tumour of the upper jaw", "An allergic swelling of the lips after a new food", "A simple dental cavity in a malnourished child"]'::jsonb, 0, 'Early treatment with antibiotics and nutrition saves lives; survivors often need reconstructive surgery.', 'PON 417 · Maxillofacial Surgery'),
(5, 10, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'PON 417 · Maxillofacial Surgery', 'Ameloblastoma is:', '["A locally aggressive benign jaw tumour, usually in the mandible", "A highly malignant skin tumour that spreads early to the lungs", "A simple salivary gland cyst that resolves without treatment", "A dental abscess that drains through the skin of the cheek"]'::jsonb, 0, 'Treatment is resection with clear margins and reconstruction.', 'PON 417 · Maxillofacial Surgery'),
(5, 11, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'PON 417 · Maxillofacial Surgery', 'Burkitt''s lymphoma in African children typically presents as:', '["A fast-growing jaw or abdominal mass", "A slow-growing pigmented skin lesion", "A pathological fracture of the femur", "A painless cystic swelling in the neck"]'::jsonb, 0, 'It is associated with Epstein-Barr virus and malaria. It responds well to chemotherapy.', 'PON 417 · Maxillofacial Surgery'),
(5, 12, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'PON 417 · Maxillofacial Surgery', 'After parotidectomy, the nerve most at risk of injury is the:', '["Facial nerve", "Trigeminal nerve", "Hypoglossal nerve", "Vagus nerve"]'::jsonb, 0, 'The facial nerve passes through the parotid gland. Facial weakness should be assessed post-operatively.', 'PON 417 · Maxillofacial Surgery'),
(5, 13, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'PON 417 · Maxillofacial Surgery', 'A dental abscess spreading into the fascial spaces of the neck requires:', '["Oral painkillers only and review in the dental clinic next week", "Hot compresses to the face to bring the abscess to a point", "Urgent airway assessment, IV antibiotics and surgical drainage", "Waiting for the abscess to drain spontaneously into the mouth"]'::jsonb, 2, 'Deep neck infections can cause airway obstruction, mediastinitis and sepsis.', 'PON 417 · Maxillofacial Surgery'),
(5, 14, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'PON 417 · Maxillofacial Surgery', 'The tooth extraction socket that loses its clot and becomes very painful is called:', '["Wet socket with pus", "Dry socket (alveolar osteitis)", "Oral candidiasis (thrush)", "Dental caries of the root"]'::jsonb, 1, 'It is more common in smokers and lower molar extractions. Treatment is irrigation and dressing of the socket.', 'PON 417 · Maxillofacial Surgery'),
(5, 15, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'PON 417 · Maxillofacial Surgery', 'A patient with a fractured mandible may present with:', '["Malocclusion, painful jaw movement and a step in the teeth", "Painless loss of vision in the eye on the same side", "Hearing loss only, without any pain or swelling", "Clear nasal discharge only, worse on bending forward"]'::jsonb, 0, 'Fractures are often in two places because the mandible is a ring structure.', 'PON 417 · Maxillofacial Surgery'),
(5, 16, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'PON 417 · Maxillofacial Surgery', 'Facial lacerations are usually closed:', '["Only by secondary intention healing", "Within 24 hours with fine sutures", "After one week, once swelling settles", "With large, thick sutures for strength"]'::jsonb, 1, 'The face has a rich blood supply, so wounds heal well and can be closed later than other sites.', 'PON 417 · Maxillofacial Surgery'),
(5, 17, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'PON 417 · Maxillofacial Surgery', 'Orthognathic surgery corrects:', '["Conductive hearing loss", "Jaw deformities and malocclusion", "Spinal curvature deformities", "Cataracts and squint"]'::jsonb, 1, 'It is planned with orthodontists and may need jaw fixation post-operatively.', 'PON 417 · Maxillofacial Surgery'),
(5, 18, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'PON 417 · Maxillofacial Surgery', 'A tracheostomy is sometimes performed in major head and neck surgery mainly to:', '["Help the patient to eat soon after surgery", "Secure the airway when swelling is expected", "Improve the patient''s speech after surgery", "Prevent chest infection after surgery"]'::jsonb, 1, 'Tracheostomy care includes suction, humidification and keeping the spare tube and dilators at the bedside.', 'PON 417 · Maxillofacial Surgery'),
(5, 19, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'PON 417 · Maxillofacial Surgery', 'An oral cancer patient with poor nutrition before surgery should receive:', '["No food for several days before surgery to reduce aspiration", "Water only for one week to cleanse the mouth before surgery", "A course of antibiotics only, as nutrition is not affected", "Nutritional assessment and support, sometimes NG or PEG feeding"]'::jsonb, 3, 'Malnutrition delays healing and increases infection risk.', 'PON 417 · Maxillofacial Surgery'),
(5, 20, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'PON 417 · Maxillofacial Surgery', 'When positioning a patient for maxillofacial surgery, eyes should be:', '["Covered with heavy folded towels for protection", "Left open so that the pupils can be checked", "Supported by pressing on the padded head ring", "Taped and padded to prevent corneal abrasion"]'::jsonb, 3, 'Corneal abrasion is a common positioning injury under anaesthesia.', 'PON 417 · Maxillofacial Surgery'),
(5, 21, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'PON 417 · Ophthalmic Surgery', 'Cataract is defined as:', '["Inflammation of the conjunctiva", "Opacity of the lens of the eye", "Raised pressure inside the eye", "Detachment of the retina"]'::jsonb, 1, 'Cataract causes gradual painless loss of vision. Surgery replaces the lens with an intraocular lens implant.', 'PON 417 · Ophthalmic Surgery'),
(5, 22, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'PON 417 · Ophthalmic Surgery', 'After cataract surgery, the patient should avoid:', '["Rubbing the eye, bending and heavy lifting", "Walking around the house and ward", "Wearing the eye shield at night", "Using the prescribed eye drops"]'::jsonb, 0, 'These activities increase intraocular pressure and risk wound damage.', 'PON 417 · Ophthalmic Surgery'),
(5, 23, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'PON 417 · Ophthalmic Surgery', 'Acute angle-closure glaucoma presents with:', '["Painless, gradual loss of peripheral vision over many years", "Itchy, watery eyes with a sticky discharge in the morning", "Floaters and flashes without any pain or redness of the eye", "Sudden painful red eye, halos, vomiting, fixed mid-dilated pupil"]'::jsonb, 3, 'It is an emergency. Treatment includes pilocarpine, acetazolamide and laser iridotomy.', 'PON 417 · Ophthalmic Surgery'),
(5, 24, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'PON 417 · Ophthalmic Surgery', 'Which drug should be avoided in a patient with angle-closure glaucoma?', '["Oral acetazolamide", "Timolol eye drops", "Atropine (a mydriatic)", "Pilocarpine eye drops"]'::jsonb, 2, 'Dilating the pupil can close the drainage angle further.', 'PON 417 · Ophthalmic Surgery'),
(5, 25, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'PON 417 · Ophthalmic Surgery', 'Retinal detachment is described by patients as:', '["Flashes, floaters and a curtain over the vision", "Severe eye pain with nausea and vomiting", "An itchy red eye with crusting of the lids", "A watery discharge with gritty sensation"]'::jsonb, 0, 'It is an emergency; surgery may involve vitrectomy, scleral buckling or gas tamponade.', 'PON 417 · Ophthalmic Surgery'),
(5, 26, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'PON 417 · Ophthalmic Surgery', 'After vitreoretinal surgery with gas bubble injection, the patient must:', '["Lie flat on the back for the first week", "Fly home within the first week if needed", "Keep the prescribed head posture and avoid air travel", "Move freely without following any posture"]'::jsonb, 2, 'The gas bubble must press against the retinal break. Altitude expansion of gas can raise pressure dangerously.', 'PON 417 · Ophthalmic Surgery'),
(5, 27, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'PON 417 · Ophthalmic Surgery', 'A chemical splash to the eye should first be treated by:', '["Immediate copious irrigation with water or saline", "Using antibiotic ointment only, with no irrigation", "Rubbing the eye gently to remove the chemical", "Applying a firm eye pad and waiting for the doctor"]'::jsonb, 0, 'Alkali burns are especially dangerous. pH is checked after irrigation.', 'PON 417 · Ophthalmic Surgery'),
(5, 28, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'PON 417 · Ophthalmic Surgery', 'Penetrating eye injury with a foreign body still in place should be managed by:', '["Apply firm pressure to the eye to stop bleeding", "Irrigate forcefully to wash the object out", "Pull the object out gently, then pad the eye", "Leave the object in, apply a shield, refer urgently"]'::jsonb, 3, 'Pressure can extrude eye contents. The patient is kept nil by mouth for surgery.', 'PON 417 · Ophthalmic Surgery'),
(5, 29, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'PON 417 · Ophthalmic Surgery', 'When instilling eye drops, the nurse should:', '["Ask the patient to look down and drop into the upper lid", "Pull down the lower lid and drop into the fornix without touching", "Rest the dropper tip on the lashes to steady the bottle", "Drop the medicine directly onto the centre of the cornea"]'::jsonb, 1, 'Gentle punctal pressure reduces systemic absorption. Wait 5 minutes between different drops.', 'PON 417 · Ophthalmic Surgery'),
(5, 30, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'PON 417 · Ophthalmic Surgery', 'Trachoma, common in northern Nigeria, is caused by:', '["Staphylococcus aureus", "Onchocerca volvulus", "Chlamydia trachomatis", "Herpes simplex"]'::jsonb, 2, 'The SAFE strategy: Surgery for trichiasis, Antibiotics, Facial cleanliness and Environmental improvement.', 'PON 417 · Ophthalmic Surgery'),
(5, 31, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'PON 417 · Ophthalmic Surgery', 'Onchocerciasis (river blindness) is transmitted by:', '["Anopheles mosquito", "Common housefly", "Tsetse fly (Glossina)", "Blackfly (Simulium)"]'::jsonb, 3, 'Ivermectin mass treatment is used in Nigeria.', 'PON 417 · Ophthalmic Surgery'),
(5, 32, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'PON 417 · Ophthalmic Surgery', 'Endophthalmitis after cataract surgery presents with:', '["Mild watering only, which settles with drops", "Painless improvement in vision on the first day", "Increasing pain, redness, falling vision and hypopyon", "Itchy eyelids only, with no change in vision"]'::jsonb, 2, 'It is a sight-threatening emergency requiring intravitreal antibiotics.', 'PON 417 · Ophthalmic Surgery'),
(5, 33, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'PON 417 · Ophthalmic Surgery', 'Local anaesthesia for eye surgery commonly involves:', '["Spinal anaesthesia at the L3–L4 level", "Lumbar epidural with a catheter", "Brachial plexus block of the arm", "Peribulbar, sub-Tenon''s or topical block"]'::jsonb, 3, 'The patient must lie still with the face covered by drapes; oxygen and reassurance are provided.', 'PON 417 · Ophthalmic Surgery'),
(5, 34, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'PON 417 · Ophthalmic Surgery', 'The oculocardiac reflex during squint surgery causes:', '["Tachycardia from adrenaline release", "Hyperthermia from muscle rigidity", "Bradycardia from traction on eye muscles", "Severe hypertension from pain"]'::jsonb, 2, 'The surgeon stops traction; atropine may be needed.', 'PON 417 · Ophthalmic Surgery'),
(5, 35, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'PON 417 · Ophthalmic Surgery', 'Glaucoma is primarily damage to the:', '["Lens, which becomes cloudy and opaque", "Cornea, which becomes thin and scarred", "Optic nerve, usually with raised pressure", "Eyelid, which turns inwards on the eye"]'::jsonb, 2, 'Chronic open-angle glaucoma is painless and leads to peripheral vision loss.', 'PON 417 · Ophthalmic Surgery'),
(5, 36, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'PON 417 · Ophthalmic Surgery', 'Trabeculectomy is a surgical procedure for:', '["Squint, adjusting the eye muscles", "Cataract, replacing the cloudy lens", "Retinal detachment, using a gas bubble", "Glaucoma, creating a new drainage channel"]'::jsonb, 3, 'A bleb forms under the conjunctiva; it should be protected from trauma.', 'PON 417 · Ophthalmic Surgery'),
(5, 37, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'PON 417 · Ophthalmic Surgery', 'Normal intraocular pressure is approximately:', '["10-21 mmHg", "30-40 mmHg", "50-60 mmHg", "0-5 mmHg"]'::jsonb, 0, 'Raised pressure may damage the optic nerve. Tonometry measures it.', 'PON 417 · Ophthalmic Surgery'),
(5, 38, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'PON 417 · Ophthalmic Surgery', 'Before eye surgery, the operative eye is:', '["Marked and checked by the team to avoid wrong-site surgery", "Not checked, because the consent form states the correct eye", "Chosen in theatre by the surgeon without any prior marking", "Covered with tape only, so the scrub nurse knows which eye"]'::jsonb, 0, 'Site marking is part of the WHO surgical safety checklist.', 'PON 417 · Ophthalmic Surgery'),
(5, 39, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'PON 417 · Ophthalmic Surgery', 'Eye shields after eye surgery are worn mainly:', '["During the day only, when the patient is out", "Never, because shields cause infection", "For the first hour only, then thrown away", "At night to prevent rubbing or pressure"]'::jsonb, 3, 'Patients are advised to avoid sleeping on the operated side.', 'PON 417 · Ophthalmic Surgery'),
(5, 40, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'PON 417 · Ophthalmic Surgery', 'A corneal abrasion causes:', '["Pain, watering, photophobia and grittiness", "Painless sudden loss of vision", "Coloured halos around lights", "Floaters and flashes of light"]'::jsonb, 0, 'Fluorescein staining shows the defect. Treatment includes antibiotic ointment and analgesia.', 'PON 417 · Ophthalmic Surgery'),
(5, 41, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'PON 415 · Otorhinolaryngology (ENT)', 'Post-tonsillectomy, a child who swallows frequently while asleep may be:', '["Dehydrated only", "Comfortable and sleeping well", "Bleeding from the tonsil bed", "Hungry"]'::jsonb, 2, 'Frequent swallowing, rising pulse and pallor indicate haemorrhage. Primary haemorrhage occurs within 24 hours; secondary at 5-10 days from infection.', 'PON 415 · Otorhinolaryngology (ENT)'),
(5, 42, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'PON 415 · Otorhinolaryngology (ENT)', 'After tonsillectomy, the patient is positioned:', '["Sitting upright immediately on arrival", "Prone with the face down on a pillow", "Supine flat with the head extended", "On the side until fully awake"]'::jsonb, 3, 'This allows blood and secretions to drain from the mouth.', 'PON 415 · Otorhinolaryngology (ENT)'),
(5, 43, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'PON 415 · Otorhinolaryngology (ENT)', 'A quinsy is:', '["A benign nasal polyp", "A middle ear infection", "A peritonsillar abscess", "A maxillary sinus infection"]'::jsonb, 2, 'It causes trismus, deviation of the uvula and muffled voice. Treatment is aspiration or incision and drainage.', 'PON 415 · Otorhinolaryngology (ENT)'),
(5, 44, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'PON 415 · Otorhinolaryngology (ENT)', 'Epistaxis first aid involves:', '["Lie flat with the head tilted back for 10 minutes", "Pinch the bony bridge of the nose firmly", "Blow the nose hard to clear the clots", "Sit forward, pinch the soft nose for 10–15 minutes"]'::jsonb, 3, 'Leaning forward prevents swallowing blood. If bleeding continues, nasal packing or cautery may be needed.', 'PON 415 · Otorhinolaryngology (ENT)'),
(5, 45, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'PON 415 · Otorhinolaryngology (ENT)', 'Little''s area, the commonest site of nosebleeds, is located on the:', '["Posterior pharyngeal wall", "Middle turbinate", "Anterior nasal septum", "Maxillary sinus"]'::jsonb, 2, 'It contains Kiesselbach''s plexus. Posterior bleeds are more severe and seen in the elderly with hypertension.', 'PON 415 · Otorhinolaryngology (ENT)'),
(5, 46, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'PON 415 · Otorhinolaryngology (ENT)', 'After a stapedectomy, the patient should avoid:', '["Nose blowing, closed-mouth sneezing, flying and heavy lifting", "Walking around the ward or at home after the first day", "Taking the prescribed analgesia regularly for the first week", "Eating soft food and drinking fluids at normal temperature"]'::jsonb, 0, 'Pressure changes may displace the prosthesis. Vertigo and changes in hearing are reported.', 'PON 415 · Otorhinolaryngology (ENT)'),
(5, 47, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'PON 415 · Otorhinolaryngology (ENT)', 'Grommets (ventilation tubes) are inserted for:', '["Recurrent attacks of tonsillitis", "Persistent otitis media with effusion", "Nasal polyps blocking the nose", "Impacted ear wax in the outer canal"]'::jsonb, 1, 'They equalise pressure and drain fluid. Patients may be advised to keep water out of the ears.', 'PON 415 · Otorhinolaryngology (ENT)'),
(5, 48, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'PON 415 · Otorhinolaryngology (ENT)', 'Foreign body in the ear (e.g. live insect) is first managed by:', '["Instilling oil to kill the insect first", "Leaving it alone until it crawls out", "Syringing the ear with hot water", "Using a cotton bud to push it out"]'::jsonb, 0, 'Batteries in ears or nose need urgent removal because of chemical burns.', 'PON 415 · Otorhinolaryngology (ENT)'),
(5, 49, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'PON 415 · Otorhinolaryngology (ENT)', 'Tracheostomy tube changes after surgery should be done with:', '["Only an oxygen mask and a pulse oximeter at the bedside", "Tracheal dilators, a spare tube and suction at the bedside", "Only a 10 mL syringe for the cuff at the bedside", "No equipment at the bedside, as the tract is mature"]'::jsonb, 1, 'The first tube change is often done by the surgeon after 5-7 days when the tract has matured.', 'PON 415 · Otorhinolaryngology (ENT)'),
(5, 50, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'PON 415 · Otorhinolaryngology (ENT)', 'A patient with a tracheostomy who cannot speak should be given:', '["A call bell and a writing board or picture chart", "No communication tools, so that the patient rests", "A mirror only, so the patient can see the stoma", "Loud music to distract the patient from distress"]'::jsonb, 0, 'Communication helps reduce anxiety and allows patients to signal distress.', 'PON 415 · Otorhinolaryngology (ENT)'),
(5, 51, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'PON 415 · Otorhinolaryngology (ENT)', 'A displaced tracheostomy tube in a fresh tracheostomy is an emergency because:', '["It causes only mild discomfort to the patient", "It is harmless because the stoma stays open", "It improves breathing by reducing dead space", "The airway may be lost and the tract may close"]'::jsonb, 3, 'Call for help, give oxygen to face and stoma, and follow emergency tracheostomy algorithms.', 'PON 415 · Otorhinolaryngology (ENT)'),
(5, 52, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'PON 415 · Otorhinolaryngology (ENT)', 'Humidification is important for tracheostomy patients because:', '["The nose and upper airway that warm and moisten air are bypassed", "Humidification makes secretions thicker and so easier to suction out", "Humidified air increases the risk of chest infection in these patients", "It is not important, because the trachea moistens the air by itself"]'::jsonb, 0, 'Dry air thickens secretions and may block the tube.', 'PON 415 · Otorhinolaryngology (ENT)'),
(5, 53, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'PON 415 · Otorhinolaryngology (ENT)', 'Laryngectomy patients breathe through:', '["The nose, as before surgery", "A permanent stoma in the neck", "The mouth, through a voice tube", "A nasal cannula with oxygen"]'::jsonb, 1, 'There is no connection between the mouth and the trachea. Oxygen and resuscitation must be given via the stoma.', 'PON 415 · Otorhinolaryngology (ENT)'),
(5, 54, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'PON 415 · Otorhinolaryngology (ENT)', 'A foreign body in the airway of a choking child who cannot cough is managed with:', '["Back blows and chest or abdominal thrusts by age", "Giving the child water to wash the object down", "A blind finger sweep of the back of the throat", "Lying the child down to sleep and observing"]'::jsonb, 0, 'Infants receive back blows and chest thrusts; children receive back blows and abdominal thrusts.', 'PON 415 · Otorhinolaryngology (ENT)'),
(5, 55, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'PON 415 · Otorhinolaryngology (ENT)', 'Acute epiglottitis in a child presents with:', '["Expiratory wheeze only, with no fever", "Productive cough with green sputum", "Drooling, stridor, high fever, sitting forward", "Barking cough and a mild fever at night"]'::jsonb, 2, 'Do not examine the throat or upset the child; secure airway in theatre with ENT ready.', 'PON 415 · Otorhinolaryngology (ENT)'),
(5, 56, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'PON 415 · Otorhinolaryngology (ENT)', 'Functional endoscopic sinus surgery (FESS) is used to:', '["Treat chronic sinusitis and polyps", "Insert grommets into the eardrums", "Repair a perforated eardrum", "Remove the tonsils and adenoids"]'::jsonb, 0, 'Complications include bleeding, orbital injury and CSF leak.', 'PON 415 · Otorhinolaryngology (ENT)'),
(5, 57, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'PON 415 · Otorhinolaryngology (ENT)', 'After nasal surgery with packing, the patient may be advised to:', '["Lie flat to reduce swelling of the face and nose", "Breathe through the mouth, sit up, and not blow the nose", "Drink very hot drinks to soothe the dry throat", "Blow the nose firmly to clear blood from the packs"]'::jsonb, 1, 'Packs are usually removed after 24-48 hours.', 'PON 415 · Otorhinolaryngology (ENT)'),
(5, 58, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'PON 415 · Otorhinolaryngology (ENT)', 'Myringoplasty is:', '["Insertion of ventilation tubes", "Removal of the tonsils", "Repair of a perforated eardrum", "Removal of the stapes bone"]'::jsonb, 2, 'The graft is commonly taken from temporalis fascia.', 'PON 415 · Otorhinolaryngology (ENT)'),
(5, 59, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'PON 415 · Otorhinolaryngology (ENT)', 'Cholesteatoma is:', '["A chronic infection of the maxillary sinus", "Skin growth in the middle ear that erodes bone", "A fatty tumour under the skin of the ear lobe", "A benign tumour of the parotid salivary gland"]'::jsonb, 1, 'It can cause hearing loss, facial palsy and intracranial complications if untreated. Mastoidectomy is needed.', 'PON 415 · Otorhinolaryngology (ENT)'),
(5, 60, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'PON 415 · Otorhinolaryngology (ENT)', 'Before ENT surgery under general anaesthesia, the throat pack must be:', '["Left in place to absorb blood after surgery", "Not counted, because it is not a swab", "Documented and removed before extubation", "Removed by the patient once fully awake"]'::jsonb, 2, 'Retained throat packs can cause airway obstruction. They are included in the count.', 'PON 415 · Otorhinolaryngology (ENT)'),
(5, 61, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'Radiology & Radiation Safety', 'The main principle of radiation protection is ALARA, meaning:', '["All Levels Are Radiation Acceptable", "Absorb Large Amounts Regularly", "As Low As Reasonably Achievable", "Always Leave All Radiation Alone"]'::jsonb, 2, 'Time, distance and shielding reduce exposure.', 'Radiology & Radiation Safety'),
(5, 62, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'Radiology & Radiation Safety', 'In theatre, when the image intensifier (C-arm) is used, staff should:', '["Wear lead aprons and thyroid shields, and stand back", "Hold the patient''s limb steady within the beam", "Stand close to the patient without any protection", "Remove lead aprons so as to work faster and cooler"]'::jsonb, 0, 'Doubling distance reduces exposure to one quarter (inverse square law).', 'Radiology & Radiation Safety'),
(5, 63, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'Radiology & Radiation Safety', 'Before an X-ray in a woman of reproductive age, the nurse should:', '["Remove all clothing", "Check pregnancy status", "Ignore pregnancy status", "Give a sedative"]'::jsonb, 1, 'The ''28-day rule'' or pregnancy test protects a possible fetus from radiation.', 'Radiology & Radiation Safety'),
(5, 64, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'Radiology & Radiation Safety', 'Before a contrast CT, the nurse checks:', '["Hair length and any hair products used", "Shoe size and walking ability before CT", "Eye colour and any contact lenses worn", "Allergies, renal function and metformin use"]'::jsonb, 3, 'Iodinated contrast can cause allergic reactions and contrast-induced nephropathy.', 'Radiology & Radiation Safety'),
(5, 65, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'Radiology & Radiation Safety', 'MRI scanning is contraindicated in patients with:', '["Cotton clothing with no metal parts", "Some pacemakers, metal in the eye, some implants", "A plaster of Paris cast on the forearm", "Removable acrylic dentures in the mouth"]'::jsonb, 1, 'MRI uses a strong magnetic field. Metal objects become projectiles and implants may heat or malfunction.', 'Radiology & Radiation Safety'),
(5, 66, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'Radiology & Radiation Safety', 'Ultrasound imaging is preferred in pregnancy because it:', '["Uses radioactive isotopes with a short half-life", "Uses low-dose X-rays that cannot harm the fetus", "Uses sound waves, not ionising radiation", "Uses a strong magnetic field and radio waves"]'::jsonb, 2, 'Ultrasound is safe and widely available. It is used for FAST scans in trauma.', 'Radiology & Radiation Safety'),
(5, 67, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'Radiology & Radiation Safety', 'A dosimeter badge worn by theatre staff is used to:', '["Measure cumulative radiation dose", "Check the staff member''s heart rate", "Measure the staff''s body temperature", "Identify staff names at the door"]'::jsonb, 0, 'Badges are checked regularly to ensure exposure stays within limits.', 'Radiology & Radiation Safety'),
(5, 68, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'Radiology & Radiation Safety', 'Barium enema is a contrast study used to examine the:', '["Stomach only", "Large bowel", "Kidneys", "Lungs"]'::jsonb, 1, 'Bowel preparation is needed. Barium is avoided if perforation is suspected.', 'Radiology & Radiation Safety'),
(5, 69, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'Radiology & Radiation Safety', 'Intravenous urography (IVU) is used to visualise the:', '["Heart and great vessels", "Kidneys, ureters and bladder", "Liver and biliary tree", "Brain and spinal cord"]'::jsonb, 1, 'Contrast is injected and filtered by the kidneys.', 'Radiology & Radiation Safety'),
(5, 70, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'Radiology & Radiation Safety', 'In theatre, the radiographer''s role during cholangiography is to:', '["Count the swabs and instruments with the scrub nurse", "Give the anaesthetic and monitor the patient", "Operate imaging and advise on radiation safety", "Perform the surgical part of the procedure"]'::jsonb, 2, 'Clear communication between surgeon and radiographer reduces radiation exposure and delays.', 'Radiology & Radiation Safety'),
(5, 71, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'Radiology & Radiation Safety', 'A lead apron should be stored:', '["Piled on the floor of theatre", "Hung or laid flat, never folded", "Stored damp after cleaning", "Folded tightly in a drawer"]'::jsonb, 1, 'Folding causes cracks in the lead lining, reducing protection.', 'Radiology & Radiation Safety'),
(5, 72, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'Radiology & Radiation Safety', 'The FAST scan in trauma is used to detect:', '["Brain injury and skull fractures", "Free fluid in the abdomen or pericardium", "Soft tissue and skin infections", "Fractures of the pelvis and long bones"]'::jsonb, 1, 'It is rapid and done at the bedside.', 'Radiology & Radiation Safety'),
(5, 73, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'Radiology & Radiation Safety', 'A chest X-ray after central line insertion is done to:', '["Check the blood glucose after insertion", "Confirm tip position and exclude pneumothorax", "Measure the central venous pressure", "Detect any urinary tract infection"]'::jsonb, 1, 'The tip should be in the lower superior vena cava.', 'Radiology & Radiation Safety'),
(5, 74, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'Radiology & Radiation Safety', 'A patient allergic to iodinated contrast may need:', '["Steroid and antihistamine premedication, or other imaging", "No precautions at all, as reactions never happen twice", "A double dose of contrast to overcome the allergy", "Oral contrast only, which is always completely safe"]'::jsonb, 0, 'Resuscitation equipment must be available.', 'Radiology & Radiation Safety'),
(5, 75, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'Radiology & Radiation Safety', 'Radiation exposure risk to staff is lowest when:', '["Standing on the image intensifier (receptor) side", "Standing on the X-ray tube side of the C-arm", "Standing close to the beam to watch the screen", "Holding the patient''s limb in position during the shot"]'::jsonb, 0, 'Scatter is greatest on the tube side.', 'Radiology & Radiation Safety'),
(5, 76, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'GSO 410 · Occupational Health & Ergonomics', 'The main purpose of occupational health in the theatre is to:', '["Replace the infection prevention team", "Increase working hours and theatre productivity", "Reduce salaries and staff benefits", "Protect staff from work hazards and promote health"]'::jsonb, 3, 'This includes vaccination, injury prevention and support.', 'GSO 410 · Occupational Health & Ergonomics'),
(5, 77, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'GSO 410 · Occupational Health & Ergonomics', 'Needlestick injuries are best prevented by:', '["Recapping needles with two hands before disposal", "Filling sharps bins to the top before closing", "No recapping, and using sharps bins and safety devices", "Bending needles so that they cannot be reused"]'::jsonb, 2, 'Use a neutral zone for passing sharps in theatre.', 'GSO 410 · Occupational Health & Ergonomics'),
(5, 78, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'GSO 410 · Occupational Health & Ergonomics', 'Following a needlestick injury, the first action is to:', '["Suck the wound to remove any infected blood", "Scrub the skin with undiluted bleach for 5 minutes", "Ignore it if the patient looks healthy", "Encourage bleeding, wash with soap and water, report"]'::jsonb, 3, 'Post-exposure prophylaxis for HIV should start within hours, ideally within 72 hours at the latest.', 'GSO 410 · Occupational Health & Ergonomics'),
(5, 79, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'GSO 410 · Occupational Health & Ergonomics', 'Staff in theatre should be immunised against:', '["Rabies", "Typhoid fever", "Hepatitis B", "Malaria"]'::jsonb, 2, 'Hepatitis B vaccination and antibody response checks are standard for health workers.', 'GSO 410 · Occupational Health & Ergonomics'),
(5, 80, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'GSO 410 · Occupational Health & Ergonomics', 'Manual handling injuries are prevented by:', '["Twisting the trunk while lifting the patient", "Lifting heavy patients alone to save time", "Risk assessment, hoists, slide sheets and teamwork", "Bending the back with straight legs to lift"]'::jsonb, 2, 'Lifting with straight back and bent knees and avoiding twisting reduces injury.', 'GSO 410 · Occupational Health & Ergonomics'),
(5, 81, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'GSO 410 · Occupational Health & Ergonomics', 'Ergonomics in the operating theatre refers to:', '["Cleaning the theatre between surgical cases", "Administering drugs during anaesthesia", "Feeding patients after their operations", "Fitting work and equipment to staff to reduce strain"]'::jsonb, 3, 'Adjusting table height, monitor positions and using anti-fatigue mats help.', 'GSO 410 · Occupational Health & Ergonomics'),
(5, 82, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'GSO 410 · Occupational Health & Ergonomics', 'Latex allergy among theatre staff is managed by:', '["Taking antihistamines every day", "Using latex-free gloves and equipment", "Using powdered latex gloves instead", "Ignoring mild skin symptoms"]'::jsonb, 1, 'Latex allergy can cause contact dermatitis or anaphylaxis.', 'GSO 410 · Occupational Health & Ergonomics'),
(5, 83, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'GSO 410 · Occupational Health & Ergonomics', 'Exposure to anaesthetic gases is reduced by:', '["Scavenging and good theatre ventilation", "Using open face masks without seals", "Closing all theatre ventilation systems", "Avoiding maintenance of the machines"]'::jsonb, 0, 'Chronic exposure may cause headaches and reproductive risks.', 'GSO 410 · Occupational Health & Ergonomics'),
(5, 84, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'GSO 410 · Occupational Health & Ergonomics', 'Surgical smoke from diathermy should be:', '["Inhaled by staff, as it is harmless", "Blown away from the field with fans", "Removed with smoke evacuation", "Ignored, as masks filter all of it"]'::jsonb, 2, 'Smoke contains chemicals and possibly viruses.', 'GSO 410 · Occupational Health & Ergonomics'),
(5, 85, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'GSO 410 · Occupational Health & Ergonomics', 'Shift work and long hours in theatre can lead to:', '["Improved performance", "Fewer clinical mistakes", "Better quality sleep", "Fatigue, errors and burnout"]'::jsonb, 3, 'Adequate breaks and rotas reduce fatigue.', 'GSO 410 · Occupational Health & Ergonomics'),
(5, 86, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'GSO 410 · Occupational Health & Ergonomics', 'Hazardous substances in theatre (e.g. formaldehyde, glutaraldehyde) are controlled under:', '["No regulations, as they are hospital chemicals", "Patient consent before any chemical is used", "Risk assessment (COSHH), PPE and ventilation", "Each staff member''s own personal discretion"]'::jsonb, 2, 'Material safety data sheets give information on handling.', 'GSO 410 · Occupational Health & Ergonomics'),
(5, 87, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'GSO 410 · Occupational Health & Ergonomics', 'Standard precautions apply to:', '["Only patients known to be HIV-positive", "Only children and the elderly", "Only patients with a fever", "All patients, whatever the diagnosis"]'::jsonb, 3, 'These include hand hygiene, PPE, safe sharps handling and waste management.', 'GSO 410 · Occupational Health & Ergonomics'),
(5, 88, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'GSO 410 · Occupational Health & Ergonomics', 'Burnout in theatre nurses is characterised by:', '["Improved relationships with colleagues and patients", "High job satisfaction with few days off sick", "Increased energy, enthusiasm and motivation at work", "Exhaustion, depersonalisation and low sense of achievement"]'::jsonb, 3, 'Support, workload management and counselling help.', 'GSO 410 · Occupational Health & Ergonomics'),
(5, 89, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'GSO 410 · Occupational Health & Ergonomics', 'Workplace violence and aggression should be:', '["Accepted as part of the job in a busy hospital", "Reported and managed with policies and training", "Ignored, unless the nurse is physically injured", "Handled alone by the nurse without telling anyone"]'::jsonb, 1, 'Staff safety is a management responsibility.', 'GSO 410 · Occupational Health & Ergonomics'),
(5, 90, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'GSO 410 · Occupational Health & Ergonomics', 'Laser safety in theatre requires:', '["Open windows to let the laser beam escape safely from theatre", "Eye protection, warning signs and non-reflective instruments", "Shiny polished instruments to reflect the beam away from staff", "No special protection, because lasers are low-energy devices"]'::jsonb, 1, 'A laser safety officer oversees safe practice.', 'GSO 410 · Occupational Health & Ergonomics'),
(5, 91, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'Nursing Theories', 'Orem''s self-care deficit theory is most useful in perioperative nursing because:', '["It ignores the needs of the patient in favour of tasks", "It focuses only on the physical environment of the theatre", "It is mainly concerned with financial management of care", "It guides care when patients cannot meet their own self-care needs"]'::jsonb, 3, 'Nursing systems are wholly compensatory (e.g. under anaesthesia), partly compensatory, or supportive-educative.', 'Nursing Theories'),
(5, 92, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'Nursing Theories', 'A patient under general anaesthesia requires which of Orem''s nursing systems?', '["Supportive-educative", "No nursing system", "Partly compensatory", "Wholly compensatory"]'::jsonb, 3, 'The patient cannot perform any self-care, so the nurse acts fully for them.', 'Nursing Theories'),
(5, 93, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'Nursing Theories', 'Florence Nightingale''s theory emphasises:', '["Financial planning and hospital budgets", "Environment: air, cleanliness, light, quiet and diet", "Psychoanalysis and unconscious conflict", "Surgical techniques and operative skills"]'::jsonb, 1, 'Her principles underpin infection control and theatre environmental standards.', 'Nursing Theories'),
(5, 94, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'Nursing Theories', 'Roy''s adaptation model views the patient as:', '["A passive recipient of all care", "A machine to be repaired by experts", "A financial unit in the hospital", "An adaptive system responding to stimuli"]'::jsonb, 3, 'The four adaptive modes are physiological, self-concept, role function and interdependence.', 'Nursing Theories'),
(5, 95, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'Nursing Theories', 'Peplau''s interpersonal relations theory focuses on:', '["The nurse–patient relationship and its phases", "Surgical skills and theatre techniques", "Drug calculations and administration", "Infection control and sterilisation"]'::jsonb, 0, 'It is useful in preoperative assessment and reducing anxiety.', 'Nursing Theories'),
(5, 96, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'Nursing Theories', 'Maslow''s hierarchy of needs places which at the base?', '["Love and belonging", "Esteem", "Physiological needs", "Self-actualisation"]'::jsonb, 2, 'In perioperative care, airway, breathing and circulation take priority.', 'Nursing Theories'),
(5, 97, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'Nursing Theories', 'Henderson''s definition of nursing states the nurse helps the individual to:', '["Perform minor surgery when no doctor is available on duty", "Do what they would do unaided if they had the strength, will or knowledge", "Pay the hospital bills and arrange health insurance for the family", "Choose the best surgeon and the hospital for the operation"]'::jsonb, 1, 'She described 14 basic needs.', 'Nursing Theories'),
(5, 98, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'Nursing Theories', 'Benner''s ''From Novice to Expert'' model describes:', '["Stages of wound healing", "Phases of general anaesthesia", "Stages of a surgical operation", "Stages of clinical competence"]'::jsonb, 3, 'It is used for training and mentoring of theatre nurses.', 'Nursing Theories'),
(5, 99, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'Nursing Theories', 'Leininger''s transcultural nursing theory is relevant in theatre because:', '["It focuses only on the cultural needs of surgeons and doctors", "It is about the equipment and technology used in theatre", "Care must respect cultural beliefs, e.g. about blood and modesty", "Culture does not affect patient care in the operating theatre"]'::jsonb, 2, 'Culturally congruent care improves trust and compliance.', 'Nursing Theories'),
(5, 100, 'Perioperative Mock — Day 2 Afternoon (Nov 2026)', 'Nursing Theories', 'Watson''s theory of human caring emphasises:', '["Technical skills alone, done quickly", "Speed and efficiency of surgery", "Cost reduction in nursing services", "Caring relationships and holistic care"]'::jsonb, 3, 'It reminds nurses to maintain dignity and compassion, even for unconscious patients.', 'Nursing Theories'),
(6, 1, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'GST 403 · Research & Statistics', 'A study comparing infection rates in patients who received chlorhexidine versus povidone-iodine skin prep, with random allocation, is a:', '["Randomised controlled trial", "Case-control study", "Cross-sectional survey", "Retrospective case series"]'::jsonb, 0, 'Random allocation balances known and unknown confounders, making RCTs the strongest single design for testing interventions.', 'GST 403 · Research & Statistics'),
(6, 2, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'GST 403 · Research & Statistics', 'The hypothesis that states there is no difference between groups is the:', '["Conceptual framework", "Null hypothesis", "Alternative hypothesis", "Research question"]'::jsonb, 1, 'Statistical tests assess evidence against the null hypothesis. A p-value below 0.05 is commonly taken as significant.', 'GST 403 · Research & Statistics'),
(6, 3, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'GST 403 · Research & Statistics', 'A p-value of 0.03 means:', '["If there were no real difference, a result this extreme would occur about 3% of the time", "There is a 3% chance that the treatment works and a 97% chance that it does not work", "97% of the patients who received the treatment improved compared with the controls", "The result is clinically important and should change practice in every hospital"]'::jsonb, 0, 'Statistical significance does not equal clinical importance; effect size and confidence intervals matter.', 'GST 403 · Research & Statistics'),
(6, 4, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'GST 403 · Research & Statistics', 'The mean, median and mode are measures of:', '["Central tendency", "Validity", "Dispersion", "Correlation"]'::jsonb, 0, 'Range, variance and standard deviation are measures of dispersion.', 'GST 403 · Research & Statistics'),
(6, 5, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'GST 403 · Research & Statistics', 'For skewed data such as length of hospital stay, the best measure of central tendency is the:', '["Mode", "Mean", "Range", "Median"]'::jsonb, 3, 'Extreme values pull the mean; the median is unaffected.', 'GST 403 · Research & Statistics'),
(6, 6, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'GST 403 · Research & Statistics', 'Reliability of a research instrument refers to its:', '["Cost", "Ability to measure what it is meant to measure", "Length", "Consistency in producing the same results"]'::jsonb, 3, 'Validity is whether it measures what it intends to measure. A tool can be reliable without being valid.', 'GST 403 · Research & Statistics'),
(6, 7, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'GST 403 · Research & Statistics', 'Informed consent in research requires:', '["Participation of all patients on the ward, without exception", "Disclosure, understanding, voluntariness and freedom to withdraw", "Approval by the patient''s family only, without the patient", "Payment to all participants so that they agree to take part"]'::jsonb, 1, 'Ethics committee approval is also required before data collection.', 'GST 403 · Research & Statistics'),
(6, 8, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'GST 403 · Research & Statistics', 'A sample selected so that every member of the population has an equal chance of selection is a:', '["Simple random sample", "Convenience sample", "Purposive sample", "Snowball sample"]'::jsonb, 0, 'Random samples allow generalisation; convenience samples are easier but prone to bias.', 'GST 403 · Research & Statistics'),
(6, 9, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'GST 403 · Research & Statistics', 'Qualitative research mainly aims to:', '["Test hypotheses statistically using large samples", "Measure numerical relationships between variables", "Explore experiences, meanings and perceptions in depth", "Calculate incidence and prevalence rates of disease"]'::jsonb, 2, 'Methods include interviews, focus groups and observation; data are analysed by themes.', 'GST 403 · Research & Statistics'),
(6, 10, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'GST 403 · Research & Statistics', 'The section of a research report that summarises previous studies is the:', '["Methodology", "Results section", "Literature review", "Abstract only"]'::jsonb, 2, 'It identifies gaps in knowledge and justifies the study.', 'GST 403 · Research & Statistics'),
(6, 11, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'GST 403 · Research & Statistics', 'The chi-square test is used to compare:', '["Correlation of continuous variables", "Means of two independent groups", "Categorical (nominal) data between groups", "Survival times between two groups"]'::jsonb, 2, 'The t-test compares means; Pearson''s correlation measures linear relationships.', 'GST 403 · Research & Statistics'),
(6, 12, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'GST 403 · Research & Statistics', 'Evidence-based practice combines:', '["Research evidence only, without the views of patients", "Research evidence, clinical expertise and patient preferences", "The surgeon''s opinion and the hospital''s usual practice", "Tradition and the routines that have always been used"]'::jsonb, 1, 'It improves patient outcomes and reduces unnecessary variation.', 'GST 403 · Research & Statistics'),
(6, 13, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'GST 403 · Research & Statistics', 'In the hierarchy of evidence, the highest level is usually:', '["Case reports and case series of rare events", "Systematic reviews and meta-analyses of RCTs", "Expert opinion from a professional committee", "Prospective cohort studies of large groups"]'::jsonb, 1, 'Expert opinion is the lowest level.', 'GST 403 · Research & Statistics'),
(6, 14, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'GST 403 · Research & Statistics', 'A confounding variable is one that:', '["Is linked to both exposure and outcome, distorting the relationship", "Is the outcome variable being measured at the end of the study", "Is always measured directly and so never biases the results", "Has no relation to the exposure or the outcome in the study"]'::jsonb, 0, 'Randomisation, matching and statistical adjustment control confounders.', 'GST 403 · Research & Statistics'),
(6, 15, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'GST 403 · Research & Statistics', 'Plagiarism in research means:', '["Paraphrasing another author and giving the reference", "Using another person''s work or ideas without credit", "Citing all the sources correctly in the reference list", "Doing original research and publishing the findings"]'::jsonb, 1, 'It is a form of research misconduct.', 'GST 403 · Research & Statistics'),
(6, 16, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'Nursing Process', 'The correct order of the nursing process is:', '["Diagnosis, planning, assessment, evaluation, implementation", "Assessment, diagnosis, planning, implementation, evaluation", "Assessment, planning, diagnosis, evaluation, implementation", "Planning, assessment, implementation, diagnosis, evaluation"]'::jsonb, 1, 'ADPIE is cyclical: evaluation leads back to reassessment.', 'Nursing Process'),
(6, 17, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'Nursing Process', 'Which is a correctly written nursing diagnosis?', '["Needs IV antibiotics and analgesia every 8 hours", "Risk for infection related to surgical incision", "Patient is difficult and refuses to cooperate", "Acute appendicitis requiring appendicectomy"]'::jsonb, 1, 'A nursing diagnosis describes the patient''s response to health problems that nurses can treat independently.', 'Nursing Process'),
(6, 18, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'Nursing Process', 'A goal statement for a post-operative patient should be:', '["Written by the patient''s family without the nurse", "Vague and general, so that it can fit any patient", "Set very high, even if it cannot be achieved", "SMART: specific, measurable, achievable, realistic, timed"]'::jsonb, 3, 'Example: ''Patient will report pain of 3/10 or less within 1 hour of analgesia''.', 'Nursing Process'),
(6, 19, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'Nursing Process', 'Subjective data include:', '["The patient''s own description of pain or anxiety", "Blood pressure and pulse readings on the chart", "Wound measurements taken with a paper ruler", "Laboratory results such as haemoglobin level"]'::jsonb, 0, 'Objective data are observed or measured by the nurse.', 'Nursing Process'),
(6, 20, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'Nursing Process', 'Preoperative assessment by the perioperative nurse includes:', '["Only the information already written in the surgeon''s notes for the operation", "Only the patient''s financial status and the method of paying the bill", "History, allergies, past anaesthetics, drugs, and physical and psychological state", "Only the patient''s name, hospital number and the planned operation"]'::jsonb, 2, 'It identifies risks and allows individual planning.', 'Nursing Process'),
(6, 21, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'Nursing Process', 'Evaluation in the nursing process means:', '["Judging whether the patient''s goals were met", "Writing the nursing diagnosis statement", "Carrying out the planned nursing care", "Collecting the initial data on admission"]'::jsonb, 0, 'Plans are revised if goals are not met.', 'Nursing Process'),
(6, 22, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'Nursing Process', 'Intra-operative nursing diagnosis ''Risk for perioperative positioning injury'' requires interventions such as:', '["Leaving the patient''s limbs unsupported on the table", "Restraining the patient tightly with straps over joints", "Padding bony prominences and keeping body alignment", "Letting skin rest directly on metal parts of the table"]'::jsonb, 2, 'Nerve and pressure injuries are prevented by careful positioning.', 'Nursing Process'),
(6, 23, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'Nursing Process', 'Implementation involves:', '["Collecting data during assessment", "Writing the nursing care plan", "Judging whether outcomes were met", "Carrying out the planned interventions"]'::jsonb, 3, 'Documentation is part of implementation.', 'Nursing Process'),
(6, 24, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'Nursing Process', 'A collaborative problem is one that:', '["Is managed by nurses alone without any doctor", "Needs nursing and medical care, e.g. haemorrhage", "Is the responsibility of the patient''s family", "Needs no intervention because it will resolve"]'::jsonb, 1, 'Nurses monitor and detect complications and implement medical orders.', 'Nursing Process'),
(6, 25, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'Nursing Process', 'Documentation in the perioperative care plan is important because:', '["It is only needed for the yearly audit report", "It only helps the surgeons write their notes", "It is legal evidence and ensures continuity of care", "It is optional when the theatre is very busy"]'::jsonb, 2, 'Undocumented care is legally considered not done.', 'Nursing Process'),
(6, 26, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'Nursing Process', 'The nursing diagnosis ''Acute pain related to surgical incision'' is an example of:', '["A medical diagnosis", "A wellness nursing diagnosis", "A risk nursing diagnosis", "An actual nursing diagnosis"]'::jsonb, 3, 'Risk diagnoses describe potential problems, e.g. ''Risk for infection''.', 'Nursing Process'),
(6, 27, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'Nursing Process', 'The primary purpose of the nursing care plan is to:', '["Replace the doctor''s management plan", "Provide individualised, coordinated care", "Increase the hospital''s income from care", "Satisfy the accreditation inspectors only"]'::jsonb, 1, 'Plans are revised as the patient''s condition changes.', 'Nursing Process'),
(6, 28, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'Nursing Process', 'Post-operative assessment priority on arrival to the ward is:', '["The patient''s educational level and occupation", "The patient''s diet history and food preferences", "Airway, breathing, circulation and consciousness", "The patient''s social and family history"]'::jsonb, 2, 'Then pain, wound, drains, fluid balance and comfort are assessed.', 'Nursing Process'),
(6, 29, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'Nursing Process', 'Patient education before surgery should include:', '["Financial planning for the cost of the hospital stay", "Deep breathing, coughing, early mobilisation and pain control", "Nothing at all, because patients forget what they are told", "Only the details of the surgical technique to be used"]'::jsonb, 1, 'Preoperative education reduces anxiety and complications.', 'Nursing Process'),
(6, 30, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'Nursing Process', 'The nursing diagnosis ''Anxiety related to unknown surgical outcome'' is best managed by:', '["Telling the patient firmly that there is nothing to fear", "Ignoring the patient so that they calm down alone", "Giving sedatives only, without any explanation", "Giving information, answering questions and reassuring"]'::jsonb, 3, 'Explaining what will happen reduces anxiety.', 'Nursing Process'),
(6, 31, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'Management', 'Theatre lists are scheduled to:', '["Use resources well and prioritise urgent cases", "Leave theatres idle for unexpected visitors", "Suit the preferences of one senior surgeon", "Avoid accepting any emergency cases at all"]'::jsonb, 0, 'Good scheduling reduces cancellations and overtime.', 'Management'),
(6, 32, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'Management', 'The leadership style most suitable in an emergency in theatre is:', '["Autocratic (directive)", "Laissez-faire", "Democratic with long discussion", "Absent leadership"]'::jsonb, 0, 'In emergencies quick decisions are needed; democratic styles suit routine planning.', 'Management'),
(6, 33, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'Management', 'Delegation means:', '["Avoiding work by passing every task to junior staff", "Doing every task yourself so that nothing goes wrong", "Giving away all responsibility for the task and its outcome", "Assigning a task to a competent person while staying accountable"]'::jsonb, 3, 'The five rights of delegation: right task, circumstances, person, direction and supervision.', 'Management'),
(6, 34, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'Management', 'Incident reporting is important because it:', '["Identifies risks and helps prevent recurrence", "Increases errors by distracting the staff", "Is a waste of time that delays patient care", "Is used mainly to identify and punish staff"]'::jsonb, 0, 'A no-blame culture encourages reporting.', 'Management'),
(6, 35, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'Management', 'The WHO surgical safety checklist has three phases:', '["Sign in, time out and sign out", "Before, during and after anaesthesia only", "Morning, afternoon and night", "Admission, surgery and discharge"]'::jsonb, 0, 'It reduces complications and mortality.', 'Management'),
(6, 36, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'Management', 'SWOT analysis stands for:', '["Strengths, Weaknesses, Opportunities and Threats", "Staff, Work, Organisation and Time", "Surgery, Wards, Outpatients and Theatre", "Safety, Wellbeing, Operations and Training"]'::jsonb, 0, 'It is used in strategic planning.', 'Management'),
(6, 37, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'Management', 'Clinical audit involves:', '["Counting the drugs in the theatre cupboard only", "Checking staff salaries and overtime payments", "Comparing practice with set standards and improving it", "Disciplining staff who have made mistakes"]'::jsonb, 2, 'The audit cycle is completed by re-auditing after changes.', 'Management'),
(6, 38, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'Management', 'Conflict between team members in theatre is best resolved by:', '["Open communication and joint problem solving", "Reporting the conflict to the media", "Shouting until one person gives in", "Avoiding the issue and hoping it will pass"]'::jsonb, 0, 'Collaboration produces win-win solutions.', 'Management'),
(6, 39, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'Management', 'The budget for theatre supplies is best controlled by:', '["Ordering items without checking current stock", "Stock control, reducing waste and monitoring usage", "Hiding stock so other units cannot use it", "Ignoring expiry dates when using supplies"]'::jsonb, 1, 'Expired stock wastes money; first in, first out rotation is used.', 'Management'),
(6, 40, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'Management', 'Staff orientation for new theatre nurses aims to:', '["Make them work alone from the first day to build confidence", "Familiarise them with policies, equipment and procedures", "Replace all formal training and competency assessment", "Reduce staff numbers by testing who can cope best"]'::jsonb, 1, 'Preceptorship supports safe practice.', 'Management'),
(6, 41, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'Management', 'Span of control refers to:', '["The number of operating theatres in the unit", "The number of staff a manager directly supervises", "The total number of working hours in a week", "The total size of the hospital and its departments"]'::jsonb, 1, 'A wide span may reduce supervision quality.', 'Management'),
(6, 42, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'Management', 'Quality assurance in theatre aims to:', '["Increase the costs of care", "Reduce the number of staff", "Ensure care meets set standards", "Avoid external reviews"]'::jsonb, 2, 'Indicators include infection rates, cancellations and retained items.', 'Management'),
(6, 43, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'Management', 'Management by objectives involves:', '["Managing the unit without any written goals at all", "Punishing staff who fail to meet the manager''s goals", "Setting goals for staff without asking for their input", "Setting agreed goals with staff and measuring results"]'::jsonb, 3, 'It increases motivation and clarity.', 'Management'),
(6, 44, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'Management', 'Duty rosters should be planned to:', '["Favour certain staff with the best shifts", "Ignore all leave requests from the staff", "Ensure safe staffing and skill mix with staff welfare", "Leave theatres understaffed to save money"]'::jsonb, 2, 'Fair rosters reduce absenteeism.', 'Management'),
(6, 45, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'Management', 'The theatre manager''s role in infection control includes:', '["Leaving infection control entirely to the surgeons", "Ignoring policies when the theatre list is very busy", "Enforcing policies, ensuring training, checking compliance", "Only cleaning the theatre at the end of each day"]'::jsonb, 2, 'Leadership is critical for a culture of safety.', 'Management'),
(6, 46, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'GSE 420 · Ethico-legal Aspects', 'Informed consent for surgery must be obtained by:', '["The surgeon doing the procedure, or a competent delegate", "The patient''s relative, if the patient is anxious", "The theatre porter, when collecting the patient", "The scrub nurse, after the patient arrives in theatre"]'::jsonb, 0, 'The nurse may witness the signature and should report if the patient seems uninformed.', 'GSE 420 · Ethico-legal Aspects'),
(6, 47, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'GSE 420 · Ethico-legal Aspects', 'A patient refuses blood transfusion on religious grounds. The nurse should:', '["Respect the competent adult''s decision and document it", "Ignore the refusal because life comes first", "Force the patient to accept the transfusion", "Give the blood secretly while the patient is asleep"]'::jsonb, 0, 'Autonomy is respected; alternatives such as cell salvage may be discussed.', 'GSE 420 · Ethico-legal Aspects'),
(6, 48, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'GSE 420 · Ethico-legal Aspects', 'Negligence requires proof of:', '["An error alone, even with no harm", "Harm alone, whatever the cause", "Duty, breach, causation and harm", "A complaint alone from the family"]'::jsonb, 2, 'Retained swabs are classic examples of negligence.', 'GSE 420 · Ethico-legal Aspects'),
(6, 49, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'GSE 420 · Ethico-legal Aspects', 'Confidentiality may be breached when:', '["A relative or friend asks casually about the patient", "A journalist asks for details of a famous patient", "Required by law or to protect others from serious harm", "Never, under any circumstances whatsoever"]'::jsonb, 2, 'Only necessary information is disclosed.', 'GSE 420 · Ethico-legal Aspects'),
(6, 50, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'GSE 420 · Ethico-legal Aspects', 'Beneficence means:', '["Treating patients fairly", "Doing good for the patient", "Telling the patient the truth", "Avoiding harm to the patient"]'::jsonb, 1, 'Non-maleficence means avoiding harm; justice is fairness.', 'GSE 420 · Ethico-legal Aspects'),
(6, 51, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'GSE 420 · Ethico-legal Aspects', 'The four principles of bioethics are:', '["Honesty, kindness, respect and duty", "Safety, quality, efficiency and equity", "Confidentiality, consent, care and cost", "Autonomy, beneficence, non-maleficence, justice"]'::jsonb, 3, 'These guide ethical decisions in perioperative care.', 'GSE 420 · Ethico-legal Aspects'),
(6, 52, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'GSE 420 · Ethico-legal Aspects', 'Assault and battery in nursing refers to:', '["Giving a prescribed drug with the patient''s consent", "Documenting the care given in the nursing notes", "Recording observations accurately on the chart", "Touching or treating a patient without valid consent"]'::jsonb, 3, 'Valid consent must be voluntary and informed by a competent person.', 'GSE 420 · Ethico-legal Aspects'),
(6, 53, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'GSE 420 · Ethico-legal Aspects', 'For an unconscious patient needing emergency life-saving surgery with no relatives, surgery may proceed under:', '["No surgery until a relative is found", "Waiting for the patient to wake up", "Necessity, in the patient''s best interests", "Consent signed by the theatre porter"]'::jsonb, 2, 'Documentation must explain the emergency.', 'GSE 420 · Ethico-legal Aspects'),
(6, 54, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'GSE 420 · Ethico-legal Aspects', 'The Nursing and Midwifery Council of Nigeria (NMCN) regulates:', '["Hospital finances and staff salaries", "Medical doctors and their training", "Drug manufacturing and importation", "Nursing education and practice in Nigeria"]'::jsonb, 3, 'It sets standards, registers nurses and handles professional misconduct.', 'GSE 420 · Ethico-legal Aspects'),
(6, 55, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'GSE 420 · Ethico-legal Aspects', 'A nurse who makes a drug error should:', '["Hide the error to avoid trouble with the manager", "Blame the pharmacist or the prescribing doctor", "Report at once, protect the patient and document it", "Wait to see whether the patient complains first"]'::jsonb, 2, 'Honesty is a professional and ethical duty.', 'GSE 420 · Ethico-legal Aspects'),
(6, 56, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'GSE 420 · Ethico-legal Aspects', 'Vicarious liability means:', '["A nurse is responsible for every act of the doctor", "Patients are responsible for the acts of their nurses", "No one is responsible when an employee makes an error", "An employer is responsible for employees'' acts at work"]'::jsonb, 3, 'Nurses remain personally accountable for their practice.', 'GSE 420 · Ethico-legal Aspects'),
(6, 57, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'GSE 420 · Ethico-legal Aspects', 'Advance directives are:', '["Doctor''s orders written in the treatment chart", "A competent person''s written wishes about future care", "Hospital policies about end-of-life care", "Insurance documents about payment for care"]'::jsonb, 1, 'They must be respected when valid and applicable.', 'GSE 420 · Ethico-legal Aspects'),
(6, 58, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'GSE 420 · Ethico-legal Aspects', 'Whistleblowing is:', '["Leaking patient data to the press", "Raising concerns about unsafe or illegal practice", "Gossiping about colleagues with other staff", "Making personal complaints about workload"]'::jsonb, 1, 'Nurses have a duty to raise concerns to protect patients.', 'GSE 420 · Ethico-legal Aspects'),
(6, 59, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'GSE 420 · Ethico-legal Aspects', 'A minor''s consent for surgery in Nigeria is usually given by:', '["The child alone", "Parent or legal guardian", "The ward nurse", "Any adult relative"]'::jsonb, 1, 'Emergency exceptions apply when delay would cause serious harm.', 'GSE 420 · Ethico-legal Aspects'),
(6, 60, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'GSE 420 · Ethico-legal Aspects', 'A retained surgical instrument is legally:', '["A breach of duty that can lead to a negligence claim", "A minor issue that needs no report or follow-up", "Acceptable if the operation was very difficult", "The patient''s fault for moving during surgery"]'::jsonb, 0, 'Counting procedures prevent retained items; discrepancies must be resolved before closure.', 'GSE 420 · Ethico-legal Aspects'),
(6, 61, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'GST 408 · Entrepreneurship', 'Entrepreneurship in nursing refers to:', '["Avoiding innovation and keeping to routine practice", "Providing only bedside care, without any business role", "Working only in government hospitals on a fixed salary", "Nurses creating and running services that meet health needs"]'::jsonb, 3, 'Examples include home care agencies, health consultancy and training centres.', 'GST 408 · Entrepreneurship'),
(6, 62, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'GST 408 · Entrepreneurship', 'A business plan should include:', '["The hospital''s rules and its staff disciplinary code", "Executive summary, market analysis, finances and marketing", "Personal diaries and family photographs of the owner", "Only the owner''s name and the business address"]'::jsonb, 1, 'It guides operations and helps secure funding.', 'GST 408 · Entrepreneurship'),
(6, 63, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'GST 408 · Entrepreneurship', 'Break-even point is when:', '["All costs fall to zero", "Revenue falls to zero", "Total revenue equals total costs", "Profit is at its maximum"]'::jsonb, 2, 'Beyond it, the business makes profit.', 'GST 408 · Entrepreneurship'),
(6, 64, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'GST 408 · Entrepreneurship', 'Fixed costs are costs that:', '["Are always zero for a small business", "Are optional and can be stopped at will", "Do not change with output, such as rent", "Change directly with the level of output"]'::jsonb, 2, 'Variable costs, e.g. consumables, change with output.', 'GST 408 · Entrepreneurship'),
(6, 65, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'GST 408 · Entrepreneurship', 'A sole proprietorship means:', '["A partnership of two or more people", "A company owned by many shareholders", "A business run by a government agency", "A business owned and run by one person"]'::jsonb, 3, 'The owner has unlimited liability.', 'GST 408 · Entrepreneurship'),
(6, 66, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'GST 408 · Entrepreneurship', 'The Corporate Affairs Commission (CAC) in Nigeria:', '["Regulates drugs and food", "Manages public hospitals", "Registers businesses and companies", "Licenses nurses and midwives"]'::jsonb, 2, 'Registration gives legal recognition.', 'GST 408 · Entrepreneurship'),
(6, 67, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'GST 408 · Entrepreneurship', 'Market research helps the nurse entrepreneur to:', '["Ignore what competitors are offering", "Understand customers'' needs and competitors", "Increase costs without any benefit", "Avoid contact with possible customers"]'::jsonb, 1, 'It informs pricing and services.', 'GST 408 · Entrepreneurship'),
(6, 68, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'GST 408 · Entrepreneurship', 'Innovation in perioperative nursing could include:', '["Avoiding any change to theatre practices", "Refusing to use any new technology in theatre", "A better system for tracking theatre instruments", "Doing every task the same way as in the past"]'::jsonb, 2, 'Innovation improves quality and efficiency.', 'GST 408 · Entrepreneurship'),
(6, 69, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'GST 408 · Entrepreneurship', 'Social entrepreneurship mainly aims to:', '["Avoid working in poor or rural communities", "Solve social problems while sustaining the business", "Rely only on donations, with no business income", "Maximise profit only, whatever the social impact"]'::jsonb, 1, 'Examples include affordable maternal care services.', 'GST 408 · Entrepreneurship'),
(6, 70, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'GST 408 · Entrepreneurship', 'Capital refers to:', '["Money and assets used to run a business", "Only the salaries paid to the staff", "Only the profit made at the end of the year", "Taxes paid to the government each year"]'::jsonb, 0, 'Sources include savings, loans and grants.', 'GST 408 · Entrepreneurship'),
(6, 71, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'GST 405 · Computer Studies', 'Electronic health records help perioperative nurses by:', '["Making information hard for staff to access", "Removing the need for nurses to document care", "Increasing handwriting errors in drug charts", "Giving accessible, legible, up-to-date patient information"]'::jsonb, 3, 'They support continuity and data analysis.', 'GST 405 · Computer Studies'),
(6, 72, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'GST 405 · Computer Studies', 'A strong password should contain:', '["Your date of birth, written without any spaces", "Only the numbers 1234, used for every account", "A mix of upper and lower case, numbers and symbols", "Only your first name, so it is easy to remember"]'::jsonb, 2, 'Passwords should not be shared.', 'GST 405 · Computer Studies'),
(6, 73, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'GST 405 · Computer Studies', 'Sharing patient photos on social media without consent is:', '["Encouraged to raise awareness of disease", "Acceptable if the face is partly hidden", "A breach of confidentiality and misconduct", "Acceptable if it is used for teaching"]'::jsonb, 2, 'Professional bodies discipline breaches.', 'GST 405 · Computer Studies'),
(6, 74, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'GST 405 · Computer Studies', 'The central processing unit (CPU) of a computer is the:', '["Keyboard used to type in data", "Printer used to produce paper copies", "Display screen showing the output", "Part that carries out instructions"]'::jsonb, 3, 'Memory stores data; input/output devices interact with users.', 'GST 405 · Computer Studies'),
(6, 75, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'GST 405 · Computer Studies', 'A spreadsheet program like Microsoft Excel is best for:', '["Writing letters and long reports", "Drawing images and diagrams only", "Organising and calculating numbers", "Browsing websites on the internet"]'::jsonb, 2, 'It is used for audits and stock records.', 'GST 405 · Computer Studies'),
(6, 76, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'GST 405 · Computer Studies', 'Computer viruses are best prevented by:', '["Sharing passwords with colleagues on the ward", "Disabling the firewall and security settings", "Antivirus, updates and avoiding suspicious links", "Opening every email attachment to check it"]'::jsonb, 2, 'Phishing emails are a common source.', 'GST 405 · Computer Studies'),
(6, 77, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'GST 405 · Computer Studies', 'Telemedicine allows:', '["Paper records only, without any computers", "Remote consultation using communication technology", "Only face-to-face visits in the outpatient clinic", "Surgery to be done without a surgeon present"]'::jsonb, 1, 'It increases access to specialists.', 'GST 405 · Computer Studies'),
(6, 78, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'GST 405 · Computer Studies', 'Data backup is important because it:', '["Wastes storage space", "Slows the computer down", "Protects against data loss", "Is not necessary at all"]'::jsonb, 2, 'Backups should be regular and secure.', 'GST 405 · Computer Studies'),
(6, 79, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'GST 405 · Computer Studies', 'RAM in a computer stands for:', '["Read And Modify", "Remote Access Module", "Rapid Access Machine", "Random Access Memory"]'::jsonb, 3, 'RAM is temporary working memory.', 'GST 405 · Computer Studies'),
(6, 80, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'GST 405 · Computer Studies', 'A barcode scanning system in theatre helps to:', '["Track instruments, implants and drugs accurately", "Increase errors by adding extra steps to the work", "Replace the need for swab and instrument counts", "Avoid any documentation of implants and drugs"]'::jsonb, 0, 'It supports traceability.', 'GST 405 · Computer Studies'),
(6, 81, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'GST 401 · Behavioural Science', 'Preoperative anxiety can be reduced by:', '["Withholding information about surgery", "Ignoring the patient until induction", "Shouting instructions so they are heard", "Information, listening and reassurance"]'::jsonb, 3, 'Anxiety increases pain and anaesthetic requirements.', 'GST 401 · Behavioural Science'),
(6, 82, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'GST 401 · Behavioural Science', 'A defence mechanism in which a patient refuses to accept a diagnosis is:', '["Regression", "Sublimation", "Projection", "Denial"]'::jsonb, 3, 'Nurses allow time and provide support.', 'GST 401 · Behavioural Science'),
(6, 83, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'GST 401 · Behavioural Science', 'Regression is when a patient:', '["Becomes more mature and independent", "Returns to behaviour of an earlier stage", "Channels feelings into useful activity", "Blames other people for own feelings"]'::jsonb, 1, 'Common in children and stressed adults.', 'GST 401 · Behavioural Science'),
(6, 84, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'GST 401 · Behavioural Science', 'Culture influences perioperative care because:', '["All patients share exactly the same beliefs", "Only the surgeons'' culture affects patient care", "Beliefs about illness, blood, pain and modesty differ", "Culture has no effect on care in the theatre"]'::jsonb, 2, 'Culturally sensitive care improves trust.', 'GST 401 · Behavioural Science'),
(6, 85, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'GST 401 · Behavioural Science', 'Body image changes after surgery such as mastectomy or stoma may cause:', '["Grief, low self-esteem and depression", "Improved mood and confidence only", "Increased self-esteem in every case", "No emotional effect at all"]'::jsonb, 0, 'Counselling and support groups help.', 'GST 401 · Behavioural Science'),
(6, 86, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'GST 401 · Behavioural Science', 'Kubler-Ross''s stages of grief are:', '["Acceptance, denial, anger, depression, bargaining", "Shock, surprise, anger, acceptance, joy", "Anger, denial, depression, acceptance, bargaining", "Denial, anger, bargaining, depression and acceptance"]'::jsonb, 3, 'Not all patients go through every stage in order.', 'GST 401 · Behavioural Science'),
(6, 87, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'GST 401 · Behavioural Science', 'Effective communication with an anxious patient involves:', '["Avoiding eye contact to reduce tension", "Using medical jargon to sound expert", "Interrupting the patient to save time", "Active listening, empathy and clear explanation"]'::jsonb, 3, 'Nonverbal cues are important.', 'GST 401 · Behavioural Science'),
(6, 88, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'GST 401 · Behavioural Science', 'Stress in theatre staff can be reduced by:', '["Increasing the workload to build strength", "Teamwork, adequate breaks and support", "Ignoring feelings so work continues", "Blaming others when things go wrong"]'::jsonb, 1, 'Debriefing after critical incidents helps.', 'GST 401 · Behavioural Science'),
(6, 89, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'GST 401 · Behavioural Science', 'Maslow''s self-actualisation refers to:', '["Realising one''s full potential", "Meeting basic bodily needs", "Feeling safe and secure", "Being loved and accepted"]'::jsonb, 0, 'It is the top of the hierarchy.', 'GST 401 · Behavioural Science'),
(6, 90, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'GST 401 · Behavioural Science', 'Socialisation is the process by which:', '["People become isolated from their society", "Hospitals and clinics are built in a community", "Infectious diseases spread through a group", "People learn the norms and values of their group"]'::jsonb, 3, 'Professional socialisation shapes nursing identity.', 'GST 401 · Behavioural Science'),
(6, 91, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'GST 400 · Use of English', 'Choose the correctly spelt word:', '["Anasthesia", "Anesthesier", "Anaesthisia", "Anaesthesia"]'::jsonb, 3, 'British spelling ''anaesthesia'' is used in Nigeria; American spelling is ''anesthesia''.', 'GST 400 · Use of English'),
(6, 92, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'GST 400 · Use of English', 'The plural of ''criterion'' is:', '["Criterias", "Criterium", "Criterions", "Criteria"]'::jsonb, 3, 'Similarly, ''phenomenon'' becomes ''phenomena''.', 'GST 400 · Use of English'),
(6, 93, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'GST 400 · Use of English', 'Choose the correct sentence:', '["The patient dressing''s was changed by the nurse.", "The patient''s dressing was changed by the nurse.", "The patients dressing were changed by the nurse.", "The patients'' dressing were changed by nurse."]'::jsonb, 1, 'A singular possessive uses ''s; the verb agrees with ''dressing''.', 'GST 400 · Use of English'),
(6, 94, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'GST 400 · Use of English', 'The word ''post-operative'' means:', '["Without surgery", "After surgery", "During surgery", "Before surgery"]'::jsonb, 1, '''Pre'' means before and ''intra'' means during.', 'GST 400 · Use of English'),
(6, 95, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'GST 400 · Use of English', 'Choose the word closest in meaning to ''deteriorate'':', '["Improve", "Recover", "Stabilise", "Worsen"]'::jsonb, 3, 'Accurate vocabulary is needed for clear clinical reports.', 'GST 400 · Use of English'),
(6, 96, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'GST 400 · Use of English', 'The suffix ''-ectomy'' means:', '["Surgical removal", "Inflammation", "Surgical opening", "Repair"]'::jsonb, 0, '''-otomy'' means incision; ''-itis'' means inflammation; ''-plasty'' means repair.', 'GST 400 · Use of English'),
(6, 97, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'GST 400 · Use of English', 'Choose the correct form: ''Neither the surgeon nor the nurses ___ ready.''', '["were", "be", "was", "is"]'::jsonb, 0, 'With ''neither...nor'', the verb agrees with the nearer subject (nurses, plural).', 'GST 400 · Use of English'),
(6, 98, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'GST 400 · Use of English', 'A ''summary'' should be:', '["Brief, with only the main points", "Written without understanding", "Longer than the original text", "Full of examples and details"]'::jsonb, 0, 'Summaries are used in handovers and reports.', 'GST 400 · Use of English'),
(6, 99, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'GST 400 · Use of English', 'Choose the correct preposition: ''The patient was allergic ___ penicillin.''', '["to", "from", "with", "for"]'::jsonb, 0, '''Allergic to'' is the correct collocation.', 'GST 400 · Use of English'),
(6, 100, 'Perioperative Mock — Day 2 Night (Nov 2026)', 'GST 400 · Use of English', 'Which is an example of formal written communication in a hospital?', '["An incident report", "A text to a friend", "A personal diary", "A social media post"]'::jsonb, 0, 'Formal reports must be factual, objective and clear.', 'GST 400 · Use of English');
